TURATH_CHUNK(12,[{"num":2400,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا تَمْنَعُوا إِمَاءَ اللَّهِ مَسَاجِدَ اللَّهِ، وَلْيَخْرُجْنَ تَفِلَاتٍ.","قَالَتْ عَائِشَةَ: وَلَوْ رَاى حَالَهُنَّ الْيَوْمَ مَنَعَهنَّ."],"takhrij":"حسن: رواه الإمام أحمد (24406) قال: حدثنا الحكم، حدثنا عبدالرحمن بن أبي الرجال، قال أبي يذكره عن أمه، عن عائشة فذكرت.","grade":"حسن","chapter_ar":"باب خروج النساء لحضور الجماعات في المساجد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Good\nAhmad (24406)","chapter_en":"Women going out to attend congregational prayers in the mosques","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":18,"content":{"translation":{"en":["‘A’ishah narrated from the Prophet ﷺ that he said: “Do not prevent the female servants of Allah from the mosques of Allah; and let them go out unperfumed.” ‘A’ishah said: “If he had seen their condition today, he would have prevented them.”"]},"buhuth":{"en":["As for ‘A’ishah’s statement, it is narrated by both major collections: Malik reported it from Yahya ibn Sa‘id from ‘Amrah bint ‘Abd al-Rahman from ‘A’ishah, that she said: “If the Messenger of Allah ﷺ had lived to see what women have introduced, he would have prevented them from the mosques, just as the women of the Children of Israel were prevented.” Yahya said: I asked ‘Amrah: “Were the women of the Children of Israel prevented from the mosques?” She said: “Yes.” It is also reported by al-Bukhari and Muslim.","Her phrase “what women have introduced” refers to adornment, perfume, and fine clothing."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (24406)."},{"num":2401,"demo":false,"sanad":"","matn":["عَنْ زَيْنَبَ الثقفية عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا شهدَتْ إِحْدَاكُنَّ الْعِشَاءَ فَلَا تطيَّبْ تِلْكَ اللَّيْلَةَ ."],"takhrij":"صحيح: رواه مسلم في الصلاة (443) من طريق ابن وهب، أخبرني مخرمة، عن أبيه بكير بن عبدالله بن الأشج، عن بُسْر بن سعيد، عن زينب فذكرته.","grade":"صحيح","chapter_ar":"باب النّهي للمرأة أن تشهد الصّلاة إذا أصابتٌ من البخور","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (443)","chapter_en":"Prohibiting a woman from attending prayer if she has applied incense/perfume","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":19,"content":{"translation":{"en":["Zaynab al-Thaqafiyyah narrated from the Messenger of Allah ﷺ that he said: “If one of you attends the ‘Isha prayer, then let her not apply perfume that night.”"]},"buhuth":{"en":["In another narration: The Messenger of Allah ﷺ said to us: “If one of you attends the mosque, then let her not touch perfume.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (443). وفي رواية قال لنا رسول الله ﷺ: (( إذا شهدت إحداكن المسجد فلا تمس طيبا))."},{"num":2402,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  أَيُّمَا امْرَأَةٍ أَصَابَتْ بَخُورًا فَلَا تَشْهَدْ مَعَنَا الْعِشَاءَ الْآخِرَةَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (444) عن يحيى بن يحيى وإسحاق بن إبراهيم، قال يحيى: أخبرنا عبدالله بن محمد بن عبدالله بن أبي فروة، عن يزيد ابن خُصيفة، عن بُسْر بن سعيد، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النّهي للمرأة أن تشهد الصّلاة إذا أصابتٌ من البخور","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (444)","chapter_en":"Prohibiting a woman from attending prayer if she has applied incense/perfume","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":19,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Any woman who has applied incense/perfume should not attend the ‘Isha (late-night) prayer with us.”"]}},"tuhfa":{},"full":1,"rep":[15572],"tks":"صحيح: رواه مسلم (444)."},{"num":2403,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَيُّمَا امْرَأَةٍ تَطَيَّبَتْ، ثُمَّ خَرَجَتْ إِلَى الْمَسْجِدِ، لَمْ تُقبلْ لَهَا صَلاَةٌ حَتَّى تَغْتَسِلَ غُسْلَها من الْجَنَابَةِ ."],"takhrij":"حسن: رواه أبو داود (4174)، وابن ماجة (4002) كلاهما من طريق سفيان بن عُيينة، عن عاصم بن عبيدالله، عن عبيد مولى أبي رُهْم، عن أبي هريرة قال: لقيتْه امرأةٌ وجد منها ريحَ الطيب يَنْفَحُ، لذيلها إعصار فقال: يا أمةَ الجبَّار، جئتِ من المسجد؟ قالت: نعم، قال: وله تطيبتِ؟ قالت: نعم، قال: إني سمعت حِبِّى أبا القاسم يقول: فذكر الحديث. واللفظ لأبي داود.","grade":"حسن","chapter_ar":"باب النّهي للمرأة أن تشهد الصّلاة إذا أصابتٌ من البخور","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Good due to supporting narrations\nAbu Dawud (4174) (wording his); Ibn Majah (4002); al-Bayhaqi (3/133)","chapter_en":"Prohibiting a woman from attending prayer if she has applied incense/perfume","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":19,"content":{"translation":{"en":["Abu Hurayrah said: I heard the Messenger of Allah ﷺ say: “Any woman who perfumes herself and then goes out to the mosque—her prayer will not be accepted until she bathes as she bathes from major ritual impurity.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4174) (واللفظ له)، ابن ماجه (4002)، البيهقي (3/133)."},{"num":2404,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا اسْتَعْطَرَتِ الْمَرْأَةُ فَمَرَّتْ عَلَى الْقَوْمِ لِيَجِدُوا رِيحَهَا فَهِيَ كَذَا وَكَذَا. قَالَ قَوْلاً شَدِيدًا."],"takhrij":"حسن: رواه أبو داود (4173) عن مسدد، حدثنا يحيى (ابن سعيد) أخبرنا ثابت بن عمارة، حدثني غنيم بن قيس، عن أبي موسى فذكره.","grade":"حسن","chapter_ar":"باب النّهي للمرأة أن تشهد الصّلاة إذا أصابتٌ من البخور","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (4173); al-Tirmidhi (2786); al-Nasa’i (5126)","chapter_en":"Prohibiting a woman from attending prayer if she has applied incense/perfume","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":19,"content":{"translation":{"en":["Abu Musa narrated from the Prophet ﷺ: “If a woman applies fragrance and passes by people so they can smell her scent, then she is such-and-such,” and he spoke very sternly."]},"buhuth":{"en":["Al-Tirmidhi’s wording includes: “Every eye commits adultery, and if a woman applies fragrance and passes by a gathering, then she is such-and-such,” meaning: like an adulteress (a severe warning). Al-Nasa’i’s wording is explicit: “Any woman who applies fragrance and passes by people so they smell it—she is an adulteress,” meaning: she is threatened with a warning like that."]}},"tuhfa":{},"full":1,"dr":1,"rep":[15571],"tks":"حسن: رواه أبو داود (4173). ورواه الترمذي (2786) ولفظه: (( كل عين زانية، والمرأة إذا استعطرت فمرت بالمجلس فهي كذا وكذا )) يعني زانية. قال الترمذي: حسن صحيح."},{"num":2405,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: صَلاَةُ الْمَرْأَةِ فِي بَيْتِهَا أَفْضَلُ مِنْ صَلاَتِهَا فِي حُجْرَتِهَا، وَصَلاَتُهَا فِي مَخْدَعِها أَفْضَلُ مِنْ صَلاَتِهَا فِي بَيْتِهَا ."],"takhrij":"حسن: رواه أبو داود (570) عن ابن المثنى، أن عمرو بن عاصم حدثهم قال: حدثنا همام، عن قتادة، عن مورِّق، عن أبي الأحوص، عن عبدالله بن مسعود فذكره.","grade":"حسن","chapter_ar":"باب صلاة المرأة في بيتها أفضل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (570); al-Hakim (1/209); Ibn Khuzaymah (1690) (authenticated)","chapter_en":"A woman’s prayer in her home is better","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":20,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud narrated from the Prophet ﷺ: “A woman’s prayer in her private room is better than her prayer in the courtyard of her home, and her prayer in her inner chamber is better than her prayer in her private room.”"]},"buhuth":{"en":["Related wordings mention: “The woman is ‘awrah; when she goes out, Satan seeks to entice attention to her; and she is closest to the Face of her Lord when she is in the deepest part of her home.” Al-Tirmidhi narrated part of that wording and graded it “good, singular.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (570) والحاكم (757) وصححه أيضا ابن خزيمة (1690)."},{"num":2406,"demo":false,"sanad":"","matn":["وَعَنِ ابْنِ عُمَرَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْمَرْأَةُ عَوْرَةٌ، وَإِنَّهَا إِذَا خَرَجَتْ مِنْ بَيْتِهَا اسْتَشْرَفَهَا الشَّيْطَانُ، وَإِنَّهَا لَا تَكُونُ أَقْرَبَ إِلَى اللَّهِ مِنْهَا فِي قَعْرِ بَيْتِهَا."],"takhrij":"حسن: رواه الطبراني في الأوسط –مجمع البحرين (2322) عن إبراهيم (هو ابن هاشم البغوي)، أخبرنا عاصم بن النضر، أنا معتمر بن سليمان، عن أبيه، عن قتادةن عن سالم بن عبدالله، عن أبيه قال: فذكره.","grade":"حسن","chapter_ar":"باب صلاة المرأة في بيتها أفضل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan","chapter_en":"A woman’s prayer in her home is better","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":20,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar narrated from the Messenger of Allah ﷺ: “A woman is ‘awrah. When she goes out, Satan seeks to draw attention to her. And she is not closer to Allah than when she is in the deepest part of her home.”"]},"buhuth":{"en":["al-Tabarani in al-Awsat (Majma‘ al-Bahrayn 2322)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (مجمع البحرين 2322)."},{"num":2407,"demo":false,"sanad":"","matn":["عن أُمِّ حُميد امرأة أَبِي حُمَيْدٍ الساعدي أَنَّهَا جَاءَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنِّي أُحِبُّ الصَّلَاةَ مَعَكَ، قَالَ: قَدْ عَلِمْتُ أَنَّكِ تُحِبِّينَ الصَّلَاةَ مَعِي، وَصَلَاتُكِ فِي بَيْتِكِ خَيْرٌ لَكِ مِنْ صَلَاتِكِ فِي حُجْرَتِكِ، وَصَلَاتُكِ فِي حُجْرَتِكِ خَيْرٌ مِنْ صَلَاتِكِ فِي دَارِكِ، وَصَلَاتُكِ فِي دَارِكِ خَيْرٌ لَكِ مِنْ صَلَاتِكِ فِي مَسْجِدِ قَوْمِكِ، وَصَلَاتُكِ فِي مَسْجِدِ قَوْمِكِ خَيْرٌ لَكِ مِنْ صَلَاتِكِ فِي مَسْجِدِي.","قَالَ: فَأَمَرَتْ فَبُنِيَ لَهَا مَسْجِدٌ فِي أَقْصَى شَيْءٍ مِنْ بَيْتِهَا وَأَظْلَمِهِ، فَكَانَتْ تُصَلِّي فِيهِ حَتَّى لَقِيَتِ اللهَ عزوجل."],"takhrij":"حسن: رواه أحمد (27090) عن هارون (بن معروف)، حدثنا عبدالله بن وهب، قال: حدثني داود بن قيس، عن عبدالله بن سويد الأنصاري، عن عمته أم حُميد فذكرت مثله.","grade":"حسن","chapter_ar":"باب صلاة المرأة في بيتها أفضل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (27090); Ibn Khuzaymah (1689); Ibn Hibban (2217); Ibn Abi Shaybah (2/384)","chapter_en":"A woman’s prayer in her home is better","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":20,"content":{"translation":{"en":["Umm Humayd, the wife of Abu Humayd al-Sa‘idi, came to the Prophet ﷺ and said: “O Messenger of Allah ﷺ, I love praying with you.” He said: “I know you love praying with me. But your prayer in your private room is better for you than your prayer in the courtyard of your home; your prayer in the courtyard of your home is better than your prayer elsewhere within your residence; your prayer within your residence is better for you than your prayer in the mosque of your people; and your prayer in the mosque of your people is better than your prayer in my mosque.” She then ordered that a prayer-place be built for her in the furthest and darkest part of her home, and she used to pray there until she met Allah, Mighty and Majestic."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (27090)، ابن خزيمة (1689)، ابن حبان (2217)، ابن أبي شيبة (2/384)."},{"num":2408,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: خَيْرُ مَسَاجِدِ النِّسَاءِ قَعْرُ بُيُوتِهِنَّ."],"takhrij":"حسن: رواه أحمد (26542، 6575)، وأبو يعلى (7025)، والطبراني في الكبير (23/(709 ، وابن خزيمة (1683)، والحاكم (756)، والبيهقي (5360) كلهم من طرق عن السائب مولى أم سلمة، عن أم سلمة.","grade":"حسن","chapter_ar":"باب صلاة المرأة في بيتها أفضل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Good due to supporting narrations\nAhmad (26542); Abu Ya‘la (7025); al-Tabarani (al-Kabir 23/709); Ibn Khuzaymah (1683); al-Hakim (756); al-Bayhaqi (3/131)","chapter_en":"A woman’s prayer in her home is better","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الجماعة","group_en":"Collected Chapters on Congregational Prayer","part_no":9,"group_no":8,"chapter_no":20,"content":{"translation":{"en":["Umm Salamah narrated that the Messenger of Allah ﷺ said: “The best mosques for women are the deepest parts of their homes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (26542)، أبو يعلى (7025)، الطبراني في الكبير (23/709)، ابن خزيمة (1683)، الحاكم (756)، البيهقي (5360)."},{"num":2409,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ اللَّهَ قَالَ: مَنْ عَادَى لِي وَلِيًّا فَقَدْ آذَنْتُهُ بِالْحَرْبِ، وَمَا تَقَرَّبَ إِلَىَّ عَبْدِي بِشَىْءٍ أَحَبَّ إِلَىَّ مِمَّا افْتَرَضْتُ عَلَيْهِ، وَمَا يَزَالُ عَبْدِي يَتَقَرَّبُ إِلَىَّ بِالنَّوَافِلِ حَتَّى أُحِبَّهُ، فَإِذَا أَحْبَبْتُهُ كُنْتُ سَمْعَهُ الَّذِي يَسْمَعُ بِهِ، وَبَصَرَهُ الَّذِي يُبْصِرُ بِهِ، وَيَدَهُ الَّتِي يَبْطُشُ بِهَا، وَرِجْلَهُ الَّتِي يَمْشِي بِهَا، وَإِنْ سَأَلَنِي لأُعْطِيَنَّهُ، وَلَئِنِ اسْتَعَاذَنِي لأُعِيذَنَّهُ، وَمَا تَرَدَّدْتُ عَنْ شَىْءٍ أَنَا فَاعِلُهُ تَرَدُّدِي عَنْ نَفْسِ الْمُؤْمِنِ، يَكْرَهُ الْمَوْتَ، وَأَنَا أَكْرَهُ مَسَاءَتَهُ."],"takhrij":"صحيح: رواه البخاري في الرقاق (6502) عن محمد بن عثمان، حدثنا خالد ابن مَخْلد، حدثنا سليمان بن بلال، حدثني شريك بن عبد بن أبي نمر، عن عطاء، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل النوافل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (6502)","chapter_en":"What has been narrated about the virtue of voluntary prayers","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Allah said: ‘Whoever shows hostility to a close servant of Mine, I have declared war upon him. My servant does not draw near to Me with anything more beloved to Me than what I have made obligatory upon him. And My servant continues drawing near to Me through voluntary deeds until I love him. When I love him, I become his hearing with which he hears, his sight with which he sees, his hand with which he strikes, and his foot with which he walks. If he asks Me, I will surely give him; and if he seeks refuge in Me, I will surely grant him refuge. I do not hesitate about anything I am going to do like My hesitation over taking the soul of the believing servant: he dislikes death, and I dislike hurting him.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[465,13221],"tks":"صحيح: رواه البخاري (6502)."},{"num":2410,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: مَرَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى قَبْرٍ دُفِنَ حَدِيثًا فَقَالَ: رَكْعَتَانِ خَفِيفَتَانِ مِمَّا تَحْقِرُونَ وَتَنْفِلُونَ يَزِيدُهُمَا هَذَا فِي عَمَلِهِ أَحَبُّ إِلَيْهِ مِنْ بَقِيَّةِ دُنْيَاكُمْ."],"takhrij":"حسن: رواه ابن صاعد في زوائده على الزهد لابن المبارك (31)، والطبراني في الأوسط (924)، وأبو نعيم في أخبار أصبهان (2/225) كلهم من طرق عن حفص بن غياث، عن أبي مالك الأشجعي، عن أبي حازم، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في فضل النوافل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Sa‘id in his additions to al-Zuhd of Ibn al-Mubarak (31); al-Tabarani in al-Awsat (924)","chapter_en":"What has been narrated about the virtue of voluntary prayers","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ passed by a grave that had just been buried and said: “Two light units of prayer—of what you consider small and voluntary—added to this person’s deeds would be more beloved to him than the remainder of your worldly life.”"]}},"tuhfa":{},"voc":["zuhdmubarak",31],"full":1,"dr":1,"tks":"حسن: رواه ابن صاعد في زوائده على الزهد لابن المبارك (31)، والطبراني في الأوسط (924)."},{"num":2411,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ ثَابِتٍ قَالَ:  احْتَجَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حُجَيْرَةً بِخَصَفَةٍ أَوْ حَصِيرٍ، فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِيهَا. قَالَ: فَتَتَبَّعَ إِلَيْهِ رِجَالٌ، وَجَاؤُوا يُصَلُّونَ بِصَلَاتِهِ. قَالَ: ثُمَّ جَاؤُوا لَيْلَةً فَحَضَرُوا. وَأَبْطَأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْهُمْ. قَالَ: فَلَمْ يَخْرُجْ إِلَيْهِمْ، فَرَفَعُوا أَصْوَاتَهُمْ، وَحَصَبُوا الْبَابَ، فَخَرَجَ إِلَيْهِمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُغْضَبًا فَقَالَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا زَالَ بِكُمْ صَنِيعُكُمْ حَتَّى ظَنَنْتُ أَنَّهُ سَيُكْتَبُ عَلَيْكُمْ. فَعَلَيْكُمْ بِالصَّلَاةِ فِي بُيُوتِكُمْ، فَإِنَّ خَيْرَ صَلَاةِ الْمَرْءِ فِي بَيْتِهِ إِلَّا الصَّلَاةَ الْمَكْتُوبَةَ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (731)، ومسلم في صلاة المسافرين (781) كلاهما من طريق سالم أبي النضْر مولى عمر بن عبدالله، عن بُسْر بن سعيد، عن زيد بن ثابت فذكره، واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في فضل صلاة التطوع في البيت","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (731); Muslim (781) (wording Muslim’s)","chapter_en":"What has come regarding the virtue of voluntary prayer in the home","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Zayd ibn Thabit said: The Messenger of Allah ﷺ made for himself a small enclosure from palm-leaf mats or a reed mat, and the Messenger of Allah ﷺ went out and prayed inside it. Some men followed him and began praying following his prayer. Then they came one night to attend, but the Messenger of Allah ﷺ stayed back from them and did not come out to them. They raised their voices and threw small pebbles at the door. So the Messenger of Allah ﷺ came out to them angry and said: “You kept doing this until I feared it would be made obligatory upon you. So pray in your houses, for the best prayer of a person is in his house—except for the obligatory prayer.”"]},"buhuth":{"en":["In al-Bukhari’s wording: it was in Ramadan; he prayed in it for nights, some of his companions prayed following him; when he knew that, he began to remain seated (i.e., not come out), then he came out to them and said similarly."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (731)، ومسلم (781)، واللفظ لمسلم. وفي لفظ البخاري: وذلك في رمضان، فصل فيها ليالي، فصلى بصلاته ناس من أصحابه، فلما علم ذلك جعل يقعد، فخرج إليهم فقال، فذكر مثله."},{"num":2412,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: اجْعَلُوا فِي بُيُوتِكُمْ مِنْ صَلاَتِكُمْ، وَلاَ تَتَّخِذُوهَا قُبُورًا."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (432)، ومسلم في صلاة المسافرين (777) كلاهما من حديث يحيى، عن عبدالله، قال: أخبرني نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في فضل صلاة التطوع في البيت","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (432); Muslim (777)","chapter_en":"What has come regarding the virtue of voluntary prayer in the home","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar narrated from the Prophet ﷺ that he said: “Make some of your prayer in your houses, and do not take them as graves.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (432)، ومسلم (777)."},{"num":2413,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  مَثَلُ الْبَيْتِ الَّذِي يُذْكَرُ اللَّهَ فِيهِ، وَالْبَيْتِ الَّذِي لَا يُذْكَرُ اللَّهَ فِيهِ، مَثَلُ الْحَيِّ وَالْمَيِّتِ."],"takhrij":"متفق عليه: رواه البخاري في الدّعوات (6407)، ومسلم في صلاة المسافرين (779) كلاهما عن محمد بن العلاء، حدثنا أبو أسامة، عن بُريد بن عبدالله، عن أبي بُرْدة، عن أبي موسى فذكره واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في فضل صلاة التطوع في البيت","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (6407); Muslim (779) (wording Muslim’s)","chapter_en":"What has come regarding the virtue of voluntary prayer in the home","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Abu Musa al-Ash‘ari narrated from the Prophet ﷺ: “The likeness of the house in which Allah is remembered and the house in which Allah is not remembered is like the living and the dead.”"]},"buhuth":{"en":["Al-Bukhari’s wording: “The one who remembers his Lord and the one who does not remember his Lord are like the living and the dead.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6407)، ومسلم (779) واللفظ لمسلم."},{"num":2414,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَا تَجْعَلُوا بُيُوتَكُمْ مَقَابِرَ. إِنَّ الشَّيْطَانَ يَنْفِرُ مِنَ الْبَيْتِ الَّذِي تُقْرَأُ فِيهِ سُورَةُ الْبَقَرَةِ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (780) عن قتيبة بن سعيد،","grade":"صحيح","chapter_ar":"باب ما جاء في فضل صلاة التطوع في البيت","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (780)","chapter_en":"What has come regarding the virtue of voluntary prayer in the home","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “Do not make your houses into graveyards. Indeed, the devil flees from the house in which Surah al-Baqarah is recited.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11871,12666],"tks":"صحيح: رواه مسلم (780)."},{"num":2415,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِذَا قَضَى أَحَدُكُمُ الصَّلَاةَ فِي مَسْجِدِهِ، فَلْيَجْعَلْ لِبَيْتِهِ نَصِيبًا مِنْ صَلَاتِهِ، فَإِنَّ اللَّهَ جَاعِلٌ فِي بَيْتِهِ مِنْ صَلَاتِهِ خَيْرًا."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (778) عن أبي بكر بن أبي شيبة وغيره عن أبي معاوية، عن الأعمش، عن أبي سفيان، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل صلاة التطوع في البيت","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (778)","chapter_en":"What has come regarding the virtue of voluntary prayer in the home","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “When one of you finishes the prayer in his mosque, let him give his house a share of his prayer, for Allah will place good in his house through his prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (778)."},{"num":2416,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيُّ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا قَضَى أَحَدُكُمْ صَلَاتَهُ فِي الْمَسْجِدِ فَلْيَجْعَلْ لِبَيْتِهِ نَصِيبًا مِنْ صَلَاتِهِ، إِنَّ اللَّهَ جَاعِلٌ فِي بَيْتِهِ مِنْ صَلَاتِهِ خَيْرًا ."],"takhrij":"صحيح: رواه ابن ماجه (1376) عن محمد بن بشار وغيره، عن عبدالرحمن بن مهدي، قال: حدثنا سفيان، عن الأعمش، عن أبي سفيان، عن جابر بن عبدالله، عن أبي سعيد الخدري فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل صلاة التطوع في البيت","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Majah (1376); Ahmad (11567); ‘Abd al-Razzaq (4837); Ibn Khuzaymah (1206) (authenticated)","chapter_en":"What has come regarding the virtue of voluntary prayer in the home","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Abu Sa‘id al-Khudri reported that the Messenger of Allah ﷺ said: “When one of you finishes his prayer in the mosque, let him give his house a share of his prayer. Allah will place good in his house through his prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (1376)، أحمد (11567) وعبد الرزاق (4837)، وصححه ابن خزيمة (1206)."},{"num":2417,"demo":false,"sanad":"","matn":["عَبْدِ اللَّهِ بْنِ سَعْدٍ، قَالَ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَيُّمَا أَفْضَلُ؟ الصَّلاَةُ فِي بَيْتِي أَوِ الصَّلاَةُ فِي الْمَسْجِدِ؟ قَالَ: أَلاَ تَرَى إِلَى بَيْتِي؟ مَا أَقْرَبَهُ مِنَ الْمَسْجِدِ! فَلأَنْ أُصَلِّيَ فِي بَيْتِي أَحَبُّ إِلَىَّ مِنْ أَنْ أُصَلِّيَ فِي الْمَسْجِدِ إِلاَّ أَنْ تَكُونَ صَلاَةً مَكْتُوبَةً."],"takhrij":"حسن: رواه ابن ماجه (1378) عن أبي بشر بكر بن خلف، قال: حدثنا عبدالرحمن بن مهدي، عن معاوية بن صالح، عن العلاء بن الحارث، عن حرام بن حكيم، عن عمه عبدالله بن سعد فذكر مثله وأخرجه ابن خزيمة (1202) من طريق عبدالرحمن به مثله. وسبق ذكر هذا الإسناد في كتاب الحيض باب مؤكلة الحائض وسؤرها.","grade":"حسن","chapter_ar":"باب ما جاء في فضل صلاة التطوع في البيت","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Majah (1378); Ibn Khuzaymah (1202)","chapter_en":"What has come regarding the virtue of voluntary prayer in the home","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["‘Abdullah ibn Sa‘d said: I asked the Messenger of Allah ﷺ: “Which is better: praying in my house or praying in the mosque?” He said: “Do you not see my house—how close it is to the mosque? Yet for me to pray in my house is more beloved to me than praying in the mosque, unless it is an obligatory prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1378) وابن خزيمة (1202)."},{"num":2418,"demo":false,"sanad":"","matn":["عَنْ مَحْمُودِ بْنِ لَبِيدٍ، أَخِي بَنِي عَبْدِ الْأَشْهَلِ، قَالَ: أَتَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى بِنَا الْمَغْرِبَ فِي مَسْجِدِنَا. فَلَمَّا سَلَّمَ مِنْهَا قَالَ: ارْكَعُوا هَاتَيْنِ الرَّكْعَتَيْنِ فِي بُيُوتِكُمْ لِلسُّبْحَةِ بَعْدَ الْمَغْرِبِ."],"takhrij":"حسن: رواه أحمد (23624) عن يعقوب، حدثنا أبي، عن ابن إسحاق، حدثني عاصم بن عمر بن قتادة الأنصاري، عن محمود بن لبيد فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في فضل صلاة التطوع في البيت","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (23624); Ibn Khuzaymah (1200); Ibn Majah (1165)","chapter_en":"What has come regarding the virtue of voluntary prayer in the home","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Mahmud ibn Labid, the brother (in alliance) of Banu ‘Abd al-Ashhal, said: The Messenger of Allah ﷺ came to us and led us in the sunset prayer in our mosque. When he finished and gave the closing salutation, he said: “Pray these two units in your homes,” referring to the voluntary prayer after the sunset prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (23624)، وابن خزيمة (1200)، وابن ماجه (1165)."},{"num":2419,"demo":false,"sanad":"","matn":["عن أُمِّ حَبِيبَةَ تَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  مَنْ صَلَّى اثْنَتَيْ عَشْرَةَ رَكْعَةً فِي يَوْمٍ وَلَيْلَةٍ بُنِيَ لَهُ بِهِنَّ بَيْتٌ فِي الْجَنَّةِ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (728) عن محمد بن عبدالله بن نُمير، حدثنا أبو خالد (سليمان بن حيَّان) عن داود بن أبي هند، عن النعمان بن سالم، عن عمرو بن أوس، قال: حدثني عَنْبَسةُ بن أبي سفيان في مرضه الذي مات فيه بحديث يُتَسارُّ إليه قال: سمعت أم حبيبة تقول، فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب في المحافظة على سنن الرواتب قبل الصلوات المفروضة وبعدها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (728)","chapter_en":"Maintaining the regular sunnah prayers before and after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":3,"content":{"translation":{"en":["Umm Habibah said: I heard the Messenger of Allah ﷺ say: “Whoever prays twelve units of prayer in a day and night, a house will be built for him in Paradise because of them.”"]},"buhuth":{"en":["al-Tirmidhi (415) mentions: four before the noon prayer, two after it, two after the sunset prayer, two after the night prayer, and two before the dawn prayer; and he graded it “good and authentic.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (728)."},{"num":2420,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن شَقِيقٍ قَالَ: سَأَلْتُ عَائِشَةَ عَنْ صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ تَطَوُّعِهِ، فَقَالَتْ: كَانَ يُصَلِّي فِي بَيْتِي قَبْلَ الظُّهْرِ أَرْبَعًا، ثُمَّ يَخْرُجُ فَيُصَلِّي بِالنَّاسِ، ثُمَّ يَدْخُلُ فَيُصَلِّي رَكْعَتَيْنِ، وَكَانَ يُصَلِّي بِالنَّاسِ الْمَغْرِبَ، ثُمَّ يَدْخُلُ فَيُصَلِّي رَكْعَتَيْنِ، وَيُصَلِّي بِالنَّاسِ الْعِشَاءَ، وَيَدْخُلُ بَيْتِي فَيُصَلِّي رَكْعَتَيْنِ، وَكَانَ يُصَلِّي مِنَ اللَّيْلِ تِسْعَ رَكَعَاتٍ فِيهِنَّ الْوِتْرُ، وَكَانَ يُصَلِّي لَيْلًا طَوِيلًا قَائِمًا، وَلَيْلًا طَوِيلًا قَاعِدًا، وَكَانَ إِذَا قَرَأَ وَهُوَ قَائِمٌ رَكَعَ وَسَجَدَ وَهُوَ قَائِمٌ، وَإِذَا قَرَأَ قَاعِدًا رَكَعَ وَسَجَدَ وَهُوَ قَاعِدٌ، وَكَانَ إِذَا طَلَعَ الْفَجْرُ صَلَّى رَكْعَتَيْنِ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (730) عن يحيى بن يحيى، قال: أخبرنا هُشيم، عن خالد، عن عبدالله بن شقيق فذكره، ورواه البخاري في التهجد (1182) عن مسدد، قال حدثنا يحيى، عن شعبة، عن إبراهيم بن محمد بن المنتشر، عن أبيه، عن عائشة، أن النبي صلى الله عليه وسلم كان لا يدع أربعا قبل الظهر وركعتين قبل الغداة.","grade":"صحيح","chapter_ar":"باب في المحافظة على سنن الرواتب قبل الصلوات المفروضة وبعدها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (730); al-Bukhari (1182) with the wording that the Prophet ﷺ did not leave four before the noon prayer and two before the dawn prayer.","chapter_en":"Maintaining the regular sunnah prayers before and after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":3,"content":{"translation":{"en":["‘Abdullah ibn Shaqiq said: I asked ‘A’ishah about the prayer of the Messenger of Allah ﷺ regarding his voluntary prayers. She said: He would pray four units in my house before the noon prayer, then he would go out and lead the people, then he would return and pray two units. He would lead the people in the sunset prayer, then return and pray two units. He would lead the people in the night prayer, then enter my house and pray two units. He would pray at night nine units including the witr prayer. He would sometimes pray a long portion of the night standing, and a long portion sitting. If he recited while standing, he bowed and prostrated while standing; and if he recited while sitting, he bowed and prostrated while sitting. And when dawn broke, he prayed two units."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (730)، ورواه البخاري (1182) بلفظ: أن النبي ﷺ كان لا يدع أربعا قبل الظهر وركعتين قبل الغداة."},{"num":2421,"demo":false,"sanad":"","matn":["عن أَبِي مُوسَى الأشعري، عَنْ أَبِيهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ صَلَّى فِي يَوْمٍ وَلَيْلَةٍ ثِنْتَيْ عَشَرَ رَكْعَةً سِوَى الْفَرِيضَةِ، بُنِيَ لَهُ بَيْتٌ فِي الْجَنَّةِ."],"takhrij":"حسن: رواه الإمام أحمد (19709) والطبراني في الأوسط (9432) والبزار -كشف الأستار (702) كلهم من طريق حماد بن زيد، عن هارون أبي إسحاق الكوفي من همدان، عن أبي بردة بن أبي موسى، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب في المحافظة على سنن الرواتب قبل الصلوات المفروضة وبعدها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (19709); al-Tabarani in al-Awsat (9432); al-Bazzar (Kashf al-Astar 702)","chapter_en":"Maintaining the regular sunnah prayers before and after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":3,"content":{"translation":{"en":["Abu Musa al-Ash‘ari said: The Messenger of Allah ﷺ said: “Whoever prays twelve units in a day and night besides the obligatory prayer, a house will be built for him in Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (19709) والطبراني في الأوسط (9432) والبزار - كشف الأستار (702)."},{"num":2422,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي قَبْلَ الظُّهْرِ رَكْعَتَيْنِ، وَبَعْدَهَا رَكْعَتَيْنِ، وَبَعْدَ الْمَغْرِبِ رَكْعَتَيْنِ فِي بَيْتِهِ، وَبَعْدَ الْعِشَاءِ رَكْعَتَيْنِ، وَكَانَ لاَ يُصَلِّي بَعْدَ الْجُمُعَةِ حَتَّى يَنْصَرِفَ فيركع رَكْعَتَيْنِ."],"takhrij":"متفق عليه: رواه مالك في قصر الصلاة (69) عن نافع، عن ابن عمر، والبخاري في الجمعة (937) عن عبدالله بن يوسف، عن مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب في المحافظة على سنن الرواتب قبل الصلوات المفروضة وبعدها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nMalik (69); al-Bukhari (937); Muslim (729)","chapter_en":"Maintaining the regular sunnah prayers before and after the obligatory prayers","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":3,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ used to pray two units before the noon prayer and two units after it; and two units after the sunset prayer in his home; and two units after the night prayer; and he would not pray after the Friday prayer until he left, then he would pray two units."]},"buhuth":{"en":["Muslim’s wording includes: “As for Maghrib, ‘Isha, and Jumu‘ah, I prayed them with the Prophet ﷺ in his house.”","Ibn ‘Umar’s statement that the Prophet ﷺ prayed two units before the noon prayer may indicate that he did that sometimes; otherwise, what appears most common is that he prayed four units in the home before the noon prayer, as the Mother of the Believers ‘A’ishah reported—and she is more knowledgeable about the Prophet ﷺ’s prayer in his home."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (69)، والبخاري (937)، ورواه مسلم (729) وفيه: فأما المغرب والعشاء والجمعة فصليت مع النبي ﷺ في بيته."},{"num":2423,"demo":false,"sanad":"","matn":["عَنْ عَاصِمِ بْنِ ضَمْرَةَ السَّلُولِيِّ، قَالَ: سَأَلْنَا عَلِيًّا عَنْ تَطَوُّعِ، رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالنَّهَارِ فَقَالَ: إِنَّكُمْ لاَ تُطِيقُونَهُ، فَقُلْنَا: أَخْبِرْنَا بِهِ نَأْخُذْ مِنْهُ مَا اسْتَطَعْنَا. قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى الْفَجْرَ يُمْهِلُ، حَتَّى إِذَا كَانَتِ الشَّمْسُ مِنْ هَاهُنَا، - يَعْنِي مِنْ قِبَلِ الْمَشْرِقِ - بِمِقْدَارِهَا مِنْ صَلاَةِ الْعَصْرِ مِنْ هَا هُنَا - يَعْنِي مِنْ قِبَلِ الْمَغْرِبِ، - قَامَ فَصَلَّى رَكْعَتَيْنِ. ثُمَّ يُمْهِلُ حَتَّى إِذَا كَانَتِ الشَّمْسُ مِنْ هَا هُنَا - يَعْنِي مِنْ قِبَلِ الْمَشْرِقِ - مِقْدَارَهَا مِنْ صَلاَةِ الظُّهْرِ مِنْ هَا هُنَا قَامَ فَصَلَّى أَرْبَعًا. وَأَرْبَعًا قَبْلَ الظُّهْرِ إِذَا زَالَتِ الشَّمْسُ. وَرَكْعَتَيْنِ بَعْدَهَا. وَأَرْبَعًا قَبْلَ الْعَصْرِ. يَفْصِلُ بَيْنَ كُلِّ رَكْعَتَيْنِ بِالتَّسْلِيمِ عَلَى الْمَلاَئِكَةِ الْمُقَرَّبِينَ وَالنَّبِيِّينَ. وَمَنْ تَبِعَهُمْ مِنَ الْمُسْلِمِينَ وَالْمُؤْمِنِينَ.","قال عَلِيٌّ: فتلك سِتَّ عشرة ركعةً، تطوُّعُ رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بالنهار، وقَلَّ من يداومُ عليها.","قَالَ وَكِيعٌ، زَادَ فِيهِ أَبِي: فَقَالَ حَبِيبُ بْنُ أَبِي ثَابِتٍ، يَا أَبَا إِسْحَاقَ! مَا أُحِبُّ أَنَّ لِي بِحَدِيثِكَ هَذَا مِلْءَ مَسْجِدِكَ هَذَا ذَهَبًا."],"takhrij":"حسن: رواه ابن ماجه (1161) عن علي بن محمد، قال: حدثنا وكيع، قال: حدثنا سفيان وأبي وإسرائيل، عن أبي إسحاق، عن عاصم بن ضمْرة السلولي فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من تطوع النبي بالنهار","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Majah (1161); al-Tirmidhi (598) (graded it good); al-Nasa’i (874); Abu Dawud (1272)","chapter_en":"What has come regarding the Prophet ﷺ’s voluntary prayers during the daytime","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":4,"content":{"translation":{"en":["‘Asim ibn Damrah al-Sululi said: We asked ‘Ali about the voluntary prayers of the Messenger of Allah ﷺ during the day. He said: “You will not be able to keep up with it.” We said: “Tell us about it so we can take from it what we are able.” He said: The Messenger of Allah ﷺ would, after praying the dawn prayer, pause until the sun was at a position from the east equivalent to its position for the late-afternoon prayer from the west; then he would stand and pray two units. Then he would pause until the sun was at a position from the east equivalent to its position for the noon prayer; then he would stand and pray four units. He would pray four units before the noon prayer when the sun passed its zenith, and two units after it; and four units before the late-afternoon prayer—separating every two units with the closing salutation, greeting the near angels, the prophets, and those who followed them among the Muslims and believers. ‘Ali said: “That is sixteen units— the Messenger of Allah ﷺ’s voluntary prayer in the daytime— and few people persist in it.” Waki‘ said: My father added: Habib ibn Abi Thabit said, “O Abu Ishaq, I would not like to have, in exchange for this report of yours, a mosque filled with gold.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1161)، والترمذي (598) وحسنه، والنسائي (874)، وأبو داود (1272)."},{"num":2424,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَمْ يَكُنِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى شَىْءٍ مِنَ النَّوَافِلِ أَشَدَّ مِنْهُ تَعَاهُدًا عَلَى رَكْعَتَىِ الْفَجْرِ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1169)، ومسلم في المسافرين (724/94) كلاهما من طريق يحيى بن سعيد، عن ابن جريج، قال: حدثني عطاء، عن عبيد بن عمير، عن عائشة فذكرت.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تأكيد ركعتي الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (1169); Muslim (94/724)","chapter_en":"Emphasizing the two units before the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":5,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: The Prophet ﷺ was not more consistent with any voluntary prayer than he was with the two units before the dawn prayer."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13411],"tks":"متفق عليه: رواه البخاري (1169)، ومسلم (724/94)."},{"num":2425,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  رَكْعَتَا الْفَجْرِ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا."],"takhrij":"صحيح: رواه مسلم في المسافرين (725) من طريق أبي عوانة، عن قتادة، عن زُرَارة بن أوفى، عن سعد بن هشام، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في تأكيد ركعتي الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (725)","chapter_en":"Emphasizing the two units before the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":5,"content":{"translation":{"en":["‘A’ishah narrated that the Prophet ﷺ said: “The two units before the dawn prayer are better than the world and everything in it.” In another narration: “They are more beloved to me than the entire world.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13410],"tks":"صحيح: رواه مسلم (725). وفي رواية: (( لهما أحب إلي من الدنيا جميعا))."},{"num":2426,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ زَادَكُمْ صَلَاةً إِلَى صَلَاتِكُمْ هِيَ خَيْرٌ لَكُمْ مِنْ حُمْرِ النَّعَمِ، أَلَا وَهِيَ الرَّكْعَتَانِ قَبْلَ صَلَاةِ الْفَجْرِ."],"takhrij":"حسن: رواه البيهقي (4463) عن أبي عبد الله الحافظ (هو الحاكم)، حدثني أبو الحسن أحمد بن جناح الكشاني، ثنا عمر بن محمد بن بجير، ثنا العباس بن الوليد الخلال، ثنا مروان بن محمد الدمشقي، ثنا معاوية بن سلام، عن يحيى بن أبي كثير، عن أبي نضرة العبدي، عن أبي سعيد الخدري قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تأكيد ركعتي الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Bayhaqi (2/469)","chapter_en":"Emphasizing the two units before the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":5,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: The Messenger of Allah ﷺ said: “Allah has added a prayer for you to your prayers which is better than red camels: it is the two units before the dawn prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي (4463)."},{"num":2427,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَمْرَ بِالرَّكْعَتَيْنِ قَبْلَ صَلَاةِ الْفَجْرِ."],"takhrij":"حسن: رواه النسائي في الكبرى (455) عن أبي بكر بن إسحاق (هو الصغاني) حدثنا إسماعيل بن خليل، أخبرنا ابنُ أبي زائدة، عن إسرائيل، عن عيسى بن أبي عزة، عن عامر (هو الشعبي)، عن أبي ثور الأزدي، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تأكيد ركعتي الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan","chapter_en":"Emphasizing the two units before the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ instructed the two units before the dawn prayer."]},"buhuth":{"en":["al-Nasa’i (al-Kubra 455)","The instruction here is understood as strong encouragement, because the two units before the dawn prayer are not obligatory."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي في الكبرى (455)."},{"num":2428,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ قَالَ: كَانَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي رَكْعَتَيِ الْفَجْرِ فِي الْأُولَى مِنْهُمَا: قُولُوا آمَنَّا بِاللَّهِ وَمَا أُنْزِلَ إِلَيْنَا [ الْبَقَرَةِ: 136] وَفِي الْآخِرَةِ مِنْهُمَا: ﴿آمَنَّا بِاللَّهِ وَاشْهَدْ بِأَنَّا مُسْلِمُونَ﴾ [سورة آل عمران: 52] [ آل عِمْرَانَ:52].","وَفِي رِوَايَةِ فِي الثَّانِيَةِ: تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ [آل عِمْرَانَ: 64]."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (727) من طريق مروان بن معاوية الفزاري، والرواية الثانية من طريق أبي خالد الأحْمَر، كلاهما عن عثمان بن حَكيم الأنصاري، قال: أخبرني سعيد بن يسار، أن ابن عباس أخبره فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في القراءة في ركعتي الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (727)","chapter_en":"Recitation in the two units before the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":6,"content":{"translation":{"en":["Ibn ‘Abbas said: The Messenger of Allah ﷺ used to recite in the two units before the dawn prayer: in the first, “Say: We believe in Allah and what has been revealed to us” (2:136); and in the second, “We believe in Allah—so bear witness that we are Muslims” (3:52). In another narration, in the second he recited: “Come to a word that is just between us and you” (3:64)."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (727)."},{"num":2429,"demo":false,"sanad":"","matn":["عن أبي هريرة أن رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قرأ في ركعتي الفجر: قُلْ يَا أَيُّهَا الْكَافِرُونَ و قُلْ هُوَ اللَّهُ أَحَدٌ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (726) قال: حدثني محمد بن عبَّاد وابن أبي عمر، قالا: حدثنا مروان بن معاوية، عن يزيد (وهو ابن كيسان) عن أبي حازم، عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في القراءة في ركعتي الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (726)","chapter_en":"Recitation in the two units before the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ recited in the two units before the dawn prayer: “Say: O disbelievers” and “Say: He is Allah, One.” (This refers to the two units of the dawn sunnah.)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (726). والمقصود من هذه القراءة في ركعتي سنة الفجر."},{"num":2430,"demo":false,"sanad":"","matn":["عن أبي هريرة أنه سمع النبيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يقرأ في ركعتي الفجر ﴿قُلْ آمَنَّا بِاللَّهِ وَمَا أُنْزِلَ عَلَيْنَا﴾ [سورة آل عمران: 84] في الرّكعة الأولى، وفي الركعة الأخرى بهذه الآية ﴿رَبَّنَا آمَنَّا بِمَا أَنْزَلْتَ وَاتَّبَعْنَا الرَّسُولَ فَاكْتُبْنَا مَعَ الشَّاهِدِينَ﴾ [سورة آل عمران: 53] أو ﴿إِنَّا أَرْسَلْنَاكَ بِالْحَقِّ بَشِيرًا وَنَذِيرًا وَلَا تُسْأَلُ عَنْ أَصْحَابِ الْجَحِيمِ﴾ [سورة البقرة: 119] شكّ الدّراورديّ."],"takhrij":"حسن: رواه أبو داود (1260) عن محمد بن الصباح بن سفيان، حدّثنا عبد العزيز بن محمد، عن عثمان بن عمر ـ يعني ابن موسى ـ، عن أبي الغيث، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في القراءة في ركعتي الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Good due to supporting narrations\nAbu Dawud (1260); al-Bayhaqi (3/43)","chapter_en":"Recitation in the two units before the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said he heard the Prophet ﷺ recite in the two units before the dawn prayer: in the first unit, “Say: We believe in Allah and what has been revealed to us” (3:84). In the other unit he recited: “Our Lord, we believe in what You have sent down and we follow the Messenger, so write us among the witnesses” (3:53), or: “Indeed We have sent you with the truth as a bringer of good news and a warner, and you will not be asked about the companions of the Fire” (2:119). Al-Darawardi was unsure which of the latter two it was."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1260)، والبيهقي (4877)."},{"num":2431,"demo":false,"sanad":"","matn":["عن ابن عمر قال: رمَقْتُ النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شهراً، فكان يقرأ في الركعتين قبل الفجر: قُلْ يَا أَيُّهَا الْكَافِرُونَ و قُلْ هُوَ اللَّهُ أَحَدٌ."],"takhrij":"صحيح: رواه الترمذي (417)، وابن ماجه (1149) كلاهما من طريق أبي أحمد الزبيري، حدثنا سفيان، عن أبي إسحاق، عن مجاهد، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في القراءة في ركعتي الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Tirmidhi (417) (graded it good); Ibn Majah (1149); al-Nasa’i (992)","chapter_en":"Recitation in the two units before the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":6,"content":{"translation":{"en":["Ibn ‘Umar said: I observed the Prophet ﷺ for a month, and he used to recite in the two units before the dawn prayer: “Say: O disbelievers” and “Say: He is Allah, One.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (417) وحسنه، وابن ماجه (1149)، والنسائي (992)."},{"num":2432,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا، أَنَّ رَجُلًا قَامَ فَرَكَعَ رَكْعَتَيِ الْفَجْرِ، فَقَرَأَ فِي الرَّكْعَةِ الْأُولَى: ﴿قُلْ يَا أَيُّهَا الْكَافِرُونَ﴾ حَتَّى انْقَضَتِ السُّورَةُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَذَا عَبْدٌ عَرَفَ رَبَّهُ، وَقَرَأَ فِي الآخِرَةِ: ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ حَتَّى انْقَضَتِ السُّورَةُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَذَا عَبْدٌ آمَنَ بِرَبِّهِ، فَقَالَ طَلْحَةُ: فَأَنَا أَسْتَحِبُّ أَنْ أَقْرَأَ بِهَاتَيْنِ السُّورَتَيْنِ فِي هَاتَيْنِ الرَّكْعَتَيْنِ."],"takhrij":"حسن: أخرجه ابن حبان (2460) فقال: أخبرنا أحمد بن الحسن بن عبد الجبار الصوفي ببغداد، حدثنا يحيى بن معين، حدثنا يحيى بن عبدالله ابن يزيد بن عبدالله بن أنيس الأنصاري، قال: سمعت طلحة بن خراش يحدث عن جابر بن عبدالله فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في القراءة في ركعتي الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Hibban (2460); al-Tahawi (1/298)","chapter_en":"Recitation in the two units before the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":6,"content":{"translation":{"en":["Jabir ibn ‘Abdullah said: A man stood and prayed the two units before the dawn prayer. In the first unit he recited “Say: O disbelievers” until he completed it. The Prophet ﷺ said: “This is a servant who has known his Lord.” In the second unit he recited “Say: He is Allah, One” until he completed it. The Messenger of Allah ﷺ said: “This is a servant who believes in his Lord.” Talhah said: “So I like to recite these two chapters in these two units.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: أخرجه ابن حبان (2460)، والطحاوي في شرحه (1774)."},{"num":2433,"demo":false,"sanad":"","matn":["عن حَفْصَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْبَرَتْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا سَكَتَ الْمُؤَذِّنُ عَنِ الأَذَانِ لِصَلاَةِ الصُّبْحِ صَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ قَبْلَ أَنْ تُقَامَ الصَّلاَةُ."],"takhrij":"متفق عليه: رواه مالك في صلاة الليل (29) عن نافع، عن عبدالله بن عمر، عن حفصة فذكرته، ورواه البخاري في الأذان (618) عن عبدالله بن يوسف، ومسلم في المسافرين (718) عن يحيى بن يحيى -كلاهما عن مالك به، إلا أن البخاري قال في لفظ الحديث: كان رسول الله صلى الله عليه وسلم إذا اعتكف المؤذِّن للصبح، وبَدَأ الصبح صلَّى ركعتين خفيفتين قبل أن تقام الصلاة .","grade":"متفق عليه","chapter_ar":"باب ما جاء في تخفيف القراءة في ركعتي الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon\nMalik (29); al-Bukhari (618); Muslim (718)","chapter_en":"Keeping the recitation light in the two units before the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Hafsah, the wife of the Prophet ﷺ, said: When the caller to prayer finished the call for the dawn prayer, the Messenger of Allah ﷺ would pray two light units before the obligatory prayer was commenced."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (29)، والبخاري (618)، ومسلم (718)."},{"num":2434,"demo":false,"sanad":"","matn":["عن عَائِشَةَ قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُخَفِّفُ الرَّكْعَتَيْنِ اللَّتَيْنِ قَبْلَ صَلاَةِ الصُّبْحِ حَتَّى إِنِّي لأَقُولُ: هَلْ قَرَأَ بِأُمِّ الْكِتَابِ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1171)، ومسلم في المسافرين (724/92) كلاهما من طريق يحيى بن سعيد قال: أخبرني محمد بن عبدالرحمن، أنه سمع عمرة تحدث عن عائشة فذكرته. ورواه مالك في صلاة الليل (30) عن يحيى بن سعيد، عن عائشة. فأسقط في الإسناد اثنين.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تخفيف القراءة في ركعتي الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon. And in al-Bukhari (1170), ‘A’ishah said: The Messenger of Allah ﷺ used to pray thirteen units at night, then when he heard the call for dawn he would pray two light units.","chapter_en":"Keeping the recitation light in the two units before the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["‘A’ishah said: The Prophet ﷺ would make the two units before the dawn prayer so light that I would say: “Did he recite the Opening of the Book or not?”"]},"buhuth":{"en":["Agreed upon (Bukhari & Muslim)","al-Bukhari (1171), Muslim (92/724); also al-Bukhari (1170)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1171)، ومسلم (724/92). وفي البخاري (1170) عن عائشة قالت:."},{"num":2435,"demo":false,"sanad":"","matn":["عَنْ حَفْصَةَ قَالَتْ: كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا أضـاء الْفَجْرُ صَلَّى رَكْعَتَيْنِ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (723: 89) عن محمد بن عباد، ثنا سفيان، عن عمرو، عن الزهري، عن سالم، عن أبيه، قال: أخبرتني حفصة فذكرت.","grade":"صحيح","chapter_ar":"باب وقت ركعتي الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic","chapter_en":"The time of the two units before the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":8,"content":{"translation":{"en":["Hafsah, the Mother of the Believers, said: When dawn became bright, the Prophet ﷺ would pray two units."]},"buhuth":{"en":["Muslim (89:723)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (723: 89)."},{"num":2436,"demo":false,"sanad":"","matn":["عن حَفْصَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا اعْتَكَفَ الْمُؤَذِّنُ لِلصُّبْحِ وَبَدَا الصُّبْحُ صَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ قَبْلَ أَنْ تُقَامَ الصَّلاَةُ."],"takhrij":"صحيح: رواه البخاري في الأذان (618) عن عبد الله بن يوسف، قال: أخبرنا مالك، عن نافع، عن عبد الله بن عمر، قال: أخبرتني حفصة، فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب وقت ركعتي الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (618)","chapter_en":"The time of the two units before the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":8,"content":{"translation":{"en":["Hafsah reported that when the caller to prayer pronounced the dawn adhan and dawn had appeared, the Messenger of Allah ﷺ would pray two light units before the prayer was commenced."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (618)."},{"num":2437,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي رَكْعَتَيِ الْفَجْرِ إِذَا سَمِعَ الْأَذَانَ، وَيُخَفِّفُهُمَا."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (724) عن عمرو الناقد، ثنا عبدة بن سليمان، ثنا هشام بن عروة، عن أبيه، عن عائشة.","grade":"صحيح","chapter_ar":"باب وقت ركعتي الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (724)","chapter_en":"The time of the two units before the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":8,"content":{"translation":{"en":["‘A’ishah, the Mother of the Believers, said: The Messenger of Allah ﷺ would pray the two units of the dawn sunnah when he heard the call, making them light. In another narration: when dawn broke."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (724). وفي رواية: إذا طلع الفجر."},{"num":2438,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا تَوَضَّأَ صَلَّى رَكْعَتَيْنِ، ثُمَّ خَرَجَ إِلَى الصَّلاَةِ."],"takhrij":"صحيح: رواه ابن ماجه (1146) عن أبي بكر بن أبي شيبة، قال: حدثنا أبو الأحوص، عن أبي إسحاق، عن الأسود، عن عائشة فذكرت مثله.","grade":"صحيح","chapter_ar":"باب وقت ركعتي الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Majah (1146)","chapter_en":"The time of the two units before the dawn prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":8,"content":{"translation":{"en":["‘A’ishah said: The Prophet ﷺ would perform ablution, pray two units, then go out to the prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (1146)."},{"num":2439,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَالِكٍ بن بُحَيْنة قَالَ: إن رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مرَّ بِرَجُلٍ يُصَلِّي، وَقَدْ أُقيمتْ صَلَاةُ الصُّبْحِ فكلَّمه بِشَيْءٍ، لَا نَدْرِي مَا هُوَ، فَلَمَّا انْصَرَفْنَا أَحَطْنَا نَقُولُ: مَاذَا قَالَ لَكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ؟ قَالَ: قَالَ لِي: يُوشِكُ أَنْ يُصَلِّي أَحَدُكُمُ الصُّبْحَ أَرْبَعًا؟ هَذَا لفظ مُسْلِمٌ.","ولفظ البخاري: فَلَمَّا انْصَرَفَ رَسُولُ اللَّهِ صلى الله عليه وسلم لاَثَ بِهِ النَّاسُ، وَقَالَ لَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم :: الصُّبْحَ أَرْبَعًا ،، الصبحَ أربعاً ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (663)، ومسلم في صلاة المسافرين (711) كلاهما من طريق إبراهيم بن سعد، عن أبيه، عن حفص بن عاصم، عن عبدالله بن مالك بن بحينة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في كراهية الاشتغال بركعتي الفجر إذا أقيمتِ الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (663); Muslim (711)","chapter_en":"Disliking being occupied with the two units before dawn once the obligatory prayer has been commenced","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["‘Abdullah ibn Malik ibn Buhaynah said: The Messenger of Allah ﷺ passed by a man praying while the dawn prayer had already been commenced. He spoke to him with something we did not know. When we finished, we gathered around the man and asked what the Messenger of Allah ﷺ said to him. He replied: He said to me: “Is one of you about to pray the dawn prayer as four units?” (This is Muslim’s wording.)","In al-Bukhari’s wording, he said: “The dawn prayer—four? The dawn prayer—four?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (663)، ومسلم (711)."},{"num":2440,"demo":false,"sanad":"","matn":["عَبْدِ اللَّهِ بْنِ سَرْجِسَ قَالَ:  دَخَلَ رَجُلٌ الْمَسْجِدَ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي صَلَاةِ الْغَدَاةِ، فَصَلَّى رَكْعَتَيْنِ فِي جَانِبِ الْمَسْجِدِ، ثُمَّ دَخَلَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَلَمَّا سَلَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَا فُلَانُ، بِأَيِّ الصَّلَاتَيْنِ اعْتَدَدْتَ؟ أَبِصَلَاتِكَ وَحْدَكَ؟ أَمْ بِصَلَاتِكَ مَعَنَا."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (712) من طريق عاصم الأحول، عن عبدالله بن سَرْجِس فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في كراهية الاشتغال بركعتي الفجر إذا أقيمتِ الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (712)","chapter_en":"Disliking being occupied with the two units before dawn once the obligatory prayer has been commenced","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["‘Abdullah ibn Sarjis said: A man entered the mosque while the Messenger of Allah ﷺ was praying the dawn prayer. He prayed two units at the side of the mosque, then joined the Messenger of Allah ﷺ. When the Messenger of Allah ﷺ finished, he said: “O so-and-so, which of the two prayers did you count—your prayer by yourself or your prayer with us?”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (712)."},{"num":2441,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  إِذَا أُقِيمَتِ الصَّلَاةُ، فَلَا صَلَاةَ إِلَّا الْمَكْتُوبَةُ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (710) عن أحمد بن حنبل، حدثنا محمد بن جعفر، حدثنا شعبة، عن وَرْقاءَ، عن عمرو بن دينار، عن عطاء بن يسار، عن أبي هريرة قال: فذكره. ورواه أيضاً من طريق حماد بن زيد، عن أيوب، عن عمرو بن دينار به مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في كراهية الاشتغال بركعتي الفجر إذا أقيمتِ الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (710)","chapter_en":"Disliking being occupied with the two units before dawn once the obligatory prayer has been commenced","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah narrated from the Prophet ﷺ: “When the prayer has been commenced, there is no prayer except the obligatory one.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2391],"tks":"صحيح: رواه مسلم (710)."},{"num":2442,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: أُقِيمَتْ صَلاةُ الصُّبْحِ، فَقَامَ رَجُلٌ يُصَلِّي الرَّكْعَتَيْنِ، فَجَذَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِثَوْبِهِ، فَقَالَ: أَتُصَلِّي الصُّبْحَ أَرْبَعًا؟"],"takhrij":"حسن: رواه الإمام أحمد (2130) عن يزيد، حدثنا صالح بن رستم أبو عامر، عن عبدالله بن أبي مليكة، عن ابن عباس فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء في كراهية الاشتغال بركعتي الفجر إذا أقيمتِ الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (2130)","chapter_en":"Disliking being occupied with the two units before dawn once the obligatory prayer has been commenced","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Ibn ‘Abbas said: The dawn prayer was commenced, and a man stood to pray the two units. The Messenger of Allah ﷺ pulled his garment and said: “Are you praying the dawn prayer as four units?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد ( 2130)."},{"num":2443,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ ، قَالَ: : خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ أُقِيمَتِ الصَّلاةُ، فَرَأَى نَاسًا يُصَلُّونَ رَكْعَتَيْنِ بِالْعَجَلَةِ، ، فَقَالَ: : أَصَلاتَانِ مَعًا؟ ، فَنَهَى أَنْ يُصَلَّى فِي الْمَسْجِدِ إِذَا أُقِيمَتِ الصَّلاةُ."],"takhrij":"حسن: رواه ابن خزيمة (1126) عن علي بن حجر السعدي بخبر غريب غريب- قال: ثنا محمد بن عمار -يعني الأنصاري، عن شريك بن عبدالله- وهو ابن أبي نمر -عن أنس قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في كراهية الاشتغال بركعتي الفجر إذا أقيمتِ الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Khuzaymah (1126)","chapter_en":"Disliking being occupied with the two units before dawn once the obligatory prayer has been commenced","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Anas said: The Prophet ﷺ came out when the prayer had been commenced and saw people praying two units quickly. He said: “Two prayers together?” So he forbade praying in the mosque once the prayer has been commenced."]}},"tuhfa":{},"voc":["ibnkhuzaymah",1129],"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة ( 1126)."},{"num":2444,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى رَجُلًا يُصَلِّي رَكْعَتِي الْفَجْرِ حِينَ أَخَذَ الْمُؤَذِّنُ يُقِيمُ، فَغَمَزَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْكِبَهُ وَقَالَ: أَلَا كَانَ هَذَا قَبْلَ هَذَا؟ ."],"takhrij":"حسن: رواه الطبراني في الكبير والأوسط كما في مجمع البحرين (771) عن أحمد بن حمدان أبي سعيد التستري بعبادان، ثنا إبراهيم بن يوسف الصيرفي، ثنا عبد الرحمن بن محمد المحاربي، عن سليمان الشيباني، عن أبي بكر بن أبي موسى، عن أبيه، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في كراهية الاشتغال بركعتي الفجر إذا أقيمتِ الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tabarani (al-Kabir and al-Awsat), as cited in Majma‘ al-Bahrayn (771)","chapter_en":"Disliking being occupied with the two units before dawn once the obligatory prayer has been commenced","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Abu Musa reported that the Messenger of Allah ﷺ saw a man praying the two units of the dawn sunnah while the caller to prayer had begun commencing the prayer. The Prophet ﷺ pressed his shoulder and said: “Shouldn’t this have been before this?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير والأوسط كما في مجمع البحرين (771)."},{"num":2445,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَامَ عَنْ رَكْعَتَىِ الْفَجْرِ. فَقَضَاهُمَا بَعْدَ مَا طَلَعَتِ الشَّمْسُ."],"takhrij":"حسن: رواه ابن ماجه (1155) عن عبدالرحمن بن إبراهيم ويعقوب بن حُميد بن كاسب، قالا: حدثنا مروان بن معاوية، عن يزيد بن كيسان، عن أبي حازم، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء فيمن فاتته ركعتا الفجر متى يقضيهما","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Majah (1155); Ibn Hibban (2652)","chapter_en":"If the two units before dawn are missed, when should they be made up?","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":10,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ slept and missed the two units before the dawn prayer, so he made them up after the sun had risen."]},"buhuth":{"en":["The basis of this report is found in Sahih Muslim (in the narration about the Prophet ﷺ’s overnight stop on a journey), where they did not awaken until after sunrise; it mentions that he prayed two rakʿahs, then the prayer was commenced and he prayed the dawn prayer.","Ibn Khuzaymah also authenticated it (1117) with the wording: “Whoever forgets the two units before dawn should pray them when the sun has risen.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1155)، وصححه ابن حبان (2652)."},{"num":2446,"demo":false,"sanad":"","matn":["عَنْ قَيْسِ بْنِ عَمْرٍو، قَالَ: رَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلاً يُصَلِّي بَعْدَ صَلاَةِ الصُّبْحِ رَكْعَتَيْنِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلاَةُ الصُّبْحِ رَكْعَتَانِ. فَقَالَ الرَّجُلُ: إِنِّي لَمْ أَكُنْ صَلَّيْتُ الرَّكْعَتَيْنِ اللَّتَيْنِ قَبْلَهُمَا، فَصَلَّيْتُهُمَا الْآنَ. فَسَكَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"حسن: رواه أبو داود (1267) حدثنا عثمان بن أبي شيبة، حدثنا ابن نمير، عن سعد بن سعيد، حدثني محمد بن إبراهيم، عن قيس ابن عمرو فذكره.","grade":"حسن","chapter_ar":"باب ما جاء فيمن فاتته ركعتا الفجر متى يقضيهما","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (1267); Ibn Majah (1154); al-Hakim (al-Mustadrak 1/275)","chapter_en":"If the two units before dawn are missed, when should they be made up?","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":10,"content":{"translation":{"en":["Qays ibn ‘Amr said: The Messenger of Allah ﷺ saw a man praying two units after the dawn prayer. The Messenger of Allah ﷺ said: “The dawn prayer is two units.” The man said: “I had not prayed the two units that come before it, so I prayed them now.” So the Messenger of Allah ﷺ remained silent."]},"buhuth":{"en":["The conclusion (as stated in al-Minnah al-Kubra 2/323): the hadith of Qays ibn Qahd—together with its supporting narrations and witness reports—does not fall below the level of “good,” and it specifies the general prohibition of voluntary prayers after dawn. From a reasoning standpoint: these two units belong before sunrise, so it is recommended to perform them in their proper time; and the prohibition of praying after dawn until sunrise applies to prayers without a specific reason. The two units before dawn are among the prayers strongly emphasized by the Lawgiver, and that emphasis is a valid reason for making them up."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1267)، وابن ماجه (1154) والحاكم في المستدرك (1018)."},{"num":2447,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى رَكْعَتَىِ الْفَجْرِ، اضْطَجَعَ عَلَى شِقِّهِ الأَيْمَنِ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1160) عن عبدالله بن يزيد، حدثنا سعيد بن أبي أيوب، قال: حدثني أبو الأسود، عن عروة بن الزبير، عن عائشة فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الاضطجاع بعد ركعتي الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (1160); Muslim (736)","chapter_en":"Lying down after the two units before dawn","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":11,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: When the Messenger of Allah ﷺ prayed the two units before dawn, he would lie down on his right side."]},"buhuth":{"en":["She also said: The Messenger of Allah ﷺ used to pray between finishing the night prayer (the one people call “al-‘atamah”) and dawn—eleven units, giving salam after every two and praying one unit as witr. When the caller to prayer finished the call for dawn and dawn became clear to him, and the caller came to him, he would stand and pray two light units, then lie down on his right side until the caller came to commence the prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1160)، ورواه مسلم (736) عن عائشة زوج النبي ﷺ قالت: كان رسول الله ﷺ يصلي فيما بين أن يفرغ من صلاة العشاء - وهي التي يدعو الناس العتمة- إلى الفجر إحدى عشرة ركعة يسلم بين كل ركعتين ويوتر بواحدة، فإذا سكت المؤذن من صلاة الفجر وتبين له الفجر وجاءه المؤذن قام فركع ركعتين خفيفتين ثم اضطجع على شقه الأيمن حتى يأتيه المؤذن للإقامة."},{"num":2448,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى رَكْعَتَىِ الْفَجْرِ اضْطَجَعَ."],"takhrij":"صحيح: رواه ابن ماجه (1199) عن عمر بن هشام، قال: حدّثنا النّضر ابن شميل، قال: أنبأنا شعبة، قال: حدّثني سهيل بن أبي صالح، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الاضطجاع بعد ركعتي الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Majah (1199)","chapter_en":"Lying down after the two units before dawn","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah said: When the Messenger of Allah ﷺ prayed the two Sunnah rakʿahs before Fajr, he would lie down."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه ( 1199)."},{"num":2449,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا صَلَّى {سُنَّةَ الْفَجْرِ} فَإِنْ كُنْتُ مُسْتَيْقِظَةً حَدَّثَنِي وَإِلاَّ اضْطَجَعَ حَتَّى يُؤْذَنَ بِالصَّلاَةِ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1161)، ومسلم في صلاة المسافرين (743) كلاهما من حديث سفيان بن عيينة، قال: حدثني سالم أبو النضر، عن أبي سلمة، عن عائشة قالت: فذكر ته.","grade":"متفق عليه","chapter_ar":"باب من تحدث بعد ركعتي الفجر ولم يضطجع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (1161); Muslim (743)","chapter_en":"Speaking after the two units before dawn without lying down","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":12,"content":{"translation":{"en":["‘A’ishah said: When the Prophet ﷺ finished praying, if I was awake he would speak with me; otherwise he would lie down until the call was made to commence the prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1161)، ومسلم (743)."},{"num":2450,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ، قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى الْفَجْرَ تَرَبَّعَ فِي مَجْلِسِهِ، حَتَّى تَطْلُعَ الشَّمْسُ حَسْنَاءَ."],"takhrij":"حسن: رواه أبو داود (4850) عن عثمان بن أبى شيبة، حدثنا أبو داود الحفري، حدثنا سفيان الثوري، عن سماك بن حرب، عن جابر بن سمرة قال: فذكره.","grade":"حسن","chapter_ar":"باب الجلوس بعد الفجر متربّعًا","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (4850)","chapter_en":"Sitting cross-legged after dawn","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Jabir ibn Samurah said: When the Prophet ﷺ prayed the dawn prayer, he would sit cross-legged in his place until the sun rose bright."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود ( 4850)."},{"num":2451,"demo":false,"sanad":"","matn":["عَنْ أُمِّ حَبِيبَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَنْ صَلَّى أَرْبَعَ رَكَعَاتٍ قَبْلَ الظُّهْرِ، وَأَرْبَعًا بَعْدَهَا حَرَّمَ اللَّهُ لَحْمَهُ عَلَى النَّارِ ."],"takhrij":"صحيح: رواه النسائي (1812) من طريق موسى بن أعين، عن أبي عمرو الأوزاعي، عن حسان بن عطية قال: لما نُزل بعنبسة، جعل يتضَوَّر، فقيل له: فقال: أما إني سمعت أم حبيبة زوج النبي صلى الله عليه وسلم تحدث فذكر الحديث وقال: فما تركتُهن منذ سمعتُهن.","grade":"صحيح","chapter_ar":"باب ما جاء في الأربع قبل الظهر وبعدها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Nasa’i (1812)","chapter_en":"The four units before and after the noon prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":14,"content":{"translation":{"en":["Umm Habibah, the wife of the Prophet ﷺ, said: The Messenger of Allah ﷺ said: “Whoever prays four units before the noon prayer and four after it, Allah will forbid his flesh from the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي ( 1812)."},{"num":2452,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ لاَ يَدَعُ أَرْبَعًا قَبْلَ الظُّهْرِ، وَرَكْعَتَيْنِ قَبْلَ الْغَدَاةِ."],"takhrij":"صحيح: رواه البخاري في التهجد (1182) عن مسدد، قال: حدثنا يحيى، عن شعبة، عن إبراهيم بن محمد بن المنتشر، عن أبيه، عن عائشة فذكرته. وقال: تابعه ابن أبي عدي وعمرو، عن شعبة.","grade":"صحيح","chapter_ar":"باب تأكيد أربع ركعات قبل الظهر، وركعتين قبل الفجر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (1182)","chapter_en":"Emphasizing four units before noon, and two units before dawn","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":15,"content":{"translation":{"en":["‘A’ishah said: The Prophet ﷺ would not leave off four units before the noon prayer, and two units before the dawn prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1182)."},{"num":2453,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن السَّائِبِ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي أَرْبَعًا بَعْدَ أَنْ تَزُولَ الشَّمْسُ قَبْلَ الظُّهْرِ، وَقَالَ: إِنَّهَا سَاعَةٌ تُفتحُ فِيهَا أَبْوَابُ السَّمَاءِ، وَأُحِبُّ أَنْ يَصْعَدَ لِي فِيهَا عَمَلٌ صَالِحٌ ."],"takhrij":"حسن: رواه الترمذي في السنن (478) وفي الشمائل (289)، والنسائي في الكبرى (331) كلهم من طريق أبي داود الطيالسي، حدثنا محمد بن مسلم ابن أبي الوضَّاح، وهو أبو سعيد المؤدِّب، عن عبدالكريم الجزري، عن مجاهد، عن عبدالله بن السائب فذكره.","grade":"حسن","chapter_ar":"باب استحباب أربع ركعات بعد الزوال قبل الظهر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tirmidhi (478); al-Nasa’i (al-Kubra 331); Ahmad (15396)","chapter_en":"Recommending four units after the sun passes its zenith, before noon","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":16,"content":{"translation":{"en":["‘Abdullah ibn al-Sa’ib reported that the Messenger of Allah ﷺ used to pray four units after the sun passed its zenith, before the noon prayer, and he said: “It is an hour in which the gates of Heaven are opened, and I love that a righteous deed be raised up for me in it.” (In Ahmad’s wording: “I love to put forward a righteous deed in it.”)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (478) وحسنه، والنسائي في الكبرى (331). ورواه أحمد (15396) وفيه:."},{"num":2454,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَحِمَ اللَّهُ امْرَأً صَلَّى قَبْلَ الْعَصْرِ أَرْبَعًا."],"takhrij":"حسن: رواه أبو داود (1271)، والترمذي (430) كلاهما من طريق أبي داود الطيالسي، حدثنا محمد بن مهران القرشي، حدثني جدي أبو المثنى، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في سنة العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (1271); al-Tirmidhi (430)","chapter_en":"What has been reported regarding the sunnah before ‘Asr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":17,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ said: “May Allah have mercy on a person who prays four units before ‘Asr.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1271)، والترمذي (430)."},{"num":2455,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي قَبْلَ الْعَصْرِ أَرْبَعَ رَكَعَاتٍ، يَفْصِلُ بَيْنَهُنَّ بِالتَّسْلِيمِ عَلَى الْمَلاَئِكَةِ الْمُقَرَّبِينَ، وَمَنْ تَبِعَهُمْ مِنَ الْمُسْلِمِينَ وَالْمُؤْمِنِينَ."],"takhrij":"حسن: رواه الترمذي (429) من طريق سفيان، عن أبي إسحاق، عن عاصم بن ضمرة، عن علي فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في سنة العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tirmidhi (429)","chapter_en":"What has been reported regarding the sunnah before ‘Asr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":17,"content":{"translation":{"en":["‘Ali ibn Abi Talib said: The Prophet ﷺ used to pray four units before ‘Asr, separating them with salutations—sending peace upon the angels brought near, and upon those who follow them from the Muslims and the believers."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (429) وحسنه."},{"num":2456,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ بن أَبِي طَالِبٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي قَبْلَ الْعَصْرِ رَكْعَتَيْنِ."],"takhrij":"حسن: رواه أبو داود (1272) عن حفص بن عمر، حدثنا شعبة، عن أبي إسحاق، عن عاصم بن ضمرة، عن علي فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في سنة العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (1272)","chapter_en":"What has been reported regarding the sunnah before ‘Asr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":17,"content":{"translation":{"en":["‘Ali ibn Abi Talib reported that the Prophet ﷺ used to pray two units before ‘Asr."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1272)."},{"num":2457,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ:  كُنَّا بِالْمَدِينَةِ، فَإِذَا أَذَّنَ الْمُؤَذِّنُ لِصَلَاةِ الْمَغْرِبِ ابْتَدَرُوا السَّوَارِيَ، فَيَرْكَعُونَ رَكْعَتَيْنِ رَكْعَتَيْنِ، حَتَّى إِنَّ الرَّجُلَ الْغَرِيبَ لَيَدْخُلُ الْمَسْجِدَ فَيَحْسِبُ أَنَّ الصَّلَاةَ قَدْ صُلِّيَتْ مِنْ كَثْرَةِ مَنْ يُصَلِّيهِمَا."],"takhrij":"متفق عليه: رواه البخاري في الأذان (625)، ومسلم في المسافرين (837) كلاهما من طريقين عن أنس، واللفظ لمسلم،","grade":"متفق عليه","chapter_ar":"باب ما جاء في ركعتين قبل المغرب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (625); Muslim (837)","chapter_en":"The two units before Maghrib","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":18,"content":{"translation":{"en":["Anas ibn Malik said: We were in Madinah, and when the caller to prayer gave the call for the Maghrib prayer, they would rush to the pillars and pray two units, two units, until a stranger would enter the mosque and think the prayer had already been performed because of how many people were praying them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (625)، ومسلم (837)، واللفظ لمسلم."},{"num":2458,"demo":false,"sanad":"","matn":["عن مرثد بن عبدالله اليزني قَالَ: أَتَيْتُ عُقْبَةَ بْنَ عَامِرٍ الْجُهَنِيَّ، فَقُلْتُ: أَلاَ أُعْجِبُكَ مِنْ أَبِي تَمِيمٍ، يَرْكَعُ رَكْعَتَيْنِ قَبْلَ صَلاَةِ الْمَغْرِبِ. فَقَالَ: عُقْبَةُ: إِنَّا كُنَّا نَفْعَلُهُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قُلْتُ: فَمَا يَمْنَعُكَ الْآنَ؟ قَالَ: الشُّغْلُ."],"takhrij":"صحيح: رواه البخاري في التهجد (1184) عن عبدالله بن يزيد، قال: حدثنا سعيد بن أبي أيوب، قال: حدثني يزيد بن أبي حبيب، قال: سمعت مرثد ابن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في ركعتين قبل المغرب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (1184)","chapter_en":"The two units before Maghrib","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":18,"content":{"translation":{"en":["Marathad ibn ‘Abdullah al-Yazani said: I came to ‘Uqbah ibn ‘Amir al-Juhani and said: “Shall I not tell you something surprising about Abu Tamim—he prays two units before Maghrib?” ‘Uqbah said: “We used to do that during the time of the Messenger of Allah ﷺ.” I said: “So what prevents you now?” He said: “Being busy.”"]},"buhuth":{"en":["“Shall I not surprise you…” means: I am telling you something you would find strange and surprising."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1184)."},{"num":2459,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مُغَفَّلٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: صَلُّوا قَبْلَ صَلاَةِ الْمَغْرِبِ ـ قَالَ فِي الثَّالِثَةِ ـ لِمَنْ شَاءَ، كَرَاهِيَةَ أَنْ يَتَّخِذَهَا النَّاسُ سُنَّةً ."],"takhrij":"صحيح: رواه البخاري في التهجد (1183) عن أبي معمر، حدثنا عبد الوارث، عن الحسين، عن ابن بُريدة قال: حدثني عبدالله المزني فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في ركعتين قبل المغرب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bukhari (1183)","chapter_en":"The two units before Maghrib","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":18,"content":{"translation":{"en":["‘Abdullah ibn Mughaffal al-Muzani narrated from the Prophet ﷺ: “Pray before the Maghrib prayer.” He said it a third time: “Whoever wishes,” out of dislike that people might take it as an established regular sunnah."]},"buhuth":{"en":["“Out of dislike that people might take it as a sunnah” means: as a fixed, regular sunnah (a permanent established routine), for it is not like that."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1183). قوله: “كراهية أن يتخذها الناس سنة” أي سنة راتبة فهي ليست كذلك."},{"num":2460,"demo":false,"sanad":"","matn":["عَنْ مُخْتَارِ بْنِ فُلْفُلٍ قَالَ:  سَأَلْتُ أَنَسَ بْنَ مَالِكٍ، عَنِ التَّطَوُّعِ بَعْدَ الْعَصْرِ، فَقَالَ: كَانَ عُمَرُ يَضْرِبُ الْأَيْدِي عَلَى صَلَاةٍ بَعْدَ الْعَصْرِ، - وَكُنَّا نُصَلِّي عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَكْعَتَيْنِ بَعْدَ غُرُوبِ الشَّمْسِ قَبْلَ صَلَاةِ الْمَغْرِبِ. فَقُلْتُ لَهُ: أَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّاهُمَا؟ قَالَ: كَانَ يَرَانَا نُصَلِّيهِمَا فَلَمْ يَأْمُرْنَا، وَلَمْ يَنْهَنَا."],"takhrij":"صحيح: رواه مسلم في المسافرين (836) من طريق ابن فُضيل، عن مختار ابن فُلْفُل قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في ركعتين قبل المغرب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (836)","chapter_en":"The two units before Maghrib","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":18,"content":{"translation":{"en":["Mukhtar ibn Fulful said: I asked Anas ibn Malik about voluntary prayer after ‘Asr. He said: ‘Umar used to strike hands for praying after ‘Asr. But during the time of the Prophet ﷺ, we used to pray two units after the sun had set, before the Maghrib prayer. I asked him: “Did the Messenger of Allah ﷺ pray them?” He said: “He used to see us praying them, and he neither ordered us nor forbade us.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (836)."},{"num":2461,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مُغَفَّلٍ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : بينَ كلّ أَذَانَيْنِ صَلاَةٌ، بينَ كلّ أَذَانَيْنِ صَلاَةٌ ثُمَّ قَالَ فِي الثَّالِثَةِ: لمَنْ شَاء ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (627)، ومسلم في صلاة المسافرين (838) كلاهما من طريق كهمس بن الحسن، عن عبدالله بن بريدة، عن عبدالله بن مغفل فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء بين كل أذانين صلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Bukhari & Muslim)\nal-Bukhari (627); Muslim (838)","chapter_en":"Between every two calls there is a prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":19,"content":{"translation":{"en":["‘Abdullah ibn Mughaffal said: The Prophet ﷺ said: “Between every two calls there is a prayer; between every two calls there is a prayer.” Then the third time he said: “Whoever wishes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (627)، ومسلم (838)."},{"num":2462,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عِنْدَ كُلِّ أَذَانَيْنِ صَلَاةٌ، عِنْدَ كُلِّ أَذَانَيْنِ صَلَاةٌ، عِنْدَ كُلِّ أَذَانَيْنِ صَلَاةٌ، لِمَنْ شَاءَ."],"takhrij":"صحيح: رواه الإمام أحمد (20574) عن يزيد (هو ابن هارون)، أخبرنا الجريري وكهمس عن عبدالله بن بريدة، عن عبد الله بن مغفل قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء بين كل أذانين صلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (20574)","chapter_en":"Between every two calls there is a prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":19,"content":{"translation":{"en":["‘Abdullah ibn Mughaffal said: The Messenger of Allah ﷺ said: “At every two calls there is a prayer; at every two calls there is a prayer; at every two calls there is a prayer—for whoever wishes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (20574)."},{"num":2463,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مِنْ صَلَاةٍ مَفْرُوضَةٍ إِلَاّ وَبَيْنَ يَدَيْهَا رَكْعَتَانِ."],"takhrij":"حسن: رواه ابن حبان (2455)، والدارقطني (1046) كلاهما من طريق عثمان بن سعيد القرشي، حدثنا محمد بن مهاجر (هو الأنصاري الشامي)، عن ثابت بن عجلان، عن سُليم بن عامر الخبائري، عن عبد الله بن الزبير قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء بين كل أذانين صلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Hibban (2455); al-Daraqutni (1046)","chapter_en":"Between every two calls there is a prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":19,"content":{"translation":{"en":["‘Abdullah ibn al-Zubayr reported that the Messenger of Allah ﷺ said: “There is no obligatory prayer except that before it are two units.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (2455)، والدار قطني (1046)."},{"num":2464,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ قَالَ: قَالَتْ لِي أُمِّي: مَتَى عَهْدُكَ بِالنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: فَقُلْتُ: مَا لِي بِهِ عَهْدٌ مُنْذُ كَذَا وَكَذَا، قَالَ: فَهَمَّتْ بِي، فَقُلْتُ: يَا أُمَّهْ، دَعِينِي حَتَّى أَذْهَبَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَا أَدَعُهُ حَتَّى يَسْتَغْفِرَ لِي، وَيَسْتَغْفِرَ لَكِ، قَالَ: فَجِئْتُهُ فَصَلَّيْتُ مَعَهُ الْمَغْرِبَ، فَلَمَّا قَضَى الصَّلَاةَ قَامَ يُصَلِّي، فَلَمْ يَزَلْ يُصَلِّي حَتَّى صَلَّى الْعِشَاءَ، ثُمَّ خَرَجَ."],"takhrij":"حسن: رواه الترمذي (3781) عن عبدالله بن عبدالرحمن وإسحاق بن منصور، قالا: أخبرنا محمد بن يوسف، عن إسرائيل، عن ميسرة بن حبيب، عن المنهال بن عمرو، زِر بن حُبيش، عن حذيفة.","grade":"حسن","chapter_ar":"باب التطوع بين المغرب والعشاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tirmidhi (3781); Ahmad (23436); Ibn Khuzaymah (1194); Ibn Hibban (6960)","chapter_en":"Voluntary prayer between Maghrib and ‘Isha","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":20,"content":{"translation":{"en":["Hudhayfah said: My mother said to me, “When was the last time you were with the Prophet ﷺ?” I said, “I have not been with him since such-and-such.” She was about to do something to me, so I said, “Mother, leave me until I go to the Prophet ﷺ. I will not leave him until he seeks forgiveness for me and seeks forgiveness for you.” So I came to him and prayed Maghrib with him. When he finished the prayer, he stood to pray. He continued praying until he prayed ‘Isha, then he left."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3781) وأحمد (23436) وصححه ابن خزيمة (1194)، وابن حبان ( 6960)."},{"num":2465,"demo":false,"sanad":"","matn":["عَنْ تَمِيمٍ الداري، عن النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أوّلُ مَا يُحَاسَبُ بِهِ الْعَبْدُ يَوْمَ الْقِيَامَةِ صَلاَتُهُ، فَإِنْ أَكْمَلَهَا كُتِبَتْ لَهُ نَافِلَةً. فَإِنْ لَمْ يَكُنْ أَكْمَلَهَا، قَالَ اللَّهُ سُبْحَانَهُ لِمَلاَئِكَتِهِ: انْظُرُوا، هَلْ تَجِدُونَ لِعَبْدِي مِنْ تَطَوُّعٍ؟ فَأَكْمِلُوا بِهَا مَا ضيّع مِنْ فَرِيضَتِهِ، ثُمَّ توخذ الأَعْمَالُ عَلَى حَسَبِ ذَلِكَ ."],"takhrij":"صحيح: رواه ابن ماجه (1426) عن أحمد بن سعيد الدارمي، قال: حدثنا سليمان بن حرب، قال: حدثنا حماد بن سلمة، عن داود بن أبي هند، عن زرارة بن أوفى، عن تميم الدارمي فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في إكمال النقص في الفرائض بالتطوع يوم القيامة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Majah (1426); Abu Dawud (866); al-Hakim (al-Mustadrak 1/262–263)","chapter_en":"Completing deficiencies in obligatory prayers with voluntary prayers on the Day of Resurrection","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":21,"content":{"translation":{"en":["Tamim al-Dari narrated from the Prophet ﷺ that he said: “The first thing for which a servant will be brought to account on the Day of Resurrection is his prayer. If it is complete, it will be recorded for him as complete. If it is not complete, Allah—Glorified—will say to His angels: ‘Look—do you find any voluntary prayer for My servant?’ Then complete with it whatever he fell short of in his obligatory prayer. Then the rest of deeds will be taken according to that.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16199],"tks":"صحيح: رواه ابن ماجه (1426)، وأبو داود (866) والحاكم في المستدرك (966)."},{"num":2466,"demo":false,"sanad":"","matn":["عن عائذ بن قُرْطٍ، يَقُولُ: قَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَنْ صَلَّى صَلاةً لَمْ يُتِمَّهَا زِيدَ عَلَيْهَا مِنْ سَبَحَاتِهِ حَتَّى تَتِمَّ ."],"takhrij":"حسن: رواه الطبراني في الكبير (18/ح 37) عن عبدالله بن أحمد بن حنبل، حدثنا الهيثم بن خارجة، حدثنا محمد بن حمير، عن عمرو بن قيس السكوني، قال: سمعت عائذ بن قرط، يقول: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في إكمال النقص في الفرائض بالتطوع يوم القيامة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tabarani, al-Mu‘jam al-Kabir (18/22)","chapter_en":"Completing deficiencies in obligatory prayers with voluntary prayers on the Day of Resurrection","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":21,"content":{"translation":{"en":["‘A’idh ibn Qurt said: The Messenger of Allah ﷺ said: “Whoever prays a prayer and does not complete it, it will be increased for him from his voluntary prayers until it becomes complete.”"]},"buhuth":{"en":["“From his subuhat” means: from his voluntary prayers."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (18/ح 37)."},{"num":2467,"demo":false,"sanad":"","matn":["عن عُمَرَ بن عَطَاءٍ بْنِ أَبِي الخُوار، أَنَّ نَافِعَ بْنَ جُبَيْرٍ أَرْسَلَهُ إِلَى السَّائِبِ ابْنِ أُخْتِ نَمِرٍ، يَسْأَلُهُ عَنْ شَيْءٍ رَآهُ مِنْهُ مُعَاوِيَةُ فِي الصَّلَاةِ. فَقَالَ: نَعَمْ. صَلَّيْتُ مَعَهُ الْجُمُعَةَ فِي الْمَقْصُورَةِ. فَلَمَّا سَلَّمَ الْإِمَامُ قُمْتُ فِي مَقَامِي. فَصَلَّيْتُ. فَلَمَّا دَخَلَ أَرْسَلَ إِلَيَّ فَقَالَ: لَا تَعُدْ لِمَا فَعَلْتَ. إِذَا صَلَّيْتَ الْجُمُعَةَ فَلَا تَصِلْهَا بِصَلَاةٍ حَتَّى تَكَلَّمَ أَوْ تَخْرُجَ. فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَنَا بِذَلِكَ. أَنْ لَا تُوصَلَ صَلَاةٌ حَتَّى نَتَكَلَّمَ، أَوْ نَخْرُجَ."],"takhrij":"صحيح: رواه مسلم في الجمعة (883) عن أبي بكر بن أبي شيبة وهو في المصنف (2/139) حدثنا غندر، عن ابن جريج، قال: أخبرني عمر بن عطاء ابن أبي الخُوار فذكره.","grade":"صحيح","chapter_ar":"باب استحباب الانتقال للتطوع من مكان الفريضة، أو الفصل بالكلام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (883)","chapter_en":"Recommending changing one’s place for voluntary prayer after the obligatory prayer, or separating by speech","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":22,"content":{"translation":{"en":["‘Umar ibn ‘Ata’ ibn Abi al-Khawwar narrated that Nafi‘ ibn Jubayr sent him to al-Sa’ib (the son of Namir’s sister) to ask him about something Mu‘awiyah had seen him do in prayer. He said: Yes. I prayed Jumu‘ah with him in the enclosed area. When the imam gave salam, I stood in my place and prayed. When he went inside, he sent for me and said: Do not repeat what you did. When you have prayed Jumu‘ah, do not join it to another prayer until you speak or you go out. For the Messenger of Allah ﷺ commanded us not to connect one prayer to another until we speak or we go out."]},"buhuth":{"en":["The “enclosed area” is the chamber built inside the mosque; Mu‘awiyah introduced it after a Kharijite struck him."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3352],"tks":"صحيح: رواه مسلم (883)."},{"num":2468,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى الْعَصْرَ، فَقَامَ رَجُلٌ يُصَلِّي، فَرَآهُ عُمَرُ فَقَالَ لَهُ: اجْلِسْ، فَإِنَّمَا هَلَكَ أَهْلُ الْكِتَابِ أَنَّهُ لَمْ يَكُنْ لِصَلَاتِهِمْ فَصْلٌ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَحْسَنَ ابْنُ الْخَطَّابِ."],"takhrij":"صحيح: رواه أحمد (23121) عن محمد بن جعفر، حدثنا شعبة، عن الأزرق بن قيس، عن عبدالله بن رباح، عن رجل من أصحاب النبي صلى الله عليه وسلم فذكره.","grade":"صحيح","chapter_ar":"باب استحباب الانتقال للتطوع من مكان الفريضة، أو الفصل بالكلام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAhmad (23121)","chapter_en":"Recommending changing one’s place for voluntary prayer after the obligatory prayer, or separating by speech","part_en":"Prayer (Ṣalāh)","group_ar":"جموع ما جاء في السنن الرواتب والنوافل مطلقاً","group_en":"Combined sections: voluntary prayers and regular sunnah prayers (general)","part_no":9,"group_no":9,"chapter_no":22,"content":{"translation":{"en":["A man from the Companions of the Prophet reported that the Messenger of Allah ﷺ prayed ‘Asr. Then a man stood to pray, and ‘Umar saw him and said: “Sit down. The People of the Book were only ruined because there was no separation between their prayers.” So the Messenger of Allah ﷺ said: “Ibn al-Khattab has done well.”"]},"buhuth":{"en":["The reports of this chapter show that one should not connect an obligatory prayer to a voluntary prayer without a break, out of fear of confusion. The Prophet ﷺ guided to this by either moving forward to another spot or speaking. This is indicated by Mu‘awiyah’s report, and by the report about moving aside; even if that report were not established, the wording in Mu‘awiyah’s report—“or go out”—is close in meaning.","If a person engages after salam in the prescribed remembrances, that is sufficient. This is the view of the majority of scholars, based on the wording in Mu‘awiyah’s report: “or speak.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (23121)."},{"num":2469,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ أَحَدَكُمْ إِذَا قَامَ يُصَلِّي، جَاءَ الشَّيْطَانُ، فَلَبَسَ عَلَيْهِ. حَتَّى لاَ يَدْرِيَ كَمْ صَلَّى، فَإِذَا وَجَدَ ذَلِكَ أَحَدُكُمْ فَلْيَسْجُدْ سَجْدَتَيْنِ، وَهُوَ جَالِسٌ."],"takhrij":"متفق عليه: رواه مالك في السهو (1) عن ابن شهاب، عن أبي سلمة بن عبد الرحن بن عوف، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في سجدتي السهو والبناء على اليقين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon\nMalik (1); al-Bukhari (1232); Muslim (82)","chapter_en":"What has come regarding the two prostrations of forgetfulness and building on certainty","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب السهو","group_en":"Comprehensive Sections on Forgetfulness in Prayer","part_no":9,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “When one of you stands to pray, Satan comes to him and confuses him until he does not know how much he has prayed. If that happens to one of you, then let him prostrate twice while he is sitting.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (1) والبخاري (1232)، ومسلم (82)."},{"num":2470,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا نُودِيَ بِالصَّلاَةِ أَدْبَرَ الشَّيْطَانُ وَلَهُ ضُرَاطٌ حَتَّى لاَ يَسْمَعَ الأَذَانَ، فَإِذَا قُضِيَ الأَذَانُ أَقْبَلَ، فَإِذَا ثُوِّبَ بِهَا أَدْبَرَ، فَإِذَا قُضِيَ التَّثْوِيبُ أَقْبَلَ حَتَّى يَخْطِرَ بَيْنَ الْمَرْءِ وَنَفْسِهِ، يَقُولُ: اذْكُرْ كَذَا وَكَذَا مَا لَمْ يَكُنْ يَذْكُرُ حَتَّى يَظَلَّ الرَّجُلُ إِنْ يَدْرِي كَمْ صَلَّى، فَإِذَا لَمْ يَدْرِ أَحَدُكُمْ كَمْ صَلَّى ثَلاَثًا أَوْ أَرْبَعًا فَلْيَسْجُدْ سَجْدَتَيْنِ وَهْوَ جَالِسٌ."],"takhrij":"متفق عليه: رواه البخاري في السهو (1231)، ومسلم في المساجد (83 الرقم الصغير) كلاهما من طريق هشام بن أبي عبدالله الدستوائي، عن يحيى بن أبي كثير، عن أبي سلمة بن عبدالرحمن، عن أبي هريرة فذكر مثله ولفظهما سواء. ورواه مسلم من وجه آخر وزاد فيه: فهنَّاه ومنَّاه، وذَكَّره من حاجاته ما لم يكُن يذكرُه .","grade":"متفق عليه","chapter_ar":"باب ما جاء في سجدتي السهو والبناء على اليقين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon\nal-Bukhari (1231); Muslim (83)","chapter_en":"What has come regarding the two prostrations of forgetfulness and building on certainty","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب السهو","group_en":"Comprehensive Sections on Forgetfulness in Prayer","part_no":9,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “When the call to prayer is made, Satan turns away, breaking wind so that he will not hear the call. When the call is finished, he comes back. When the call is made for the prayer (the second call), he turns away again; and when that is finished, he returns until he comes between a person and his own self, saying: ‘Remember this, remember that’—things he did not remember before—until the man ends up not knowing how much he prayed. If one of you does not know how much he prayed—three or four—then let him prostrate twice while he is sitting.”"]},"buhuth":{"en":["The phrase “إن يدري” uses “إن” as a negation meaning “does not.”","“Tuwiba” refers to the second call connected to the prayer—its commencement and being called to (i.e., the iqamah/second summons)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري ( 1231)، ومسلم (83)."},{"num":2471,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِذَا شَكَّ أَحَدُكُمْ فِي صَلَاتِهِ فَلَمْ يَدْرِ كَمْ صَلَّى؟ ثَلَاثًا أَمْ أَرْبَعًا، فَلْيَطْرَحِ الشَّكَّ، وَلْيَبْنِ عَلَى مَا اسْتَيْقَنَ. ثُمَّ يَسْجُدُْ سَجْدَتَيْنِ قَبْلَ أَنْ يُسَلِّمَ. فَإِنْ كَانَ صَلَّى خَمْسًا شَفَعْنَ لَهُ صَلَاتَهُ، وَإِنْ كَانَ صَلَّى إِتْمَامًا لِأَرْبَعٍ كَانَتَا تَرْغِيمًا لِلشَّيْطَانِ."],"takhrij":"صحيح: رواه مسلم في المساجد (571) من طريق سليمان بن بلال، عن زيد بن أسلم عن عطاء بن يسار، عن أبي سعيد الخدري فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في سجدتي السهو والبناء على اليقين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (571)","chapter_en":"What has come regarding the two prostrations of forgetfulness and building on certainty","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب السهو","group_en":"Comprehensive Sections on Forgetfulness in Prayer","part_no":9,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Abu Sa‘id al-Khudri reported that the Messenger of Allah ﷺ said: “If one of you doubts in his prayer and does not know how much he has prayed—three or four—then let him cast aside the doubt and build upon what he is certain of. Then let him perform two prostrations before he gives salam. If he had prayed five, they will make his prayer even; and if he had completed four, then they will be a humiliation for Satan.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم ( 571)."},{"num":2472,"demo":false,"sanad":"","matn":["عَنْ عُثْمَانَ بْنِ عَفَّانَ، قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا رَسُولَ اللَّهِ، إِنِّي صَلَّيْتُ فَلَمْ أَدْرِ أَشَفَعْتُ أَمْ أَوْتَرْتُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِيَّايَ، وَأَنْ يَتَلَعَّبَ بِكُمُ الشَّيْطَانُ فِي صَلاتِكُمْ، مَنْ صَلَّى مِنْكُمْ فَلَمْ يَدْرِ أَشَفَعَ أَوْ أَوْتَرَ،، فَلْيَسْجُدْ سَجْدَتَيْنِ، فَإِنَّهُمَا تَمَامُ صَلاتِهِ."],"takhrij":"حسن: رواه الإمام أحمد (450) عن محمد بن عبدالله بن الزبير، حدثنا مسَرَّةُ بن معبد، عن يزيد بن أبي كَبْشَة، عن عثمان بن عفان فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء في سجدتي السهو والبناء على اليقين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (450)","chapter_en":"What has come regarding the two prostrations of forgetfulness and building on certainty","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب السهو","group_en":"Comprehensive Sections on Forgetfulness in Prayer","part_no":9,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["‘Uthman ibn ‘Affan reported: A man came to the Prophet ﷺ and said: “O Messenger of Allah, I prayed and I do not know whether I prayed an even number or an odd number.” The Messenger of Allah ﷺ said: “Beware that Satan plays with you in your prayer. Whoever among you prays and does not know whether he prayed an even number or an odd number, then let him prostrate twice, for they complete his prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (450)."},{"num":2473,"demo":false,"sanad":"","matn":["رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: إِذَا صَلَّى أَحَدُكُمْ فَلَا يَدْرِي كَمْ صَلَّى، ثَلَاثًا، أَوْ أَرْبَعًا، فَلْيَرْكَعْ رَكْعَةً، يُحْسِنُ رُكُوعَهَا، وَسُجُودَهَا، وَيَسْجُدُ سَجْدَتَيْنِ."],"takhrij":"صحيح: رواه ابن خزيمة (1026)، والحاكم (1/260،322) كلاهما من حديث أيوب بن سليمان بن بلال، حدثني أبو بكر بن أبي أويس، عن سليمان بن بلال، عن عمر بن محمد بن زيد، عن سالم بن عبدالله، عن عبدالله بن عمر فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في سجدتي السهو والبناء على اليقين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Khuzaymah (1026); al-Hakim (1/260, 1/322)","chapter_en":"What has come regarding the two prostrations of forgetfulness and building on certainty","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب السهو","group_en":"Comprehensive Sections on Forgetfulness in Prayer","part_no":9,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ said: “If one of you prays and does not know how much he prayed—three or four—then let him perform one additional unit, perfecting its bowing and prostration, and then let him prostrate twice.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة (1026)، والحاكم (260)."},{"num":2474,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا شَكَّ أَحَدُكُمْ فِي صَلَاتِهِ فَلَمْ يَدْرِ اثْنَتَيْنِ صَلَّى، أَوْ ثَلَاثًا، فَلْيُلْقِ الشَّكَّ، وَلْيَبْنِ عَلَى الْيَقِينِ."],"takhrij":"صحيح: رواه البيهقي في الكبرى (3808) عن أبي عبدالله الحافظ في الفوائد الكبير لأبي العباس، ثنا أبو العباس محمد بن يعقوب، ثنا أحمد بن حازم بن أبي غرزة، أنبأ جعفر، أنبأ سعيد بن أبي عروبة، عن قتادة، عن أنس فذكره. وإسناده صحيح وجعفر هو: ابن عون ثقة من رجال الشيخين.","grade":"صحيح","chapter_ar":"باب ما جاء في سجدتي السهو والبناء على اليقين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bayhaqi, al-Sunan al-Kubra (2/333)","chapter_en":"What has come regarding the two prostrations of forgetfulness and building on certainty","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب السهو","group_en":"Comprehensive Sections on Forgetfulness in Prayer","part_no":9,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Anas narrated from the Prophet ﷺ that he said: “If one of you doubts in his prayer and does not know whether he prayed two or three, then let him discard the doubt and build upon certainty.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البيهقي في الكبرى (3808)."},{"num":2475,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ انْصَرَفَ مِنَ اثْنَتَيْنِ. فَقَالَ لَهُ ذُو الْيَدَيْنِ: أقَصُرَتِ الصَّلاَةُ أَمْ نَسِيتَ يـا رَسُولَ اللَّهِ؟ فقــــــــال رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَصَدَقَ ذُو الْيَدَيْنِ؟ فَقَالَ النَّاسُ: نَعَمْ. فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فصَلَّى رَكْعَتَيْنِ أُخْرَيين، ثُمَّ سلَّم، ثُمَّ كبَّر فَسَجَدَ مِثْلَ سُجُودِهِ أَوْ أَطْوَلَ، ثُمَّ رَفَعَ، ثُمَّ كبَّر فَسَجَدَ مِثل سُجُودِهِ أَوْ أَطْوَلَ، ثُمَّ رَفَعَ."],"takhrij":"متفق عليه: رواه مالك في الصلاة (58) عن أيوب بن أبي تميمة السختيان، عن محمد بن سيرين، عن أبي هريرة فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء في سجود السّهو بعد التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon\nMalik (58); al-Bukhari (714); Muslim (573)","chapter_en":"What has come regarding the prostration of forgetfulness after the salam","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب السهو","group_en":"Comprehensive Sections on Forgetfulness in Prayer","part_no":9,"group_no":10,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ finished after two units. Dhul-Yadayn said to him: “Has the prayer been shortened, or did you forget, O Messenger of Allah?” The Messenger of Allah ﷺ said: “Is Dhul-Yadayn telling the truth?” The people said: “Yes.” So the Messenger of Allah ﷺ stood and prayed two additional units, then gave salam. Then he said “Allāhu akbar” and prostrated like his prostration—or longer—then he raised his head, then said “Allāhu akbar” and prostrated like his prostration—or longer—then he raised his head."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (58)، والبخاري (714)، ومسلم (573)."},{"num":2476,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى الْعَصْرَ فَسَلَّمَ فِي ثَلَاثِ رَكَعَاتٍ، ثُمَّ دَخَلَ مَنْزِلَهُ، فَقَامَ إِلَيْهِ رَجُلٌ - يُقَالُ لَهُ: الْخِرْبَاقُ، وَكَانَ فِي يَدَيْهِ طُولٌ، - فَقَالَ: يَا رَسُولَ اللَّهِ، فَذَكَرَ لَهُ صَنِيعَهُ. وَخَرَجَ غَضْبَانَ يَجُرُّ رِدَاءَهُ حَتَّى انْتَهَى إِلَى النَّاسِ، فَقَالَ: أَصَدَقَ هَذَا؟ قَالُوا: نَعَمْ. فَصَلَّى رَكْعَةً، ثُمَّ سَلَّمَ، ثُمَّ سَجَدَ سَجْدَتَيْنِ، ثُمَّ سَلَّمَ."],"takhrij":"صحيح: رواه مسلم في المساجد (574) من طريق عبدالوهاب الثقفي، وإسماعيل بن إبراهيم (المعروف بابن عُلية) كلاهما عن خالد الحذاء، عن أبي قلابة، عن أبي المهلب، عن عمران بن حصين فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في سجود السّهو بعد التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nMuslim (574)","chapter_en":"What has come regarding the prostration of forgetfulness after the salam","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب السهو","group_en":"Comprehensive Sections on Forgetfulness in Prayer","part_no":9,"group_no":10,"chapter_no":2,"content":{"translation":{"en":["‘Imran ibn Husayn reported that the Messenger of Allah ﷺ prayed ‘Asr and gave salam after three units. When he entered his house, a man called al-Khirbaq—who had long arms—stood up to him and mentioned what had happened. The Prophet ﷺ came out angry, dragging his cloak, until he reached the people and said: “Is this man telling the truth?” They said: “Yes.” So he prayed one unit, then gave salam, then performed two prostrations, then gave salam."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (574)."},{"num":2477,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَهَا فَسَلَّم فِي الرَّكْعَتَيْنِ، فَقَالَ لَهُ رَجُلٌ يُقَالُ لَهُ ذُو الْيَدَيْنِ: يَا رَسُولَ اللَّهِ! أَقَصُرتْ أَوْ نَسيتَ؟ قَالَ: مَا قَصُرَتْ وَمَا نَسِيتُ قَالَ: إذاً فَصليتَ رَكْعَتَيْنِ. قَالَ: أَكَمَا يَقُولُ ذُو الْيَدَيْنِ؟ قَالُوا: نَعَمْ. فَتَقَدَّمَ فَصَلَّى رَكْعَتَيْنِ، ثُمَّ سلَّم، ثُمَّ سَجَدَ سجدتي السَّهْوِ."],"takhrij":"صحيح: رواه أبو داود (1017)، وابن ماجة (1213) عن أبي كريب الهمداني، عن أبي أسامة، عن عبيدالله بن عمر، عن نافع، عن ابن عمر فذكر مثله. واللفظ لابن ماجة، لأن أبا داود أحال على لفظ حديث أبي هريرة.","grade":"صحيح","chapter_ar":"باب ما جاء في سجود السّهو بعد التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nAbu Dawud (1017); Ibn Majah (1213)","chapter_en":"What has come regarding the prostration of forgetfulness after the salam","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب السهو","group_en":"Comprehensive Sections on Forgetfulness in Prayer","part_no":9,"group_no":10,"chapter_no":2,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ forgot and gave salam after two units. A man called Dhul-Yadayn said: “O Messenger of Allah, has the prayer been shortened, or did you forget?” He said: “It has not been shortened, and I did not forget.” Dhul-Yadayn said: “Then you prayed only two units.” He said: “Is Dhul-Yadayn saying what is true?” They said: “Yes.” So he went forward and prayed two units, then gave salam, then performed the two prostrations of forgetfulness."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1017)، وابن ماجه (1213)."},{"num":2478,"demo":false,"sanad":"","matn":["أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى الظُّهْرَ خَمْسًا، فَقِيلَ لَهُ: أَزِيدَ فِي الصَّلاَةِ؟ فَقَالَ: وَمَا ذَاكَ. قَالَ: صَلَّيْتَ خَمْسًا. فَسَجَدَ سَجْدَتَيْنِ بَعْدَ مَا سَلَّمَ."],"takhrij":"متفق عليه: رواه البخاري في السهو (1226)، ومسلم في المساجد (91 الرقم الصغير) كلاهما من حديث شعبة، عن الحكم، عن إبراهيم، عن علقمة، عن عبدالله بن مسعود فذكر مثله ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب ما جاء في سجود السّهو بعد التسليم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon\nal-Bukhari (1226); Muslim (91)","chapter_en":"What has come regarding the prostration of forgetfulness after the salam","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب السهو","group_en":"Comprehensive Sections on Forgetfulness in Prayer","part_no":9,"group_no":10,"chapter_no":2,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud reported that the Messenger of Allah ﷺ prayed Dhuhr as five units. It was said to him: “Has something been added to the prayer?” He said: “What is that?” They said: “You prayed five.” So he prostrated twice after he had said salam."]},"buhuth":{"en":["The two narrations also report that he folded his legs, faced the direction of prayer, and prostrated twice, then gave salam. Then he turned to them and said that if something new had been introduced into the prayer he would have informed them, but he is a human being like them and forgets as they forget; if he forgets, they should remind him. If someone doubts in his prayer, he should try to determine what is correct, complete the prayer upon that, then give salam, then prostrate twice. Another narration in Muslim states that he performed the two prostrations of forgetfulness after salam and speaking."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1226)، ومسلم (91 الرقم الصغير)."},{"num":2479,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن بُحينة، أنه قَالَ: صَلَّى لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَكْعَتَيْنِ، ثُمَّ قَامَ فَلَمْ يَجْلِسْ، فَقَامَ النَّاسُ مَعَهُ. فَلَمَّا قَضَى صَلَاتَهُ، وَنَظَرْنَا تَسْلِيمَهُ، كبَّر، ثُمَّ سَجَدَ سَجْدَتَيْنِ، وَهُوَ جَالِسٌ قَبْلَ التَّسْلِيمِ، ثُمَّ سَلَّم."],"takhrij":"متفق عليه: رواه مالك في الصلاة (65) عن ابن شهاب، عن الأعرج، عن عبدالله بن بحينة فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء في سجود السهو قبل التسليم وأنه لا تشهد فيه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon\nMalik (65); al-Bukhari (1224); Muslim (570)","chapter_en":"What has come regarding prostration of forgetfulness before salam, and that there is no tashahhud in it","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب السهو","group_en":"Comprehensive Sections on Forgetfulness in Prayer","part_no":9,"group_no":10,"chapter_no":3,"content":{"translation":{"en":["‘Abdullah ibn Buhaynah reported that the Messenger of Allah ﷺ led us in prayer for two rakʿahs, then stood up without sitting, and the people stood with him. When he finished his prayer and we were expecting his salam, he said “Allāhu akbar,” then prostrated twice while sitting before the salam, then he gave salam."]},"buhuth":{"en":["Al-Tirmidhi’s wording adds that when he completed his prayer, he prostrated twice, saying “Allāhu akbar” for each prostration, while sitting before the salam; and the people prostrated with him as compensation for the sitting that was missed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (65) والبخاري (1224)، ومسلم (570)."},{"num":2480,"demo":false,"sanad":"","matn":["عَنْ قَيْسِ بْنِ أَبِي حَازِمٍ ، قَالَ: : صَلَّى بِنَا الْمُغِيرَةُ بْنُ شُعْبَةَ، ، فَقَامَ مِنَ الرَّكْعَتَيْنِ قَائِمًا، ، فَقُلْنَا: : \" سُبْحَانَ اللهِ، \" فَأَوْمَى وَقَالَ: : \" سُبْحَانَ اللهِ، \" فَمَضَى فِي صَلَاتِهِ، .فَلَمَّا قَضَى صَلَاتَهُ وَسَلَّمَ، ، سَجَدَ سَجْدَتَيْنِ وَهُوَ جَالِسٌ، ، ثُمَّ قَالَ: : صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ، فَاسْتَوَى قَائِمًا مِنْ جُلُوسِهِ، ، فَمَضَى فِي صَلَاتِهِ، .فَلَمَّا قَضَى صَلَاتَهُ ، سَجَدَ سَجْدَتَيْنِ وَهُوَ جَالِسٌ، ، ثُمَّ قَالَ: : إِذَا صَلَّى أَحَدُكُمْ فَقَامَ مِنَ الْجُلُوسِ، ، فَإِنْ لَمْ يَسْتَتِمَّ قَائِمًا ، فَلْيَجْلِسْ، ، وَلَيْسَ عَلَيْهِ سَجْدَتَانِ، ، فَإِنِ اسْتَوَى قَائِمًا ، فَلْيَمْضِ فِي صَلَاتِهِ، ، وَلْيَسْجُدْ سَجْدَتَيْنِ وَهُوَ جَالِسٌ."],"takhrij":"صحيح: رواه الطّحاوي في شرحه (2499) عن ابن مرزوق، قال: ثنا أبو عامر، عن إبراهيم بن طهمان، عن المغيرة بن شُبيل، عن قيس بن أبي حازم فذكر مثله.","grade":"صحيح","chapter_ar":"باب من قام من الركعتين فإن استوى فلْيَمْض وإلا فيجلس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Tahawi, Sharh (2499)","chapter_en":"Whoever rises after two units: if he becomes fully upright, let him continue; otherwise, let him sit","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب السهو","group_en":"Comprehensive Sections on Forgetfulness in Prayer","part_no":9,"group_no":10,"chapter_no":4,"content":{"translation":{"en":["Qays ibn Abi Hazim said: al-Mughirah ibn Shu‘bah led us in prayer, and he stood up after two units. We said: “Subhan Allah,” and he gestured and said: “Subhan Allah,” and continued. When he finished and gave salam, he prostrated twice while sitting. Then he said: The Messenger of Allah ﷺ once stood up fully after rising from the sitting, and he continued his prayer; then when he finished, he prostrated twice while sitting. Then he said: “If one of you prays and rises from the sitting: if he has not yet become fully upright, then let him sit back down and there are no two prostrations upon him. But if he becomes fully upright, then let him continue in his prayer and prostrate twice while sitting.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطحاوي في شرحه (2499)."},{"num":2481,"demo":false,"sanad":"","matn":["عن عمرو بن العاص أنه صَلَّى بِالنَّاسِ، فَقَامَ عَنْ تَشَهُّدِهِ، فَصَاحَ بِهِ النَّاسُ فَقَالُوا: سُبْحَانَ اللَّهِ، سُبْحَانَ اللَّهِ، فَصَلَّى كَمَا هُوَ، فَلَمَّا أَتَمَّ صَلَاتَهُ سَجَدَ سَجْدَتَيْنِ ثُمَّ قَالَ: \" أَيُّهَا النَّاسُ إِنَّهُ لَمْ يَخْفَ عَلَيَّ الَّذِي أَرَدْتُمْ، وَلَمْ يَمْنَعْنِي مِنَ الْجُلُوسِ إِلَّا الَّذِي صَنَعْتُ مِنَ السُّنَّةِ."],"takhrij":"صحيح: رواه ابن أبي عمر العدني قال: ثنا حيوة، أخبرني يزيد بن أبي حبيب، حدثني عبدالرحمن بن شِماسة، قال: صلى عمرو بن العاص بالناس فذكره.","grade":"صحيح","chapter_ar":"باب من قام من الركعتين فإن استوى فلْيَمْض وإلا فيجلس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nIbn Abi ‘Umar al-‘Adani, Ithaf al-Maharah (2106)","chapter_en":"Whoever rises after two units: if he becomes fully upright, let him continue; otherwise, let him sit","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب السهو","group_en":"Comprehensive Sections on Forgetfulness in Prayer","part_no":9,"group_no":10,"chapter_no":4,"content":{"translation":{"en":["‘Amr ibn al-‘As led the people in prayer and stood up leaving his tashahhud. The people called out to him: “Subhan Allah, Subhan Allah,” but he continued as he was. When he completed his prayer, he prostrated twice and then said: “O people, what you wanted was not hidden from me; nothing prevented me from sitting except that I acted according to the Sunnah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن أبي عمر العدني (( إتحاف المهرة)) (2106)."},{"num":2482,"demo":false,"sanad":"","matn":["عن عُقْبَةَ بن عَامِرٍ الجهني قَامَ، وَعَلَيْهِ جُلُوسٌ، فَقَالَ النَّاسُ: سُبْحَانَ اللَّهِ، سُبْحَانَ اللَّهِ، فَلَمْ يَجْلِسْ، وَمَضَى عَلَى قِيَامِهِ، فَلَمَّا كَانَ فِي آخِرِ صَلَاتِهِ سَجَدَ سَجْدَتَيْنِ، وَهُوَ جَالِسٌ، فَلَمَّا سَلَّمَ قَالَ: إِنِّي سَمِعْتُكُمْ آنِفًا تَقُولُونَ: سُبْحَانَ اللَّهِ، لِكَيْمَا أَجْلِسَ، لَكِنَّ السُّنَّةَ الَّذِي صَنَعْتُ."],"takhrij":"صحيح: رواه الحارث بن أبي أسامة بغية الباحث (187)، والحاكم (1214) كلاهما من طريق يزيد بن أبي حبيب، أنه سمع عبدالرحمن بن شماسة المهري، يقول: صلى بنا عقبة بن عامر فذكر مثله واللفظ للحاكم.","grade":"صحيح","chapter_ar":"باب من قام من الركعتين فإن استوى فلْيَمْض وإلا فيجلس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Harith ibn Abi Usamah, Bughyat al-Bahith (187); al-Hakim (1/325) — wording as in al-Hakim","chapter_en":"Whoever rises after two units: if he becomes fully upright, let him continue; otherwise, let him sit","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب السهو","group_en":"Comprehensive Sections on Forgetfulness in Prayer","part_no":9,"group_no":10,"chapter_no":4,"content":{"translation":{"en":["‘Uqbah ibn ‘Amir al-Juhani stood up when he should have been sitting. The people said: “Subhan Allah, Subhan Allah,” but he did not sit and continued standing. At the end of his prayer he prostrated twice while sitting. When he gave salam, he said: “I heard you earlier saying: ‘Subhan Allah,’ so that I would sit, but what I did is the Sunnah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الحارث بن أبي أسامة في بغية الباحث (187)، والحاكم (1214) واللفظ للحاكم."},{"num":2483,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَأَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى بِهِمْ صَلَاةَ الْعَصْرِ، أَوِ الظُّهْرِ، فَقَامَ فِي رَكْعَتَيْنِ فَسَبَّحُوا لَهُ فَمَضَى فِي صَلَاتِهِ. فَلَمَّا قَضَى الصَّلَاةَ سَجَدَ سَجْدَتَيْنِ، ثُمَّ سَلَّمَ."],"takhrij":"صحيح: رواه البزار كشف الأستار (576) عن الحسن بن يحيى الأزدي، ثنا أبو زيد سعيد بن الربيع، ثنا علي بن المبارك، عن يحيى بن أبي كثير، عن ضمضم بن جَوس، عن أبي هريرة فذكر مثله.","grade":"صحيح","chapter_ar":"باب من قام من الركعتين فإن استوى فلْيَمْض وإلا فيجلس","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic\nal-Bazzar, Kashf al-Astar (576)","chapter_en":"Whoever rises after two units: if he becomes fully upright, let him continue; otherwise, let him sit","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب السهو","group_en":"Comprehensive Sections on Forgetfulness in Prayer","part_no":9,"group_no":10,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ led them in ‘Asr—or Dhuhr—and he stood up after two units. They said “Subhan Allah” to alert him, but he continued. When he finished the prayer, he prostrated twice, then gave salam."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البزار في كشف الأستار (576)."},{"num":2484,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ بْنِ حُدَيْجٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى يَوْمًا فَسَلَّمَ، وَقَدْ بَقِيَتْ مِنَ الصَّلاَةِ رَكْعَةٌ، فَأَدْرَكَهُ رَجُلٌ فَقَالَ: نَسِيتَ مِنَ الصَّلاَةِ رَكْعَةً. فَرَجَعَ فَدَخَلَ الْمَسْجِدَ، وَأَمَرَ بِلاَلاً فَأَقَامَ الصَّلاَةَ، فَصَلَّى لِلنَّاسِ رَكْعَةً. فَأَخْبَرْتُ بِذَلِكَ النَّاسَ. فَقَالُوا لِي: أَتَعْرِفُ الرَّجُلَ؟ قُلْتُ: لاَ إِلاَّ أَنْ أَرَاهُ فَمَرَّ بِي، فَقُلْتُ: هَذَا هُوَ. فَقَالُوا: هَذَا طَلْحَةُ بْنُ عُبَيْدِ."],"takhrij":"صحيح: رواه أبو داود (1023)، والنسائي (664) كلاهما عن قتيبة بن سعيد، حدثنا الليثُ -يعني ابن سعد- عن يزيد بن أبي حبيب، أن سويد بن سعيد أخبره عن معاوية بن حُديج فذكر مثله.","grade":"صحيح","chapter_ar":"باب الإقامة لمن نسي ركعة من الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nAbu Dawud (1023); al-Nasā’ī (664)","chapter_en":"Calling the Iqāmah for the one who forgot a rak‘ah of the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب السهو","group_en":"Comprehensive Sections on Forgetfulness in Prayer","part_no":9,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Mu‘āwiyah ibn Ḥudayj reported that the Messenger of Allah ﷺ prayed one day and gave salam while one rak‘ah still remained of the prayer. A man caught up to him and said: “You forgot one rak‘ah from the prayer.” So he returned, entered the mosque, and ordered Bilāl to call the iqāmah. Then he led the people in one rak‘ah. I informed the people about this, and they said to me: “Do you know the man?” I said: “No—except that I would recognize him if I saw him.” Then he passed by me, so I said: “This is him.” They said: “That is Ṭalḥah ibn ‘Ubaydillāh.”"]},"buhuth":{"en":["His statement, “and he ordered Bilāl to call the iqāmah,” has the apparent meaning that it refers to the well-known, standard iqāmah for prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1023)، والنسائي (664)."},{"num":2485,"demo":false,"sanad":"","matn":["عن عُقْبَةَ بن عَامِرٍ الْجُهَنِيَّ يَقُولُ:  ثَلَاثُ سَاعَاتٍ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَانَا أَنْ نُصَلِّيَ فِيهِنَّ، أَوْ أَنْ نَقْبُرَ فِيهِنَّ مَوْتَانَا: حِينَ تَطْلُعُ الشَّمْسُ بَازِغَةً حَتَّى تَرْتَفِعَ، وَحِينَ يَقُومُ قَائِمُ الظَّهِيرَةِ حَتَّى تَمِيلَ الشَّمْسُ، وَحِينَ تَضَيَّفُ الشَّمْسُ لِلْغُرُوبِ حَتَّى تَغْرُبَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (831) عن يحيى بن يحيى، حدثنا","grade":"صحيح","chapter_ar":"باب ثلاث ساعات كان النبي ﷺ ينهى عن الصلاة فيها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nMuslim (831).","chapter_en":"Three times in which the Prophet ﷺ used to forbid prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["‘Uqbah ibn ‘Āmir said: There are three times during which the Messenger of Allah ﷺ used to forbid us from praying—or burying our dead: when the sun rises and is visibly emerging until it rises higher; when the sun is at its midday peak until it begins to decline; and when the sun inclines toward sunset until it sets."]},"buhuth":{"en":["“بَازِغَة” means “rising / emerging,” and “تَضَيَّف” means “leaning toward sunset.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3772],"tks":"صحيح: رواه مسلم (831). وقوله: (( بازغة)) - أي طالعة. وقوله: (( تضيف)) إذا مالت للغروب."},{"num":2486,"demo":false,"sanad":"","matn":["عن عَمْرِو بْنِ عَبَسَة السُلمي قَالَ: فَقُلْتُ: يَا نَبِيَّ اللَّهِ، أَخْبِرْنِي عَمَّا عَلَّمَكَ اللَّهُ وَأَجْهَلُهُ، أَخْبِرْنِي عَنِ الصَّلَاةِ. قَالَ: صَلِّ صَلَاةَ الصُّبْحِ، ثُمَّ أَقْصِرْ عَنِ الصَّلَاةِ حَتَّى تَطْلُعَ الشَّمْسُ حَتَّى تَرْتَفِعَ، فَإِنَّهَا تَطْلُعُ حِينَ تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ، وَحِينَئِذٍ يَسْجُدُ لَهَا الْكُفَّارُ. ثُمَّ صَلِّ فَإِنَّ الصَّلَاةَ مَشْهُودَةٌ مَحْضُورَةٌ حَتَّى يَسْتَقِلَّ الظِّلُّ بِالرُّمْحِ. ثُمَّ أَقْصِرْ عَنِ الصَّلَاةِ فَإِنَّ حِينَئِذٍ تُسْجَرُ جَهَنَّمُ. فَإِذَا أَقْبَلَ الْفَيْءُ فَصَلِّ فَإِنَّ الصَّلَاةَ مَشْهُودَةٌ مَحْضُورَةٌ حَتَّى تُصَلِّيَ الْعَصْرَ. ثُمَّ أَقْصِرْ عَنِ الصَّلَاةِ حَتَّى تَغْرُبَ الشَّمْسُ، فَإِنَّهَا تَغْرُبُ بَيْنَ قَرْنَيْ شَيْطَانٍ، وَحِينَئِذٍ يَسْجُدُ لَهَا الْكُفَّارُ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (832) عن أحمد بن جعفر المعقري، حدثنا النضر بن محمد، حدثنا عكرمة بن عمار، حدثنا شداد بن عبد الله أبو عمار ويحيى بن أبي كثير، عن أبي أُمامة قال: قال عمرو بن عَبَسَة فذكر قصة إسلامه في حديث طويل سبق ذكره في ثواب الوضوء.","grade":"صحيح","chapter_ar":"باب ثلاث ساعات كان النبي ﷺ ينهى عن الصلاة فيها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nMuslim (832)","chapter_en":"Three times in which the Prophet ﷺ used to forbid prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["‘Amr ibn ‘Abasah al-Sulamī said: I said, “O Prophet of Allah ﷺ, tell me about what Allah has taught you and I am ignorant of. Tell me about prayer.” He said: “Pray the morning prayer (Fajr). Then stop praying until the sun rises and becomes high, for it rises between the two horns of Satan, and at that time the disbelievers prostrate to it. Then pray, for prayer is witnessed and attended until the shadow becomes like a spear (i.e., until the sun nears midday). Then stop praying, for at that time Hell is kindled. When the shadow returns (i.e., after the sun declines), then pray, for prayer is witnessed and attended until you pray ‘Asr. Then stop praying until the sun sets, for it sets between the two horns of Satan, and at that time the disbelievers prostrate to it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (832)."},{"num":2487,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: سَأَلَ صَفْوَانُ بْنُ الْمُعَطَّلِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ! إِنِّي سَائِلُكَ عَنْ أَمْرٍ أَنْتَ بِهِ عَالِمٌ وَأَنَا بِهِ جَاهِلٌ. قَالَ: وَمَا هُوَ. قَالَ: هَلْ مِنْ سَاعَاتِ اللَّيْلِ وَالنَّهَارِ سَاعَةٌ تُكْرَهُ فِيهَا الصَّلاَةُ؟ قَالَ: نَعَمْ. إِذَا صَلَّيْتَ الصُّبْحَ، فَدَعِ الصَّلاَةَ حَتَّى تَطْلُعَ الشَّمْسُ. فَإِنَّهَا تَطْلُعُ بِقَرْنَىِ الشَّيْطَانِ. ثُمَّ صَلِّ فَالصَّلاَةُ مَحْضُورَةٌ مُتَقَبَّلَةٌ حَتَّى تَسْتَوِيَ الشَّمْسُ عَلَى رَأْسِكَ كَالرُّمْحِ. فَإِذَا كَانَتْ عَلَى رَأْسِكَ كَالرُّمْحِ فَدَعِ الصَّلاَةَ. فَإِنَّ تِلْكَ السَّاعَةَ تُسْجَرُ فِيهَا جَهَنَّمُ وَتُفْتَحُ فِيهَا أَبْوَابُهَا. حَتَّى تَزِيغَ الشَّمْسُ عَنْ حَاجِبِكَ الأَيْمَنِ. فَإِذَا زَالَتْ فَالصَّلاَةُ مَحْضُورَةٌ مُتَقَبَّلَةٌ حَتَّى تُصَلِّيَ الْعَصْرَ. ثُمَّ دَعِ الصَّلاَةَ حَتَّى تَغِيبَ الشَّمْسُ."],"takhrij":"حسن: رواه ابن ماجه (1252) عن الحسن بن داود المنكدري، حدثنا ابن أبي فُديك، عن الضحاك بن عثمان، عن المقبري، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ثلاث ساعات كان النبي ﷺ ينهى عن الصلاة فيها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nIbn Mājah (1252); Ibn Ḥibbān (1542); al-Bayhaqī (2/455)","chapter_en":"Three times in which the Prophet ﷺ used to forbid prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: Ṣafwān ibn al-Mu‘aṭṭal asked the Messenger of Allah ﷺ: “O Messenger of Allah, I will ask you about something you know and I do not.” He said: “What is it?” He asked: “Is there any hour of night or day in which prayer is disliked?” He said: “Yes. When you have prayed Fajr, then leave prayer until the sun rises, for it rises with the horns of Satan. Then pray, for prayer is attended and accepted until the sun is overhead like a spear. When it is overhead like a spear, then leave prayer, for at that time Hell is kindled and its gates are opened, until the sun declines from your right eyebrow. When it declines, then prayer is attended and accepted until you pray ‘Asr. Then leave prayer until the sun sets.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1252)، وابن حبان (1542)، والبيهقي (4387)."},{"num":2488,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، قَالَ: نُهِيَ عَنِ الصَّلاةِ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ، وَبَعْدَ الْفَجْرِ، أَوْ قَالَ: بَعْدَ صَلاةِ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ، وَبِنِصْفِ النَّهَارِ، قَالَ: فِي شِدَّةِ الْحَرِّ."],"takhrij":"حسن: رواه البزار الكشف (614) عن العباس بن جعفر، ثنا الوليد بن صالح، عن أبي بكر بن عياش، عن عاصم، عن زِر، عن عبدالله فذكره.","grade":"حسن","chapter_ar":"باب ثلاث ساعات كان النبي ﷺ ينهى عن الصلاة فيها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nal-Bazzār, al-Kashf (614)","chapter_en":"Three times in which the Prophet ﷺ used to forbid prayer","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ūd said: Prayer was forbidden after ‘Asr until the sun sets, and after Fajr—or he said, after the morning prayer—until the sun rises, and at midday. He said: during intense heat."]}},"tuhfa":{},"voc":["sh12862",615],"full":1,"dr":1,"tks":"حسن: رواه البزار في الكشف (614)."},{"num":2489,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: شَهِدَ عِنْدِي رِجَالٌ مَرْضِيُّونَ، وَأَرْضَاهُمْ عِنْدِي عُمَرُ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الصَّلاَةِ بَعْدَ الصُّبْحِ حَتَّى تَشْرُقَ الشَّمْسُ، وَبَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (581)، ومسلم في صلاة المسافرين (826) كلاهما من طريق هشام، عن قتادة، قال: أخبرنا أبو العالية، عن ابن عباس فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب النهي عن الصلاة بعد الصبح وبعد العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon\nal-Bukhari (581); Muslim (826)","chapter_en":"Prohibition of prayer after Fajr and after ‘Asr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["Ibn ‘Abbās said: Reliable men testified in my presence—and the most reliable to me was ‘Umar—that the Messenger of Allah ﷺ forbade prayer after Fajr until the sun rises brightly, and after ‘Asr until the sun sets."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (581)، ومسلم (826)."},{"num":2490,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  نَهَى عَنِ الصَّلَاةِ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ، وَعَنِ الصَّلَاةِ بَعْدَ الصُّبْحِ حَتَّى تَطْلُعَ الشَّمْسُ."],"takhrij":"متفق عليه: رواه مالك في القرآن (48) عن محمد بن يحيى بن حَبَّان، عن الأعرج، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن الصلاة بعد الصبح وبعد العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon\nMālik (48); Muslim (825); al-Bukhārī (588)","chapter_en":"Prohibition of prayer after Fajr and after ‘Asr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade prayer after ‘Asr until the sun sets, and forbade prayer after Ṣubḥ (Fajr) until the sun rises."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (48) ومسلم (825)، والبخاري (588)."},{"num":2491,"demo":false,"sanad":"","matn":["عن أَبِي سَعِيدٍ الْخُدْرِيِّ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لاَ صَلاَةَ بَعْدَ الصُّبْحِ حَتَّى تَرْتَفِعَ الشَّمْسُ، وَلاَ صَلاَةَ بَعْدَ الْعَصْرِ حَتَّى تَغِيبَ الشَّمْسُ."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (586)، ومسلم في صلاة المسافرين (827) كلاهما من حديث ابن شهاب، قال: أخبرني عطاء بن يزيد الجندعي الليثي، أنه سمع أبا سعيد الخدري يقول فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب النهي عن الصلاة بعد الصبح وبعد العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon\nal-Bukhārī (586); Muslim (827)","chapter_en":"Prohibition of prayer after Fajr and after ‘Asr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["Abu Sa‘īd al-Khudrī said: I heard the Messenger of Allah ﷺ say: “There is no prayer after Ṣubḥ (Fajr) until the sun rises high, and no prayer after ‘Asr until the sun sets.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (586)، ومسلم (827)."},{"num":2492,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ، قَالَ: إِنَّكُمْ لَتُصَلُّونَ صَلاَةً، لَقَدْ صَحِبْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَمَا رَأَيْنَاهُ يُصَلِّيهَا، وَلَقَدْ نَهَى عَنْهُمَا، يَعْنِي: الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ."],"takhrij":"صحيح: رواه البخاري في المواقيت (587) عن محمد بن أبان، قال: حدثنا غندر، قال: حدثنا شعبةُ، عن أبي التيَّاح، قال: سمعتُ حمرانَ بن أبان، يحدثُ عن معاوية فذكر الحديث.","grade":"صحيح","chapter_ar":"باب النهي عن الصلاة بعد الصبح وبعد العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nal-Bukhārī (587)","chapter_en":"Prohibition of prayer after Fajr and after ‘Asr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["Mu‘āwiyah said: “You are praying a prayer. We accompanied the Messenger of Allah ﷺ and we never saw him pray it—and he forbade it,” meaning the two rak‘ahs after ‘Asr."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (587)."},{"num":2493,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَصْرَةَ الْغِفَارِيِّ قَالَ:  صَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْعَصْرَ بِالْمُخَمَّصِ، فَقَالَ: إِنَّ هَذِهِ الصَّلَاةَ عُرِضَتْ عَلَى مَنْ كَانَ قَبْلَكُمْ فَضَيَّعُوهَا. فَمَنْ حَافَظَ عَلَيْهَا كَانَ لَهُ أَجْرُهُ مَرَّتَيْنِ، وَلَا صَلَاةَ بَعْدَهَا حَتَّى يَطْلُعَ الشَّاهِدُ وَالشَّاهِدُ: النَّجْمُ."],"takhrij":"صحيح: رواه مسلم في المسافرين (830) من حديث خير بن نُعيم الحضرمي، عن عبد الله بن هبيرة السبَّائي، عن أبي تميم الجيشاني، عن أبي بصرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الصلاة بعد الصبح وبعد العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nMuslim (830)","chapter_en":"Prohibition of prayer after Fajr and after ‘Asr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["Abu Baṣrah al-Ghifārī said: The Messenger of Allah ﷺ led us in ‘Asr at al-Mukhammāṣ, then he said: “This prayer was presented to those before you, but they neglected it. Whoever preserves it will have his reward twice. And there is no prayer after it until the witness rises”—and the witness is the star."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (830)."},{"num":2494,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عمرو قَالَ: إن رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطَبَهُمْ وَهُوَ مُسْنِدٌ ظَهْرَهُ إِلَى الْكَعْبَةِ فَقَالَ: لَا صَلَاةَ بَعْدَ الْعَصْرِ حَتَّى تغرُبَ الشَّمْسُ، وَلَا صَلَاةَ بَعْدَ صَلَاةِ الْغَدَاةِ حَتَّى تَطْلُعَ الشَّمْسُ ."],"takhrij":"حسن: رواه الإمام أحمد (6970) عن عبد الصمد (ابن عبد الوارث) حدثنا خليفة، عن عمرو بن شعيب، عن أبيه، عن جده (عبد الله بن عمرو بن العاص) فذكر مثله.","grade":"حسن","chapter_ar":"باب النهي عن الصلاة بعد الصبح وبعد العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAḥmad (6970); Abū Dāwūd al-Ṭayālisī (2374)","chapter_en":"Prohibition of prayer after Fajr and after ‘Asr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["Ibn ‘Amr said: The Messenger of Allah ﷺ addressed them while leaning his back against the Ka‘bah and said: “There is no prayer after ‘Asr until the sun sets, and no prayer after the morning prayer (al-ghadāh) until the sun rises.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (6970)، وأبو داود الطيالسي (2374)."},{"num":2495,"demo":false,"sanad":"","matn":["عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ قَالَ: كُنْتُ أُسَافِرُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَمَا رَأَيْتُهُ صَلَّى بَعْدَ الْعَصْرِ، وَلَا بَعْدَ الصُّبْحِ قَطُّ."],"takhrij":"صحيح: رواه الإمام أحمد (16535) عن عبد الرحمن بن مهدي، عن زهير. وحدثنا يحيى بن أبي بكير، قال: حدثنا زهير بن محمد، عن يزيد بن خُصَيفَة، عن سلمة بن الأكوع فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الصلاة بعد الصبح وبعد العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nAḥmad (16535)","chapter_en":"Prohibition of prayer after Fajr and after ‘Asr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["Salamah ibn al-Akwa‘ said: I used to travel with the Messenger of Allah ﷺ, and I never saw him pray after ‘Asr, nor after Ṣubḥ (Fajr), ever."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (16535)."},{"num":2496,"demo":false,"sanad":"","matn":["الْبَزَّارُ، وَلَفْظُهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الصَّلَاةِ بَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ، وَبَعْدَ الْفَجْرِ حَتَّى تَطْلُعَ الشَّمْسُ."],"takhrij":"حسن: رواه البزار كشف الأستار (613) عن محمد بن المثنى أبي موسى، ثنا رَوح بن عبادة، عن أسامة بن زيد، عن حفص، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب النهي عن الصلاة بعد الصبح وبعد العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nal-Bazzār, Kashf al-Astār (613)","chapter_en":"Prohibition of prayer after Fajr and after ‘Asr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Mālik reported that the Prophet ﷺ forbade prayer after ‘Asr until the sun sets, and after Fajr until the sun rises."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (613)."},{"num":2497,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ ، قَالَ: : كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي عَلَى إِثْرِ كُلِّ صَلاةٍ مَكْتُوبَةٍ رَكْعَتَيْنِ إِلا الْفَجْرَ وَالْعَصْرَ."],"takhrij":"صحيح: رواه ابن خزيمة (1196) قال: ثنا بندار، ثنا عبد الرحمن، نا سفيان، ح وثنا محمد بن العلاء بن كُريب، ثنا أبو خالد الأحمر، ثنا سفيان، ح وثنا سَلْم بن جُنادة، ثنا وكيع، عن سفيان، عن أبي إسحاق، عن عاصم بن ضَمْرة، عن علي فذكر مثله.","grade":"صحيح","chapter_ar":"باب النهي عن الصلاة بعد الصبح وبعد العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nIbn Khuzaymah (1196)","chapter_en":"Prohibition of prayer after Fajr and after ‘Asr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["‘Alī ibn Abī Ṭālib said: The Messenger of Allah ﷺ used to pray two rak‘ahs after every obligatory prayer, except after Fajr and ‘Asr."]}},"tuhfa":{},"voc":["ibnkhuzaymah",1199],"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة (1196)."},{"num":2498,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا صَلَاةَ بَعْدَ الْعَصْرِ حَتَّى تَغِيبَ الشَّمْسُ، وَلَا بَعْدَ الصُّبْحِ حَتَّى تَرْتَفِعَ الشَّمْسُ أَوْ تَضْحَى."],"takhrij":"صحيح: رواه الإمام أحمد (5010) عن يزيد، أخبرنا ابن أبي ذئب، عن مسلم الخبَّاط، عن ابن عمر، قال: نهى رسول الله صلى الله عليه وسلم أن يُتلقَّى الركبانُ أو يبيع حاضر لبادٍ، ولا يخطبَ أحدكم على خطبة أخيه حتى ينكح أو يدعَ، ولا صلاة بعد العصر حتى تغيبَ الشمس، ولا بعد الصُّبح حتى ترتفع الشمسُ، أو تَضْحى.","grade":"صحيح","chapter_ar":"باب النهي عن الصلاة بعد الصبح وبعد العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nAḥmad (5010)","chapter_en":"Prohibition of prayer after Fajr and after ‘Asr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["Ibn ‘Umar reported from the Prophet ﷺ that he said: “There is no prayer after ‘Asr until the sun sets, and no prayer after Ṣubḥ (Fajr) until the sun rises high and becomes bright.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (5010)."},{"num":2499,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ يَتَحَرَّى أَحَدُكُمْ فَيُصَلِّي عِنْدَ طُلُوعِ الشَّمْسِ، وَلاَ عِنْدَ غُرُوبِهَا."],"takhrij":"متفق عليه: رواه مالك في القرآن (47) عن نافع، عن عبد الله بن عمر فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب النهي عن الصلاة عند طلوع الشمس وعند غروبها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon\nMālik (47); al-Bukhārī (585); Muslim (828)","chapter_en":"Prohibition of praying at sunrise and at sunset","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":3,"content":{"translation":{"en":["Ibn ‘Umar reported that the Messenger of Allah ﷺ said: “None of you should deliberately time his prayer to coincide with the rising of the sun or its setting.”"]},"buhuth":{"en":["In another narration in both: “Do not deliberately time your prayer at sunrise or sunset.”","Muslim adds: “For it rises with the horns of Satan.”","In al-Bukhārī and Muslim: “When the edge of the sun appears, delay prayer until it rises higher; and when the edge of the sun disappears, delay prayer until it fully sets.”","In another wording in both: “Do not time your prayer at sunrise or sunset, for it rises between the two horns of Satan (or: the Satan).” ‘Abdah said, as reported in al-Bukhari: “I do not know which of the two wordings Hisham said” (3273).","The statement “it rises between the two horns of Satan” is understood with respect to the observer at sunrise; if the observer could see Satan, he would see him standing in line with it. (As mentioned in al-Fatḥ, 6/340.)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (47)، والبخاري (585)، ومسلم (828)."},{"num":2500,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا قَالَتْ:  لَمْ يَدَعْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ. قَالَ: فَقَالَتْ عَائِشَةُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَتَحَرَّوْا طُلُوعَ الشَّمْسِ، وَلَا غُرُوبَهَا، فَتُصَلُّوا عِنْدَ ذَلِكَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (833/296) عن حسن الحلُواني، ثنا عبد الرزاق، أخبرنا معمر، عن ابن طاوس، عن أبيه، عن عائشة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب النهي عن الصلاة عند طلوع الشمس وعند غروبها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nMuslim (296/833)","chapter_en":"Prohibition of praying at sunrise and at sunset","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":3,"content":{"translation":{"en":["‘Ā’ishah said: The Messenger of Allah ﷺ never left the two rak‘ahs after ‘Asr. Then she said: The Messenger of Allah ﷺ said: “Do not deliberately time prayer at the rising of the sun or its setting, so that you pray at that time.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (833/296)."},{"num":2501,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا قَالَتْ:  وَهِمَ عُمَرُ إِنَّمَا نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُتَحَرَّى طُلُوعُ الشَّمْسِ وَغُرُوبُهَا."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (833) عن محمد بن حاتم، حدثنا بهز، حدثنا وُهَيب، حدثنا عبد الله بن طاوس، عن أبيه، عن عائشة فذكرت مثله.","grade":"صحيح","chapter_ar":"باب النهي عن الصلاة عند طلوع الشمس وعند غروبها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nMuslim (833)","chapter_en":"Prohibition of praying at sunrise and at sunset","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":3,"content":{"translation":{"en":["‘Ā’ishah said: ‘Umar was mistaken; rather, the Messenger of Allah ﷺ only forbade deliberately timing prayer at sunrise and sunset."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (833)."},{"num":2502,"demo":false,"sanad":"","matn":["عَنْ بِلَالٍ، قَالَ: لَمْ يَكُنْ يَنْهَى عَنِ الصَّلَاةِ، إِلَّا عِنْدَ طُلُوعِ الشَّمْسِ، فَإِنَّهَا تَطْلُعُ بَيْنَ قَرْنَيِ الشَّيْطَانِ."],"takhrij":"صحيح: رواه الإمام أحمد (23887) عن وكيع، عن شُعبة، عن قيس بن مسلم، عن طارق بن شِهاب، عن بلال فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الصلاة عند طلوع الشمس وعند غروبها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nAḥmad (23887); al-Ṭabarānī, al-Kabīr (1070)","chapter_en":"Prohibition of praying at sunrise and at sunset","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":3,"content":{"translation":{"en":["Bilāl said: Prayer was not prohibited except at the time of sunrise, for it rises between the two horns of Satan."]},"buhuth":{"en":["The phrase “was not prohibited” is in the passive voice; the one who prohibited it is the Prophet ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (23887) والطبراني في الكبير (1070)."},{"num":2503,"demo":false,"sanad":"","matn":["عن سَمُرَةَ بْنِ جندب، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا تُصَلُّوا حِينَ تَطْلُعُ الشَّمْسُ، وَلَا حِينَ تَسْقُطُ، فَإِنَّهَا تَطْلُعُ بَيْنَ قَرْنَيِ الشَّيْطَانِ، وَتَغْرُبُ بَيْنَ قَرْنَيِ الشَّيْطَانِ."],"takhrij":"حسن: رواه الإمام أحمد (20169) والبزار كشف الأستار (612)، والطبراني في الكبير (6973) كلُّهم من طريق شعبة، عن سِماك بن حرب قال: سمعتُ المهلب بن أبي صُفرة يحدث عن سمرة فذكر الحديث، وفي رواية: يخطب فقال: قال سمرة بن جندب فذكر الحديث.","grade":"حسن","chapter_ar":"باب النهي عن الصلاة عند طلوع الشمس وعند غروبها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAḥmad (20169); al-Bazzār, Kashf al-Astār (612); al-Ṭabarānī, al-Kabīr (6973)","chapter_en":"Prohibition of praying at sunrise and at sunset","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":3,"content":{"translation":{"en":["Samurah ibn Jundub narrated that the Prophet ﷺ said: “Do not pray when the sun is rising, nor when it is setting, for it rises between the two horns of Satan and sets between the two horns of Satan.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (20169) والبزار في كشف الأستار (612)، والطبراني في الكبير (6973)."},{"num":2504,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تُصَلُّوا عِنْدَ طُلُوعِ الشَّمْسِ، وَلَا عِنْدَ غُرُوبِهَا؛ فَإِنَّهَا تَطْلُعُ وَتَغْرُبُ عَلَى قَرْنِ شَيْطَانٍ، وَصَلَّوْا بَيْنَ ذَلِكَ مَا شِئْتُمْ."],"takhrij":"حسن: رواه أبو يعلى (4216 تحقيق حسين سليم) عن محمد بن عبد الله بن نمير، حدثنا رَوح، حدثنا أسامة بن زيد، عن حفص بن عبيدالله، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب النهي عن الصلاة عند طلوع الشمس وعند غروبها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAbū Ya‘lā (4216)","chapter_en":"Prohibition of praying at sunrise and at sunset","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":3,"content":{"translation":{"en":["Anas said: The Messenger of Allah ﷺ said: “Do not pray at sunrise nor at sunset, for it rises and sets upon a horn of Satan. Pray between those times whatever you wish.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى (4216)."},{"num":2505,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ ثَابِتٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُصَلَّى إِذَا طَلَعَ قَرْنُ الشَّمْسِ، أَوْغَابَ قَرْنُهَا، وَقَالَ: إِنَّهَا تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ أَوْ مِنْ بَيْنِ قَرْنَيْ شَيْطَانٍ."],"takhrij":"صحيح: رواه الإمام أحمد (21661) عن عفَّان، حدثنا همام، حدثنا قتادة، عن ابن سيرين، عن زيد بن ثابت فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب النهي عن الصلاة عند طلوع الشمس وعند غروبها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nAḥmad (21661)","chapter_en":"Prohibition of praying at sunrise and at sunset","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":3,"content":{"translation":{"en":["Zayd ibn Thābit reported that the Prophet ﷺ forbade praying when the horn (edge) of the sun appears or when its edge disappears, and he said: “It rises between the two horns of Satan,” or “from between the two horns of Satan.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (21661)."},{"num":2506,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: رَكْعَتَانِ لَمْ يَكُنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَعُهُمَا سِرًّا وَلاَ عَلاَنِيَةً، رَكْعَتَانِ قَبْلَ صَلاَةِ الصُّبْحِ، وَرَكْعَتَانِ بَعْدَ الْعَصْرِ."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (592)، ومسلم في المسافرين (835) كلاهما من طريق أبي إسحاق الشيباني، عن عبد الرحمن بن الأسود، عن أبيه، عن عائشة فذكرت مثله.","grade":"متفق عليه","chapter_ar":"باب صلاة النبي ﷺ ركعتين بعد العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon\nal-Bukhārī (592); Muslim (835)","chapter_en":"The Prophet’s ﷺ prayer of two rak‘ahs after ‘Asr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":4,"content":{"translation":{"en":["‘Ā’ishah said: There were two rak‘ahs that the Messenger of Allah ﷺ never left—neither in private nor in public: two rak‘ahs before the morning (Fajr) prayer, and two rak‘ahs after ‘Asr."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (592)، ومسلم (835)."},{"num":2507,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَلَمَةَ قَالَ: إنه سَأَلَ عَائِشَةَ عَنِ السَّجْدَتَيْنِ اللَّتَيْنِ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّيهِمَا بَعْدَ الْعَصْرِ. فَقَالَتْ: كَانَ يُصَلِّيهِمَا قَبْلَ الْعَصْرِ، ثُمَّ إِنَّهُ شُغِل عَنْهُمَا أَوْ نَسِيَهُمَا فَصَلَّاهُمَا بَعْدَ الْعَصْرِ، ثُمَّ أَثْبَتَهُمَا. وَكَانَ إِذَا صَلَّى صَلَاةً أَثْبَتَهَا. تَعْنِي: دَاوَمَ عَلَيْهَا."],"takhrij":"صحيح: رواه مسلم في المسافرين (835) من طريق إسماعيل بن جعفر، قال: أخبرني محمد بن أبي حرملة، قال: أخبرني أبو سلمة فذكر مثله.","grade":"صحيح","chapter_ar":"باب صلاة النبي ﷺ ركعتين بعد العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nMuslim (835)","chapter_en":"The Prophet’s ﷺ prayer of two rak‘ahs after ‘Asr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":4,"content":{"translation":{"en":["Abu Salamah said: He asked ‘Ā’ishah about the two prostrations (i.e., the two rak‘ahs) that the Messenger of Allah ﷺ used to pray after ‘Asr. She said: He used to pray them before ‘Asr, then he was preoccupied from them or forgot them, so he prayed them after ‘Asr, then he kept them consistently. And whenever he performed a prayer, he would make it regular—meaning: he would continue doing it."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (835)."},{"num":2508,"demo":false,"sanad":"","matn":["عَنْ كُرَيْبٍ، أَنَّ ابْنَ عَبَّاسٍ، وَالْمِسْوَرَ بْنَ مَخْرَمَةَ، وَعَبْدَ الرَّحْمَنِ بْنَ أَزْهَرَ رَضِيَ اللَّهُ عَنْهُمْ أَرْسَلُوهُ إِلَى عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا فَقَالُوا: اقْرَأْ عَلَيْهَا السَّلاَمَ مِنَّا جَمِيعًا وَسَلْهَا عَنِ الرَّكْعَتَيْنِ بَعْدَ صَلاَةِ الْعَصْرِ وَقُلْ لَهَا: إِنَّا أُخْبِرْنَا أَنَّكِ تُصَلِّينَهُمَا، وَقَدْ بَلَغَنَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْهَا. وَقَالَ ابْنُ عَبَّاسٍ: وَكُنْتُ أَضْرِبُ النَّاسَ مَعَ عُمَرَ بْنِ الْخَطَّابِ عَنْهُمَا. فَقَالَ كُرَيْبٌ: فَدَخَلْتُ عَلَى عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا فَبَلَّغْتُهَا مَا أَرْسَلُونِي. فَقَالَتْ: سَلْ أُمَّ سَلَمَةَ. فَخَرَجْتُ إِلَيْهِمْ فَأَخْبَرْتُهُمْ بِقَوْلِهَا، فَرَدُّونِي إِلَى أُمِّ سَلَمَةَ بِمِثْلِ مَا أَرْسَلُونِي بِهِ إِلَى عَائِشَةَ. فَقَالَتْ أُمُّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْهَا، ثُمَّ رَأَيْتُهُ يُصَلِّيهِمَا حِينَ صَلَّى الْعَصْرَ، ثُمَّ دَخَلَ عَلَىَّ وَعِنْدِي نِسْوَةٌ مِنْ بَنِي حَرَامٍ مِنَ الأَنْصَارِ فَأَرْسَلْتُ إِلَيْهِ الْجَارِيَةَ فَقُلْتُ: قُومِي بِجَنْبِهِ قُولِي لَهُ: تَقُولُ لَكَ أُمُّ سَلَمَةَ يَا رَسُولَ اللَّهِ سَمِعْتُكَ تَنْهَى عَنْ هَاتَيْنِ وَأَرَاكَ تُصَلِّيهِمَا. فَإِنْ أَشَارَ بِيَدِهِ فَاسْتَأْخِرِي عَنْهُ. فَفَعَلَتِ الْجَارِيَةُ، فَأَشَارَ بِيَدِهِ، فَاسْتَأْخَرَتْ عَنْهُ، فَلَمَّا انْصَرَفَ قَالَ: يَا بِنْتَ أَبِي أُمَيَّةَ، سَأَلْتِ عَنِ الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ، وَإِنَّهُ أَتَانِي نَاسٌ مِنْ عَبْدِ الْقَيْسِ فَشَغَلُونِي عَنِ الرَّكْعَتَيْنِ اللَّتَيْنِ بَعْدَ الظُّهْرِ، فَهُمَا هَاتَانِ."],"takhrij":"متفق عليه: رواه البخاري في كتاب السهو (1233)، ومسلم في المسافرين (834) كلاهما من طريق عبد الله بن وهب، قال: أخبرني عمرو بن الحارث، عن بكير، عن كريب فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب صلاة النبي ﷺ ركعتين بعد العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon\nal-Bukhārī (1233); Muslim (834)","chapter_en":"The Prophet’s ﷺ prayer of two rak‘ahs after ‘Asr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":4,"content":{"translation":{"en":["Kurayb reported that Ibn ‘Abbās, al-Miswar ibn Makhramah, and ‘Abd al-Raḥmān ibn Azhar (may Allah be pleased with them) sent him to ‘Ā’ishah (may Allah be pleased with her) and said: “Convey our greetings to her all together, and ask her about the two rak‘ahs after the ‘Asr prayer, and tell her: we have been informed that you pray them, and it has reached us that the Prophet ﷺ forbade them.” Ibn ‘Abbās said: “I used to strike the people along with ‘Umar ibn al-Khaṭṭāb to stop them from doing them.” Kurayb said: I went in to ‘Ā’ishah and delivered to her what they sent me with. She said: “Ask Umm Salamah.” So I went out to them and informed them of her statement, and they sent me back to Umm Salamah with the same message they had sent me with to ‘Ā’ishah. Umm Salamah (may Allah be pleased with her) said: I heard the Prophet ﷺ forbid them, then I saw him praying them after he prayed ‘Asr. Then he entered upon me while I had some women from Banī Ḥarām of the Anṣār with me. So I sent a servant girl to him and said: “Stand by his side and say to him: Umm Salamah says to you, O Messenger of Allah: I heard you forbidding these two (rak‘ahs), yet I see you praying them. If he gestures with his hand, then step back.” The girl did so, and he gestured with his hand, so she stepped back. When he finished, he said: “O daughter of Abī Umayyah, you asked about the two rak‘ahs after ‘Asr. Some people from ‘Abd al-Qays came to me and preoccupied me from the two rak‘ahs after Ẓuhr, so these are those two.”"]},"buhuth":{"en":["al-Nasā’ī (580) — Umm Salamah mentions he prayed two rak‘ahs after ‘Asr in her house once; and he explained: “They are two rak‘ahs I used to pray after Ẓuhr, but I was distracted from them until I prayed ‘Asr.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1233)، ومسلم (834)."},{"num":2509,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الْعَزِيزِ بن رفيع قَالَ: رَأَيْتُ عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ يُصَلِّي رَكْعَتَيْنِ بَعْدَ الْعَصْرِ، ويُخبِر أَنَّ عَائِشَةَ رَضِيَ اللَّهِ عَنْهُ ا حدَّثتْه أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَدْخُلْ بَيْتَهَا إِلاَّ صَلاَّهُمَا ."],"takhrij":"صحيح: رواه البخاري في الحج (1631) عن الحسن بن محمد هو الزعفراني، حدثنا عبيدة بن حُميد، حدثني عبد العزيز بن رُفيع فذكره.","grade":"صحيح","chapter_ar":"باب صلاة النبي ﷺ ركعتين بعد العصر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nal-Bukhārī (1631)","chapter_en":"The Prophet’s ﷺ prayer of two rak‘ahs after ‘Asr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":4,"content":{"translation":{"en":["‘Abd al-‘Azīz ibn Rufay‘ said: I saw ‘Abdullāh ibn al-Zubayr praying two rak‘ahs after ‘Asr, and he reported that ‘Ā’ishah (may Allah be pleased with her) told him that the Prophet ﷺ never entered her house except that he prayed them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1631)."},{"num":2510,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الصَّلاَةِ بَعْدَ الْعَصْرِ إِلاَّ أَنْ تَكُونَ الشَّمْسُ بَيْضَاءَ نَقِيَّةً مُرْتَفِعَةً."],"takhrij":"حسن: رواه أبو داود (1274)، والنسائي (573) كلاهما من طريق منصور بن المعتمر، عن هلال بن يساف، عن وهب بن الأجدع، عن علي فذكره.","grade":"حسن","chapter_ar":"باب الرّخصة في الصّلاة بعد العصر إذا كانت الشّمس مرتفعة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAbū Dāwūd (1274); al-Nasā’ī (573); Ibn Khuzaymah (1284–1285) — wording: “No prayer after ‘Asr unless the sun is high.”","chapter_en":"Concession to pray after ‘Asr when the sun is still high","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":5,"content":{"translation":{"en":["‘Alī ibn Abī Ṭālib said: The Messenger of Allah ﷺ forbade prayer after ‘Asr unless the sun is bright, clear, and high."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1274)، والنسائي (573). وأخرجه ابن خزيمة (1285 ،1284) ولفظه: (( لا يصلى بعد العصر إلا أن تكون الشمس مرتفعة ))."},{"num":2511,"demo":false,"sanad":"","matn":["عَنْ جُبَيْرِ بْنِ مُطْعِمٍ، يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ تَمْنَعُوا أَحَدًا يَطُوفُ بِهَذَا الْبَيْتِ، وَيُصَلِّي أَىَّ سَاعَةٍ شَاءَ مِنْ لَيْلٍ أَوْ نَهَارٍ.","وفي رواية: يَا بَنِي عَبْدِ مَنَافٍ، لاَ تَمْنَعُوا أَحَدًا .."],"takhrij":"حسن: رواه أبو داود (1894)، والترمذي (868)، والنسائي (585)، وابن ماجه (1254) كلهم من طريق سفيان بن عيينة، عن أبي الزبير، عن عبد الله بن باباه، عن جبير بن مطعم فذكره واللفظ لأبي داود.","grade":"حسن","chapter_ar":"باب ما جاء في الرخصة في الصلاة بمكة في كل وقت","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAbū Dāwūd (1894); al-Tirmidhī (868); al-Nasā’ī (585); Ibn Mājah (1254)","chapter_en":"Concession for praying in Makkah at any time","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":6,"content":{"translation":{"en":["Jubayr ibn Muṭ‘im narrated (attributed to the Prophet ﷺ): “Do not prevent anyone from circumambulating this House and praying at whatever hour he wishes of the night or the day.” In another wording: “O Banī ‘Abd Manāf, do not prevent anyone.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1894)، والترمذي (868)، والنسائي (585)، وابن ماجه (1254)."},{"num":2512,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ نَسِيَ صَلاَةً فَلْيُصَلِّ إِذَا ذَكَرَهَا، لاَ كَفَّارَةَ لَهَا إِلاَّ ذَلِكَ. {وَأَقِمِ الصَّلاَةَ لِذِكْرِي} قَالَ مُوسَى."],"takhrij":"متفق عليه: رواه البخاري في المواقيت (597) عن أبي نعيم وموسى بن إسماعيل، قالا: حدثنا همام، عن قتادة، عن أنس فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب من نسي صلاة فليصلها إذا ذكرها ولوكان الوقت مكروهاً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon\nal-Bukhārī (597); Muslim (684)","chapter_en":"Whoever forgets a prayer should pray it when he remembers, even if the time is normally disliked","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":7,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet ﷺ said: “Whoever forgets a prayer, let him pray it when he remembers it—there is no expiation for it except that.” And (Allah says): “Establish the prayer for My remembrance.” (Sūrah Ṭā Hā: 14)"]},"buhuth":{"en":["“There is no expiation for it except that.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (597)، ومسلم (684). وفي لفظ: (( لا كفارة لها إلا ذلك))."},{"num":2513,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ قَفَلَ مِنْ غَزْوَةِ خَيْبَرَ سَارَ لَيْلَهُ حَتَّى إِذَا أَدْرَكَهُ الْكَرَى عَرَّسَ، وَقَالَ لِبِلَالٍ: اكْلَأْ لَنَا اللَّيْلَ. فَصَلَّى بِلَالٌ مَا قُدِّرَ لَهُ، وَنَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ. فَلَمَّا تَقَارَبَ الْفَجْرُ اسْتَنَدَ بِلَالٌ إِلَى رَاحِلَتِهِ مُوَاجِهَ الْفَجْرِ، فَغَلَبَتْ بِلَالًا عَيْنَاهُ وَهُوَ مُسْتَنِدٌ إِلَى رَاحِلَتِهِ، فَلَمْ يَسْتَيْقِظْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَا بِلَالٌ وَلَا أَحَدٌ مِنْ أَصْحَابِهِ حَتَّى ضَرَبَتْهُمُ الشَّمْسُ. فَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوَّلَهُمُ اسْتِيقَاظًا، فَفَزِعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَيْ بِلَالُ! فَقَالَ بِلَالٌ: أَخَذَ بِنَفْسِي الَّذِي أَخَذَ بِأَبِي أَنْتَ وَأُمِّي يَا رَسُولَ اللَّهِ بِنَفْسِكَ، قَالَ: اقْتَادُوا. فَاقْتَادُوا رَوَاحِلَهُمْ شَيْئًا، ثُمَّ تَوَضَّأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَمَرَ بِلَالًا فَأَقَامَ الصَّلَاةَ، فَصَلَّى بِهِمُ الصُّبْحَ، فَلَمَّا قَضَى الصَّلَاةَ، قَالَ: مَنْ نَسِيَ الصَّلَاةَ فَلْيُصَلِّهَا إِذَا ذَكَرَهَا فَإِنَّ اللَّهَ قَالَ: ﴿أَقِمِ الصَّلاةَ لِذِكْرِي﴾. قَالَ يُونُسُ."],"takhrij":"صحيح: رواه مسلم في المساجد (680) عن حرملة بن يحيى، أخبرنا ابن وهب، أخبرني يونس، عن ابن شهاب، عن سعيد بن المسيب، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب من نسي صلاة فليصلها إذا ذكرها ولوكان الوقت مكروهاً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nMuslim (680)","chapter_en":"Whoever forgets a prayer should pray it when he remembers, even if the time is normally disliked","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah narrated that when the Messenger of Allah ﷺ returned from the expedition of Khaybar, he traveled during the night until drowsiness overcame him. He stopped to rest and said to Bilal: “Keep watch for us through the night.” Bilal prayed as much as he was able, while the Messenger of Allah ﷺ and his companions slept. As dawn approached, Bilal leaned against his mount facing the direction of dawn, but sleep overcame Bilal’s eyes while he was leaning against his mount. Neither the Messenger of Allah ﷺ, nor Bilal, nor any of his companions awoke until the sun struck them. The Messenger of Allah ﷺ was the first of them to awaken. Startled, he said: “O Bilal!” Bilal said: “The One who took your soul took mine (as well)—may my father and mother be sacrificed for you, O Messenger of Allah.” He said: “Move on.” So they led their mounts on for some distance. Then the Messenger of Allah ﷺ performed wudu’, and he ordered Bilal to establish the prayer. He then prayed the morning prayer with them. When he finished, he said: “Whoever forgets a prayer, let him pray it when he remembers it. Indeed Allah says: ‘And establish the prayer for My remembrance.’” (Surah Ta-Ha 14)."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (680)."},{"num":2514,"demo":false,"sanad":"","matn":["عَنْ أَبِى قَتَادَةَ قَالَ: خَطَبَنَا رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّكُمْ تَسِيرُونَ عَشِيَّتَكُمْ وَلَيْلَتَكُمْ وَتَأْتُونَ الماءَ إِنْ شَاءَ الله غَدًا . فَانْطَلَقَ النَّاسُ لاَ يَلْوِى أَحَدٌ عَلَى أَحَدٍ، قَالَ أَبُو قَتَادَةَ: فَبَيْنَمَا رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسِيرُ حَتَّى ابْهَارَّ اللَّيْلُ وَأَنَا إِلَى جَنْبِهِ، قَالَ: فَنَعَسَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَمَالَ عَنْ رَاحِلَتِهِ، فَأَتَيْتُهُ فَدَعَمْتُهُ مِنْ غَيْرِ أَنْ أُوقِظَهُ حَتَّى اعْتَدَلَ عَلَى رَاحِلَتِهِ، قَالَ: ثُمَّ سَارَ حَتَّى تَهَوَّرَ اللَّيْلُ مَالَ عَنْ رَاحِلَتِهِ، قَالَ: فَدَعَمْتُهُ مِنْ غَيْرِ أَنْ أُوقِظَهُ حَتَّى اعْتَدَلَ عَلَى رَاحِلَتِهِ، قَالَ: ثُمَّ سَارَ حَتَّى إِذَا كَانَ مِنْ آخِرِ السَّحَرِ مَالَ مَيْلَةً هِىَ أَشَدُّ مِنَ الميْلَتَيْنِ الأُولَيَيْنِ حَتَّى كَادَ يَنْجَفِلُ فَأَتَيْتُهُ فَدَعَمْتُهُ فَرَفَعَ رَأْسَهُ فَقَالَ مَنْ هَذَا؟ قُلْتُ أَبُو قَتَادَةَ. قَالَ مَتَى كَانَ هَذَا مَسِيرَكَ مِنِّي؟ . قلْتُ: مَا زَالَ هَذَا مَسِيرِى مُنْذُ اللَّيْلَةِ، قَالَ: حَفِظَكَ الله بِمَا حَفِظْتَ بِهِ نَبِيَّهُ . ثُمَّ قَالَ: هَلْ تَرَانَا نَخْفَى عَلَى النَّاسِ . ثُمَّ قَالَ: هَلْ تَرَى مِنْ أَحَدٍ؟ . قُلْتُ: هَذَا رَاكِبٌ. ثُمَّ قُلْتُ: هَذَا رَاكِبٌ آخَرُ، حَتَّى اجْتَمَعْنَا فَكُنَّا سَبْعَةَ رَكْبٍ. قَالَ: فَمَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الطَّرِيقِ فَوَضَعَ رَأْسَهُ ثُمَّ قَالَ: احْفَظُوا عَلَيْنَا صَلاَتَنَا . فَكَانَ أَوَّلَ مَنِ اسْتَيْقَظَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالشَّمْسُ فِى ظَهْرِهِ، قَالَ: فَقُمْنَا فَزِعِينَ ثُمَّ قَالَ: ارْكَبُوا . فَرَكِبْنَا فَسِرْنَا حَتَّى إِذَا ارْتَفَعَتِ الشَّمْسُ نَزَلَ ثُمَّ دَعَا بِمِيضَأَةٍ كَانَتْ مَعِى فِيهَا شَيءٌ مِنْ مَاءٍ قَالَ: فَتَوَضَّأَ مِنْهَا وُضُوءًا دُونَ وُضُوءٍ قَالَ: وَبَقِىَ فِيهَا شَىْءٌ مِنْ مَاءٍ، ثُمَّ قَالَ لأَبِى قَتَادَةَ: احْفَظْ عَلَيْنَا مِيضَأَتَكَ فَسَيَكُونُ لَهَا نَبَأٌ . ثُمَّ أَذَّنَ بِلاَلٌ بِالصَّلاَةِ فَصَلَّى رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَكْعَتَيْنِ ثُمَّ صَلَّى الْغَدَاةَ فَصَنَعَ كَمَا كَانَ يَصْنَعُ كُلَّ يَوْمٍ قَالَ: وَرَكِبَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَرَكِبْنَا مَعَهُ قَالَ: فَجَعَلَ بَعْضُنَا يَهْمِسُ إِلَى بَعْضٍ مَا كَفَّارَةُ مَا صَنَعْنَا بِتَفْرِيطِنَا فِى صَلاَتِنَا ثُمَّ قَالَ أَمَا لَكُمْ فِىَّ أُسْوَةٌ . ثُمَّ قَالَ: أَمَا إِنَّهُ لَيْسَ فِى النَّوْمِ تَفْرِيطٌ إِنَّمَا التَّفْرِيطُ عَلَى مَنْ لَمْ يُصَلِّ الصَّلاَةَ حَتَّى يَجِىءَ وَقْتُ الصَّلاَةِ الأُخْرَى فَمَنْ فَعَلَ ذَلِكَ فَلْيُصَلِّهَا حِينَ يَنْتَبِهُ لَهَا فَإِذَا كَانَ الْغَدُ فَلْيُصَلِّهَا عِنْدَ وَقْتِهَا . ثُمَّ قَالَ مَا تَرَوْنَ النَّاسَ صَنَعُوا . قَالَ: ثُمَّ قَالَ: أَصْبَحَ النَّاسُ فَقَدُوا نَبِيَّهُمْ، فَقَالَ أَبُو بَكْرٍ وَعُمَرُ: رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدَكُمْ لَمْ يَكُنْ لِيُخَلِّفَكُمْ. وَقَالَ النَّاسُ: إِنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ أَيْدِيكُمْ فَإِنْ يُطِيعُوا أَبَا بَكْرٍ وَعُمَرَ يَرْشُدُوا. قَالَ: فَانْتَهَيْنَا إِلَى النَّاسِ حِينَ امْتَدَّ النَّهَارُ، وَحَمِىَ كُلُّ شَىْءٍ، وَهُمْ يَقُولُونَ: يَا رَسُولَ الله هَلَكْنَا عَطِشْنَا. فَقَالَ: لاَ هُلْكَ عَلَيْكُمْ . ثُمَّ قَالَ: أَطْلِقُوا لِى غُمَرِي . قَالَ: وَدَعَا بِالْمِيضَأَةِ فَجَعَلَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُبُّ وَأَبُو قَتَادَةَ يَسْقِيهِمْ فَلَمْ يَعْدُ أَنْ رَأَى النَّاسُ مَاءً فِى الْمِيضَأَةِ تَكَابُّوا عَلَيْهَا. فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَحْسِنُوا الْمَلأَ كُلُّكُمْ سَيَرْوَى . قَالَ: فَفَعَلُوا فَجَعَلَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصُبُّ وَأَسْقِيهِمْ حَتَّى مَا بَقِىَ غَيْرِى وَغَيْرُ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: ثُمَّ صَبَّ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لِى: اشْرَبْ . فَقُلْتُ: لاَ أَشْرَبُ حَتَّى تَشْرَبَ يَا رَسُولَ الله قَالَ: إِنَّ سَاقِىَ الْقَوْمِ آخِرُهُمْ شُرْبًا . قَالَ: فَشَرِبْتُ وَشَرِبَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، قَالَ: فَأَتَى النَّاسُ الماءَ جَامِّينَ رِوَاءً.","قَالَ: فَقَالَ عَبْدُ الله بْنُ رَبَاحٍ: إِنِّى لأُحَدِّثُ هَذَا الحدِيثَ فِى مَسْجِدِ الجامِعِ إِذْ قَالَ عِمْرَانُ بْنُ حُصَيْنٍ انْظُرْ أَيُّهَا الْفَتَى كَيْفَ تُحَدِّثُ؟ فَإِنِّى أَحَدُ الرَّكْبِ تِلْكَ اللَّيْلَةَ. قَالَ: قُلْتُ: فَأَنْتَ أَعْلَمُ بِالحدِيثِ. فَقَالَ: مِمَّنْ أَنْتَ؟ قُلْتُ مِنَ الأَنْصَارِ. قَالَ: حَدِّثْ فَأَنْتُمْ أَعْلَمُ بِحَدِيثِكُمْ. قَالَ: فَحَدَّثْتُ الْقَوْمَ، فَقَالَ عِمْرَانُ: لَقَدْ شَهِدْتُ تِلْكَ اللَّيْلَةَ، وَمَا شَعَرْتُ أَنَّ أَحَدًا حَفِظَهُ كَمَا حَفِظْتُهُ."],"takhrij":"صحيح: رواه مسلم في المساجد (681) عن شيبان بن فروخ، حدثنا سليمان يعني ابن المغيرة، حدثنا ثابت، عن عبد الله بن رباح، عن أبي قتادة قال: فذكره.","grade":"صحيح","chapter_ar":"باب من نسي صلاة فليصلها إذا ذكرها ولوكان الوقت مكروهاً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nMuslim (681)","chapter_en":"Whoever forgets a prayer should pray it when he remembers, even if the time is normally disliked","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":7,"content":{"translation":{"en":["Abu Qatadah said: The Messenger of Allah ﷺ delivered a sermon to us and said: “You will travel during your evening and your night, and you will reach the water tomorrow, Allah willing.” So the people set off, and none of them would turn aside for anyone else (i.e., they continued without stopping for one another). Abu Qatadah said: While the Messenger of Allah ﷺ was traveling, the night reached its middle and I was beside him. The Messenger of Allah ﷺ became drowsy and leaned to the side on his riding mount. I came to him and supported him without waking him until he straightened upon his mount. Then he continued traveling until much of the night passed, and he again leaned on his mount. I supported him again without waking him until he straightened upon his mount. Then he continued traveling until, near the end of the pre-dawn time, he leaned with a lean stronger than the first two, until he was about to fall. I came to him and supported him. He raised his head and said: “Who is this?” I said: Abu Qatadah. He said: “How long have you been traveling like this beside me?” I said: “This has been my traveling beside you since the beginning of the night.” He said: “May Allah protect you for what you protected His Prophet with.” Then he said: “Do you think we are hidden from the people?” Then he said: “Do you see anyone?” I said: “This is a rider.” Then I said: “This is another rider,” until we gathered and we were seven riders. He said: Then the Messenger of Allah ﷺ turned away from the road and laid down his head and said: “Guard our prayer for us.” And the first to awaken was the Messenger of Allah ﷺ, and the sun was upon his back (i.e., the sun had risen). We stood up alarmed. Then he said: “Ride.” So we rode and continued until, when the sun had risen higher, he dismounted. Then he called for a small vessel for washing (a miḍā’ah) that I had with me, in which there was some water. He performed wudu’ from it—less than a full wudu’—and some water remained in it. Then he said to Abu Qatadah: “Keep your vessel safe for us, for it will have some news.” Then Bilal gave the adhan for the prayer. The Messenger of Allah ﷺ prayed two rak‘ahs, then he prayed the morning prayer (Fajr), doing as he used to do every day. He said: Then the Messenger of Allah ﷺ rode, and we rode with him. Some of us began whispering to one another: “What is the expiation for what we have done by our negligence concerning our prayer?” Then he said: “Do you not have in me an example?” Then he said: “Indeed, there is no negligence in sleep. Negligence is only for the one who does not pray the prayer until the time of the next prayer comes. Whoever does that, let him pray it when he wakes up to it (i.e., when he awakens/realizes it). Then when tomorrow comes, let him pray it at its proper time.” Then he said: “What do you think the people have done?” Then he said: “The people woke up and they missed their Prophet.” So Abu Bakr and ‘Umar said: “The Messenger of Allah ﷺ is behind you; he would not abandon you.” And the people said: “The Messenger of Allah ﷺ is ahead of you. If they obey Abu Bakr and ‘Umar, they will be guided.” He said: So we reached the people when the day had extended and everything had become hot, and they were saying: “O Messenger of Allah, we are ruined! We are thirsty!” He said: “There is no ruin upon you.” Then he said: “Bring me my cup (ghumrī).” He called for the washing vessel, and the Messenger of Allah ﷺ began pouring (water) while Abu Qatadah was giving them to drink. As soon as the people saw water in the vessel, they crowded over it. So the Messenger of Allah ﷺ said: “Behave well and keep good order; all of you will be given to drink.” He said: So they did so. The Messenger of Allah ﷺ continued pouring and I continued giving them to drink, until none remained except me and the Messenger of Allah ﷺ. Then the Messenger of Allah ﷺ poured and said to me: “Drink.” I said: “I will not drink until you drink, O Messenger of Allah.” He said: “The one who serves the people is the last of them to drink.” So I drank, and the Messenger of Allah ﷺ drank. Then the people came to the water satisfied and fully quenched.","He said: Then ‘Abdullah ibn Rabah said: “I narrated this hadith in the central mosque when ‘Imran ibn Husayn said: ‘Look, young man, how you narrate—because I was one of the riders that night.’” I said: “Then you know the hadith better.” He said: “From whom are you?” I said: “From the Ansar.” He said: “Narrate, for you know your hadith best.” So I narrated it to the people, and ‘Imran said: “I witnessed that night, and I did not realize that anyone had preserved it as you have preserved it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (681)."},{"num":2515,"demo":false,"sanad":"","matn":["عن أَبِي بَكْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ نَسِيَ صَلَاةً أَوْ نَامَ عَنْهَا فَلْيُصَلِّهَا إِذَا ذَكَرَهَا."],"takhrij":"حسن: رواه البزّار كشف الأستار (394) عن أحمد بن المقدام، ثنا إسماعيل ابن عُلية، عن عُيينة، عن أبيه، عن أبي بكرة فذكر الحديث.","grade":"حسن","chapter_ar":"باب من نسي صلاة فليصلها إذا ذكرها ولوكان الوقت مكروهاً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Bazzar, Kashf al-Astar (394)","chapter_en":"Whoever forgets a prayer should pray it when he remembers, even if the time is normally disliked","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":7,"content":{"translation":{"en":["Abu Bakrah narrated that the Messenger of Allah ﷺ said: “Whoever forgets a prayer or sleeps through it, let him pray it when he remembers it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (394)."},{"num":2516,"demo":false,"sanad":"","matn":["عن أَبِي جُحَيْفة قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرِهِ الَّذِي نَامُوا فِيهِ حَتَّى طَلَعَتِ الشَّمْسُ، فَقَالَ: إِنَّكُمْ كُنْتُمْ أَمْوَاتًا، فَرَدَّ اللَّهُ إِلَيْكُمْ أَرْوَاحَكُمْ، فَمَنْ نَامَ عَنْ صَلَاةٍ فَلْيُصَلِّهَا إِذَا اسْتَيْقَظَ، وَمَنْ نَسِيَ صَلَاةً فَلْيُصَلِّ إِذَا ذَكَرَ."],"takhrij":"حسن: رواه أبو يعلى المقصد العليّ (203) عن أبي خيثمة، ثنا الفضل بن دُكين، ثنا عبد الجبار بن العباس الهمداني، عن عون بن أبي جُحَيْفة، عن أبيه فذكر مثله.","grade":"حسن","chapter_ar":"باب من نسي صلاة فليصلها إذا ذكرها ولوكان الوقت مكروهاً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Ya‘la, al-Maqsad al-‘Ali (203)","chapter_en":"Whoever forgets a prayer should pray it when he remembers, even if the time is normally disliked","part_en":"Prayer (Ṣalāh)","group_ar":"جموع الأوقات المنهي عنها عن الصلاة فيها","group_en":"A Collection of the Times in Which Prayer Is Prohibited","part_no":9,"group_no":11,"chapter_no":7,"content":{"translation":{"en":["Abu Juhayfah said: The Messenger of Allah ﷺ was on a journey during which they slept until the sun rose. He said: “You were as if dead, then Allah returned your souls to you. Whoever sleeps through a prayer should pray it when he wakes, and whoever forgets a prayer should pray it when he remembers.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى في المقصد العلي (203)."},{"num":2517,"demo":false,"sanad":"","matn":["عَنْ سَبْرة بن مَعْبَدٍ الجهني قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِذَا صلَّى أَحَدُكُمْ فَلْيَسْتَتِرْ لِصَلَاتِهِ، وَلَوْ بِسَهْمٍ ."],"takhrij":"حسن: رواه أحمد (15340، 15342)، وأبو يعلى (941)، وابن خزيمة (810)، والطبراني في الكبير (6542) والحاكم (1/252)، كلهم من طرق عن عبد الملك بن الربيع بن سبرة، عن أبيه، عن جده قال: فذكره.","grade":"حسن","chapter_ar":"باب اتخاذ السترة للصلاة، وأنها سنّة مؤكّدة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (15340)","chapter_en":"Using a sutrah (a barrier) in prayer, and that it is a strongly emphasized Sunnah","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":1,"content":{"translation":{"en":["Sabrah ibn Ma‘bad al-Juhani reported that the Messenger of Allah ﷺ said: “When one of you prays, let him take a sutrah for his prayer—even if it is just an arrow.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (15340)."},{"num":2518,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ كَانَ يُعَرِّضُ رَاحِلَتَهُ فَيُصَلِّي إِلَيْهَا. قُلْتُ أَفَرَأَيْتَ إِذَا هَبَّتِ الرِّكَابُ. قَالَ: كَانَ يَأْخُذُ هَذَا الرَّحْلَ فَيُعَدِّلُهُ فَيُصَلِّي إِلَى آخِرَتِهِ ـ أَوْ قَالَ: مُؤَخَّرِهِ ـ وَكَانَ ابْنُ عُمَرَ رَضِيَ اللَّهُ عَنْهُ يَفْعَلُهُ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (507)، ومسلم في الصلاة (502) كلاهما من طريق معتمر بن سليمان، عن عبيدالله، عن نافع، عن ابن عمر فذكر مثله واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب في تحري الصّلاة إلى سترة كالأسطوانة ونحوها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (507) and Muslim (502), with al-Bukhari’s wording; Muslim has a shorter wording: “He would place his mount sideways and pray toward it,” and also: “He used to pray toward his mount.” Another wording states: “The Prophet ﷺ prayed facing a camel.”","chapter_en":"Seeking to pray toward a sutrah such as a pillar and the like","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["Ibn ‘Umar reported that the Prophet ﷺ used to place his riding mount sideways and pray facing it (using it as a sutrah). Nafi‘ said: “What if the riding animals became restless?” He replied: “He would take the saddle and set it upright and pray toward its back end (or its rear).”"]},"buhuth":{"en":["“يُعَرِّضُ” means he would set it sideways, as a barrier between him and the direction of prayer.","“هبَّت الركاب” means the camels became agitated/restless; if that happened and disturbed the prayer, he would shift to using the saddle as the sutrah.","“مؤخرة الرحل” refers to the wooden rear part of the saddle that the rider leans against."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (507)، ومسلم (502) واللفظ للبخاري. ولفظ مسلم مختصر: «كان يعرض راحلته وهو يصلي إليها». وفي لفظ: «كان يصلي إلى راحلته». وفي لفظ: (( إن النبي ﷺ صلى إلى بعير))."},{"num":2519,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا خَرَجَ يَوْمَ الْعِيدِ أَمَرَ بِالْحَرْبَةِ فَتُوضَعُ بَيْنَ يَدَيْهِ، فَيُصَلِّي إِلَيْهَا، وَالنَّاسُ وَرَاءَهُ، وَكَانَ يَفْعَلُ ذَلِكَ فِي السَّفَرِ، فَمِنْ ثَمَّ اتَّخَذَهَا الأُمَرَاءُ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (464)، ومسلم في الصلاة (501) كلاهما من حديث عبدالله بن نمير، حدثنا عبيدالله، عن نافع، عن ابن عمر، فذكره.","grade":"متفق عليه","chapter_ar":"باب في تحري الصّلاة إلى سترة كالأسطوانة ونحوها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (494), Muslim (501)","chapter_en":"Seeking to pray toward a sutrah such as a pillar and the like","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["Ibn ‘Umar reported that when the Messenger of Allah ﷺ went out on the day of ‘Eid, he would order that a spear be placed in front of him, and he would pray facing it, with the people behind him. He also used to do that while traveling, and from this the rulers later adopted the practice."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (464)، ومسلم ( 501)."},{"num":2520,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ، قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا خَرَجَ لِحَاجَتِهِ تَبِعْتُهُ أَنَا وَغُلاَمٌ، وَمَعَنَا عُكَّازَةٌ أَوْ عَصًا، أَوْ عَنَزَةٌ، وَمَعَنَا إِدَاوَةٌ، فَإِذَا فَرَغَ مِنْ حَاجَتِهِ نَاوَلْنَاهُ الإِدَاوَةَ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (500)، ومسلم في الطهارة (271) كلاهما من حديث شعبة، عن عطاء بن أبي ميمونة، أنه سمع أنس بن مالك يقول (فذكره). واللفظ للبخاري، ولفظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب في تحري الصّلاة إلى سترة كالأسطوانة ونحوها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (500) with this wording; Muslim (271) with similar wording.","chapter_en":"Seeking to pray toward a sutrah such as a pillar and the like","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Malik said: When the Prophet ﷺ went out for his need, I and a boy would follow him, and with us was a walking stick or a staff, or a small spear (‘anazah), and with us was a water container. When he finished, we would hand him the water container."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (500)، ومسلم (271). واللفظ للبخاري، ولفظ مسلم نحوه."},{"num":2521,"demo":false,"sanad":"","matn":["عَنْ طَلْحَةَ بن عبيدالله قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِذَا وَضَعَ أَحَدُكُمْ بَيْنَ يَدَيْهِ مِثل مؤخِرةِ الرحْلِ فليُصلِّ. وَلَا يُبَالِي مَنْ مرَّ وَرَاءَ ذَلِكَ ."],"takhrij":"صحيح: رواه مسلم في الصلاة (499) من طريق أبي الأحوص، عن سماك عن موسى بن طلحة، عن أبيه فذكر مثله.","grade":"صحيح","chapter_ar":"باب في تحري الصّلاة إلى سترة كالأسطوانة ونحوها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nMuslim (499)","chapter_en":"Seeking to pray toward a sutrah such as a pillar and the like","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["Talhah ibn ‘Ubaydillah reported that the Messenger of Allah ﷺ said: “If one of you places in front of him something like the rear part of a saddle, then let him pray, and he need not worry about whoever passes behind that.”"]},"buhuth":{"en":["“The rear of the saddle” is the wooden piece the rider leans against."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (499)."},{"num":2522,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ فِي غَزْوَةِ تَبُوكَ عَنْ سُتْرَةِ الْمُصَلِّي فَقَالَ: كَمُؤْخِرَةِ الرَّحْلِ."],"takhrij":"صحيح: رواه مسلم في الصلاة (500) من طريق أبي الأسود محمد بن عبدالرحمن، عن عروة، عن عائشة فذكرت مثله.","grade":"صحيح","chapter_ar":"باب في تحري الصّلاة إلى سترة كالأسطوانة ونحوها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nMuslim (500)","chapter_en":"Seeking to pray toward a sutrah such as a pillar and the like","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["‘A’ishah (Mother of the Believers) reported that the Messenger of Allah ﷺ was asked during the expedition of Tabuk about the sutrah of the one praying, and he said: “Like the rear part of a saddle.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم ( 500)."},{"num":2523,"demo":false,"sanad":"","matn":["عن يَزِيدَ بْنِ أَبِي عُبَيْدٍ، قَالَ: كُنْتُ آتِي مَعَ سَلَمَةَ بْنِ الأَكْوَعِ فَيُصَلِّي عِنْدَ الأُسْطُوَانَةِ الَّتِي عِنْدَ الْمُصْحَفِ. فَقُلْتُ: يَا أَبَا مُسْلِمٍ، أَرَاكَ تَتَحَرَّى الصَّلاَةَ عِنْدَ هَذِهِ الأُسْطُوَانَةِ. قَالَ: فَإِنِّي رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَحَرَّى الصَّلاَةَ عِنْدَهَا."],"takhrij":"متفق عليه: رواه البخاريّ في الصلاة (502)، ومسلم في الصلاة (509: 264) كلاهما من حديث مكي بن إبراهيم، قال: حدثنا يزيد بن أبي عبيد، فذكره.","grade":"متفق عليه","chapter_ar":"باب في تحري الصّلاة إلى سترة كالأسطوانة ونحوها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (502), Muslim (509)","chapter_en":"Seeking to pray toward a sutrah such as a pillar and the like","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["Yazid ibn Abi ‘Ubayd said: I used to come with Salamah ibn al-Akwa‘, and he would pray by the pillar near the mushaf. I said: “O Abu Muslim, I see you deliberately choosing to pray by that pillar.” He said: “I saw the Prophet ﷺ deliberately choosing to pray by it.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (502)، ومسلم (509: 264)."},{"num":2524,"demo":false,"sanad":"","matn":["عَنْ يَزِيدَ ابْنَ أَبِى عُبَيْدٍ، عَنْ سَلَمَةَ بن الأَكْوَعِ أَنَّهُ كَانَ يَتَحَرَّى مَوْضِعَ مَكَانِ الْمُصْحَفِ يُسَبِّحُ فِيهِ، وَذَكَرَ أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَتَحَرَّى ذَلِكَ الْمَكَانَ، وَكَانَ بَيْنَ الْمِنْبَرِ وَالْقِبْلَةِ قَدْرُ مَمَرِّ الشَّاةِ."],"takhrij":"صحيح: رواه مسلم في الصلاة (509: 263) من طرق عن حماد بن مسعدة، عن يزيد بن أبي عبيد فذكره.","grade":"صحيح","chapter_ar":"باب في تحري الصّلاة إلى سترة كالأسطوانة ونحوها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nMuslim, Book of Prayer (509), hadith (263)","chapter_en":"Seeking to pray toward a sutrah such as a pillar and the like","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["Yazid ibn Abi ‘Ubayd narrated from Salamah ibn al-Akwa‘ that he used to deliberately seek out a particular place by a pillar to do tasbih (devotional prayer/remembering Allah) there, and he mentioned that the Messenger of Allah ﷺ used to deliberately seek that same place. And between the minbar and the qiblah there was enough space for a sheep to pass."]},"buhuth":{"en":["“الأسطوانة” means a pillar (a column). Praying toward a pillar is done for the purpose of having a sutrah (a barrier), not because that exact spot has some special inherent virtue.","“عند المصحف” means: near the place where the box/chest used to be placed that contained the Mushaf (written Qur’an). About the pillar mentioned, al-Hafiz Ibn Hajar said: “Some of our teachers verified for us that it is the middle pillar in the blessed Rawdah, and that it is known as the Pillar of the Muhajirun.” Al-Fath (1/577). Meaning: the Muhajirun used to gather near it for discussion, and because of that, ‘Umar said: “Those praying have more right to the pillars than those merely talking,” and al-Bukhari mentioned this in a hanging (mu‘allaq) form. Today it is located behind the mihrab and written on it is: “الأسطوانة المخلّقة (the perfumed pillar).” “خلوق” is a type of perfume they used to apply to it.","The phrase “يُسبّح” (he does tasbih) includes nafl (voluntary) prayer, and the author says he did not find any authentic hadith establishing special “extra virtues” for praying specifically at a pillar."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (509: 263)."},{"num":2525,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، قَالَ: لَقَدْ رَأَيْتُنَا لَيْلَةَ بَدْرٍ، وَمَا مِنَّا إِنْسَانٌ إِلا نَائِمٌ، إِلا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَإِنَّهُ كَانَ يُصَلِّي إِلَى شَجَرَةٍ، وَيَدْعُو حَتَّى أَصْبَحَ، وَمَا كَانَ مِنَّا فَارِسٌ يَوْمَ بَدْرٍ غَيْرَ الْمِقْدَادِ بْنِ الْأَسْوَدِ."],"takhrij":"صحيح: رواه الإمام أحمد (1161) عن محمد بن جعفر، حدثنا شعبة، عن أبي إسحاق، قال: سمعت حارثة بن مُضرِّب يحدّث عن علي، فذكره.","grade":"صحيح","chapter_ar":"باب في تحري الصّلاة إلى سترة كالأسطوانة ونحوها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nAhmad (1161)","chapter_en":"Seeking to pray toward a sutrah such as a pillar and the like","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["‘Ali ibn Abi Talib said: “I saw us on the night of Badr: none of us was awake except the Messenger of Allah ﷺ. He used to pray facing a tree and supplicate until morning. And there was no horseman among us on the Day of Badr except al-Miqdad ibn al-Aswad.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (1161)."},{"num":2526,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِذَا قَامَ أَحَدُكُمْ يُصَلِّي، فَإِنَّهُ يَسْتُرُهُ إِذَا كَانَ بَيْنَ يَدَيْهِ مِثْلُ آخِرَةِ الرَّحْلِ، فَإِذَا لَمْ يَكُنْ بَيْنَ يَدَيْهِ مِثْلُ آخِرَةِ الرَّحْلِ فَإِنَّهُ يَقْطَعُ صَلَاتَهُ الْحِمَارُ وَالْمَرْأَةُ وَالْكَلْبُ الْأَسْوَدُ. قُلْتُ: يَا أَبَا ذَرٍّ، مَا بَالُ الْكَلْبِ الْأَسْوَدِ مِنَ الْكَلْبِ الْأَحْمَرِ مِنَ الْكَلْبِ الْأَصْفَرِ؟ قَالَ: يَا ابْنَ أَخِي! سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَمَا سَأَلْتَنِي فَقَالَ: الْكَلْبُ الْأَسْوَدُ شَيْطَانٌ."],"takhrij":"صحيح: رواه مسلم في الصلاة (510) من طرق عن يونس، عن حُميد ابن هلال، عن عبدالله بن الصامت، عن أبي ذر فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما يقطع الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nMuslim (510)","chapter_en":"What cuts off (interrupts) the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":3,"content":{"translation":{"en":["Abu Dharr reported that the Messenger of Allah ﷺ said: “When one of you stands to pray, he is screened if in front of him there is something like the rear of a saddle. But if there is not in front of him something like the rear of a saddle, then a donkey, a woman, and a black dog cut off his prayer.” I said: “O Abu Dharr, why a black dog rather than a red dog or a yellow dog?” He said: “My nephew, I asked the Messenger of Allah ﷺ just as you asked me, and he said: ‘The black dog is a devil.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (510)."},{"num":2527,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  يَقْطَعُ الصَّلَاةَ الْمَرْأَةُ، وَالْحِمَارُ، وَالْكَلْبُ، وَيَقِي ذَلِكَ مِثْلُ مُؤْخِرَةِ الرَّحْلِ."],"takhrij":"صحيح: رواه مسلم (511) عن إسحاق بن إبراهيم، نا المخزومي، ثنا عبد الواحد (وهو ابن زياد) ثنا عبيدالله بن عبدالله بن الأصمِّ، ثنا يزيد بن الأصم، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما يقطع الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nMuslim (511)","chapter_en":"What cuts off (interrupts) the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":3,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “A woman, a donkey, and a dog cut off the prayer, and what protects against that is something like the rear of a saddle.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (511)."},{"num":2528,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَقْطَعُ الصَّلاَةَ الْكَلْبُ الأَسْوَدُ، وَالْمَرْأَةُ الْحَائِضُ."],"takhrij":"صحيح: رواه ابن ماجه (949) عن أبي بكر بن خلاد الباهلي، قال: حدثنا يحيى بن سعيد، قال: حدثنا شعبةُ، قال: حدثنا قتادةُ، حدثنا جابر (ابن زيد)، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما يقطع الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nIbn Majah (949), Ahmad (3241), Abu Dawud (703), al-Nasa’i (752)","chapter_en":"What cuts off (interrupts) the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":3,"content":{"translation":{"en":["Ibn ‘Abbas reported from the Prophet ﷺ that he said: “The black dog and the menstruating woman cut off the prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (949)، وأحمد (3241)، وأبو داود (703)، والنسائي (752)."},{"num":2529,"demo":false,"sanad":"","matn":["عن أنس أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَقْطَعُ الصَّلَاةَ الْكَلْبُ وَالْحِمَارُ وَالْمَرْأَةُ."],"takhrij":"حسن: رواه البزار كشف الأستار (582) عن يحيى بن محمد بن السكن، ثنا يحيى بن كثير، ثنا شعبة، عن عبيدالله بن أبي بكر، عن أنس، عن النبي صلى الله عليه وسلم فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما يقطع الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan","chapter_en":"What cuts off (interrupts) the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":3,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ said: “A dog, a donkey, and a woman cut off the prayer.”"]},"buhuth":{"en":["al-Bazzar (Kashf al-Astar 582)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (582)."},{"num":2530,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ شَدَّادٍ، قَالَ: سَمِعْتُ خَالَتِي، مَيْمُونَةَ ـ زَوْجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهَا كَانَتْ تَكُونُ حَائِضًا لاَ تُصَلِّي، وَهْىَ مُفْتَرِشَةٌ بِحِذَاءِ مَسْجِدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهْوَ يُصَلِّي عَلَى خُمْرَتِهِ، إِذَا سَجَدَ أَصَابَنِي بَعْضُ ثَوْبِهِ.","وفي رواية: كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُصَلِّي وَأَنَا حِذَاءَهُ وَأَنَا حَائِضٌ، وَرُبَّمَا أَصَابَنِي ثَوْبُهُ إِذَا سَجَدَ ..","وفي رواية: كان النبي صلى الله عليه وسلم يُصلي، وأنا إلى جنبه نائمة ."],"takhrij":"متفق عليه: رواه البخاري في الطهارة (333)، وفي الصلاة (379)، ومسلم في الصلاة (513) كلاهما من طرق عن سليمان الشيباني، عن عبدالله ابن شداد به فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب من قال: المرأة لا تقطع الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (379, 333) and Muslim (513)","chapter_en":"Those who said that a woman does not cut off the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":4,"content":{"translation":{"en":["‘Abdullah ibn Shaddad said: I heard my maternal aunt Maymunah, the wife of the Prophet ﷺ, say that she would be menstruating and not praying, while she was lying down beside the place where the Messenger of Allah ﷺ prayed. When he prostrated, some of his garment would touch her. In another wording: “The Messenger of Allah ﷺ would pray while I was beside him and I was menstruating, and sometimes his garment would touch me when he prostrated.”","In another wording: “The Prophet ﷺ would pray while I was sleeping next to him.”"]},"buhuth":{"en":["This hadith has been used as evidence that a woman does not cut off the prayer. However, the wordings of the hadith do not prove that it is permissible for someone to pass/walk in front of the praying person. Rather, it only proves that it is permissible for a woman to sit or lie in front of him (in proximity) or beside him while he is praying."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (333) ،(333)، ومسلم (513)."},{"num":2531,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، ذُكِرَ عِنْدَهَا مَا يَقْطَعُ الصَّلاَةَ الْكَلْبُ وَالْحِمَارُ وَالْمَرْأَةُ. فَقَالَتْ: شَبَّهْتُمُونَا بِالْحُمُرِ وَالْكِلاَبِ، وَاللَّهِ لَقَدْ رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، وَإِنِّي عَلَى السَّرِيرِ، ـ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ ـ مُضْطَجِعَةً، فَتَبْدُو لِي الْحَاجَةُ، فَأَكْرَهُ أَنْ أَجْلِسَ فَأُوذِيَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَنْسَلُّ مِنْ عِنْدِ رِجْلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (514)، ومسلم في الصلاة (270) (الرقم الصغير) كلاهما عن عمر بن حفص بن غياث، قال: حدثنا أبي، قال: حدثنا الأعمش، قال: حدثنا إبراهيم، عن الأسود، عن عائشة فذكرت مثله.","grade":"متفق عليه","chapter_ar":"باب من قال: المرأة لا تقطع الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (514) and Muslim (270) (short numbering).","chapter_en":"Those who said that a woman does not cut off the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":4,"content":{"translation":{"en":["‘A’ishah (may Allah be pleased with her) was told about what cuts off the prayer—“a dog, a donkey, and a woman.” She said: “You have compared us to donkeys and dogs! By Allah, I saw the Prophet ﷺ praying while I was on the bed, lying between him and the qiblah. If I needed something, I disliked sitting up and disturbing the Prophet ﷺ, so I would slip away from by his feet.”"]},"buhuth":{"en":["Muslim also narrated that ‘A’ishah said: “What cuts off the prayer?” We said: “A woman and a donkey.” She said: “Indeed, a woman is an evil beast? I saw myself lying in front of the Messenger of Allah ﷺ, stretched across like a funeral bier/body placed in front, while he was praying.”","Malik also narrated that ‘A’ishah said: “I used to sleep in front of the Messenger of Allah ﷺ with my legs toward his qiblah. When he prostrated, he would nudge me, so I would draw my legs in. When he stood, I would stretch them back out.” She said: “And in those days the houses had no lamps.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (514)، ومسلم (270) (الرقم الصغير)."},{"num":2532,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى وَهِيَ مُعْتَرِضَةٌ بَيْنَ يَدَيْهِ، وَقَالَ: أَلَيْسَ هُنَّ أُمَّهَاتِكُمْ، وَأَخَوَاتِكُمْ، وَعَمَّاتِكُمْ."],"takhrij":"حسن: رواه أحمد (24359) عن يونس، حدثنا داود -يعني ابن أبي فُرات، عن إبراهيم بن ميمون الصائغ، عن عطاء، عن عروة، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب من قال: المرأة لا تقطع الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (24359)","chapter_en":"Those who said that a woman does not cut off the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":4,"content":{"translation":{"en":["‘A’ishah reported that the Prophet ﷺ prayed while she was lying across in front of him, and he said: “Are they not your mothers, your sisters, and your aunts?”"]},"buhuth":{"en":["His statement “Are they not…” means “women.” Meaning: if women are your mothers/sisters/aunts, then how could their passing “cut off” your prayer?"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد ( 24359)."},{"num":2533,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ قَالَتْ: كَانَ فراشها حِيَالَ مسجد رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ . وَفِي رِوَايَةِ: كَانَ يُفْرَشُ لِي حِيَالَ مُصَلَّى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَكَانَ يُصَلِّي وَأَنَا حِيَالُهُ."],"takhrij":"صحيح: روه أبو داود (4148)، وابن ماجه (957) كلاهما من طريق يزيد بن زُريع، عن خالد الحذاء، عن أبي قِلابة، عن زينب بنت أبي سلمة، عن أمها فذكرته.","grade":"صحيح","chapter_ar":"باب من قال: المرأة لا تقطع الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nAbu Dawud (4148), Ibn Majah (957), Ahmad (26773), Abu Ya‘la (6939)","chapter_en":"Those who said that a woman does not cut off the prayer","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":4,"content":{"translation":{"en":["Umm Salamah said: “Her bed used to be in line with (facing) the place where the Messenger of Allah ﷺ prayed.” In another narration: “A mat would be spread for me opposite the place where the Messenger of Allah ﷺ prayed, and he would pray while I was facing him.”"]},"buhuth":{"en":["(Reconciliation between the two sets of hadiths)","Al-Tirmidhī reported from Imam Aḥmad—after he recorded the hadith of Abu Dharr—that Aḥmad said: “What I have no doubt about is that the black dog cuts off the prayer. But regarding the donkey and the woman, I have something (i.e., uncertainty/hesitation) in my heart.” And Isḥāq said: “Nothing cuts it off except the black dog.” (2/163)","The author then says: I say: This is because he did not find anything that counters the report about the black dog, but he did find regarding the donkey the upcoming hadith of Ibn ‘Abbas, and regarding the woman the hadiths of ‘A’ishah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4148)، وابن ماجه (957)، وأحمد (26773)، وأبو يعلى (6939)."},{"num":2534,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، وَأَنَا رَاقِدَةٌ مُعْتَرِضَةٌ عَلَى فِرَاشِهِ، فَإِذَا أَرَادَ أَنْ يُوتِرَ أَيْقَظَنِي فَأَوْتَرْتُ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (512)، ومسلم في الصلاة (268: 512) كلاهما من حديث هشام، عن أبيه، عن عائشة فذكرت مثله.","grade":"متفق عليه","chapter_ar":"باب الصلاة خلف النائم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (512) and Muslim (268/512)","chapter_en":"Praying while someone is asleep in front (i.e., beyond the sutrah / in the same area)","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":5,"content":{"translation":{"en":["‘A’ishah said: “The Prophet ﷺ would pray while I was lying down across on his bed. When he wanted to pray witr, he would wake me and I would pray witr.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2789],"tks":"متفق عليه: رواه البخاري (512)، ومسلم (268: 512)."},{"num":2535,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: نُهِيتُ أَنْ أُصَلِّيَ خَلْفَ الْمُتَحَدِّثِينَ وَالنِّيَامِ."],"takhrij":"حسن: رواه الطبراني في الأوسط مجمع البحرين (747) عن محمد بن الفضل السقطي، ثنا سهل بن صالح الأنطاكي، ثنا شجاع بن الوليد، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكر الحديث.","grade":"حسن","chapter_ar":"بابُ كراهية الصلاة خلف النائم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan","chapter_en":"The dislike of praying behind someone who is asleep","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “I have been forbidden to pray behind people who are talking and those who are sleeping.”"]},"buhuth":{"en":["al-Tabarani in al-Awsat (as cited in Majma‘ al-Bahrayn 747)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط كما في مجمع البحرين (747)."},{"num":2536,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا خَرَجَ يَوْمَ الْعِيدِ أَمَرَ بِالْحَرْبَةِ فَتُوضَعُ بَيْنَ يَدَيْهِ، فَيُصَلِّي إِلَيْهَا وَالنَّاسُ وَرَاءَهُ، وَكَانَ يَفْعَلُ ذَلِكَ فِي السَّفَرِ، فَمِنْ ثَمَّ اتَّخَذَهَا الأُمَرَاءُ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (494)، ومسلم في الصلاة (501) كلاهما من طريق عبدالله بن نمير، حدثنا عبيدالله، عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب سترة الإمام سترة من خلفه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (494) and Muslim (501)","chapter_en":"The sutrah of the imam is the sutrah for those behind him","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":7,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar reported that when the Messenger of Allah ﷺ went out on the day of ‘Eid, he would order that a harbah (spear) be placed in front of him, and he would pray toward it while the people were behind him. He used to do that in travel as well, and from that the rulers later adopted it."]},"buhuth":{"en":["Some narrated it in a shorter wording: “A spear would be planted for him and he would pray toward it.” (al-Bukhari 498) And in Muslim: “An ‘anazah would be planted for him and he would pray toward it,” and in another wording: “The ‘anazah would be planted for him and he would pray toward it.”","The harbah and the ‘anazah refer to the same type of object. If the spear is short, it is called an ‘anazah.","The ‘anazah is like a spear, but its metal point (spearhead) is at the lower end, unlike a typical spear where the point is at the upper end."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (494)، ومسلم (501)."},{"num":2537,"demo":false,"sanad":"","matn":["عَنْ عَوْنِ بْنِ أَبِي جُحَيْفَةَ، قَالَ: سَمِعْتُ أَبِي أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى بِهِمْ بِالْبَطْحَاءِ ـ وَبَيْنَ يَدَيْهِ عَنَزَةٌ ـ الظُّهْرَ رَكْعَتَيْنِ، وَالْعَصْرَ رَكْعَتَيْنِ، تَمُرُّ بَيْنَ يَدَيْهِ الْمَرْأَةُ وَالْحِمَارُ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (495) عن أبي الوليد، قال حدثنا شعبة، عن عون بن أبي جُحيفة فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب سترة الإمام سترة من خلفه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (495) and Muslim (503)","chapter_en":"The sutrah of the imam is the sutrah for those behind him","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":7,"content":{"translation":{"en":["‘Awn ibn Abi Juhayfah said: I heard my father say that the Prophet ﷺ led them in prayer at al-Batha’—with an ‘anazah in front of him—praying Dhuhr two rak‘ahs and ‘Asr two rak‘ahs, while a woman and a donkey passed in front of him."]},"buhuth":{"en":["The phrase “in front of him (بين يديه)” means: in front of him but beyond the ‘anazah (i.e., after the sutrah), not between the Prophet ﷺ and his sutrah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (495)، ومسلم (503). وقوله: (( بين يديه ) أي: أمامه بعد العنزة."},{"num":2538,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ:  أَقْبَلْتُ رَاكِبًا عَلَى أَتَانٍ، وَأَنَا يَوْمَئِذٍ قَدْ نَاهَزْتُ الِاحْتِلَامَ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِالنَّاسِ بِمِنًى. فَمَرَرْتُ بَيْنَ يَدَيِ الصَّفِّ. فَنَزَلْتُ فَأَرْسَلْتُ الْأَتَانَ تَرْتَعُ، وَدَخَلْتُ فِي الصَّفِّ. فَلَمْ يُنْكِرْ ذَلِكَ عَلَيَّ أَحَدٌ."],"takhrij":"متفق عليه: رواه مالك في قصر الصلاة (38) عن ابن شهاب، عن عبيدالله بن عبدالله بن عتبة بن مسعود، عن عبدالله بن عباس فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب سترة الإمام سترة من خلفه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (38), al-Bukhari (76), Muslim (504)","chapter_en":"The sutrah of the imam is the sutrah for those behind him","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":7,"content":{"translation":{"en":["Ibn ‘Abbas said: “I came riding on a she-donkey, and at that time I was close to puberty. The Messenger of Allah ﷺ was praying with the people at Mina. I passed in front of part of the row. Then I got down, let the donkey graze, and I entered the row. No one objected to me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (38)، والبخاري (76)، ومسلم (504)."},{"num":2539,"demo":false,"sanad":"","matn":["عن أَبِي صالح السمَّان قَالَ: رَأَيْتُ أَبَا سَعِيدٍ الْخُدْرِيَّ فِي يَوْمِ جُمُعَةٍ، يُصَلِّي إِلَى شَىْءٍ يَسْتُرُهُ مِنَ النَّاسِ، فَأَرَادَ شَابٌّ مِنْ بَنِي أَبِي مُعَيْطٍ أَنْ يَجْتَازَ بَيْنَ يَدَيْهِ فَدَفَعَ أَبُو سَعِيدٍ فِي صَدْرِهِ، فَنَظَرَ الشَّابُّ فَلَمْ يَجِدْ مَسَاغًا إِلاَّ بَيْنَ يَدَيْهِ، فَعَادَ لِيَجْتَازَ، فَدَفَعَهُ أَبُو سَعِيدٍ أَشَدَّ مِنَ الْأُولَى، فَنَالَ مِنْ أَبِي سَعِيدٍ، ثُمَّ دَخَلَ عَلَى مَرْوَانَ، فَشَكَا إِلَيْهِ مَا لَقِيَ مِنْ أَبِي سَعِيدٍ، وَدَخَلَ أَبُو سَعِيدٍ خَلْفَهُ عَلَى مَرْوَانَ، فَقَالَ: مَا لَكَ وَلاِبْنِ أَخِيكَ يَا أَبَا سَعِيدٍ؟ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِذَا صَلَّى أَحَدُكُمْ إِلَى شَىْءٍ يَسْتُرُهُ مِنَ النَّاسِ، فَأَرَادَ أَحَدٌ أَنْ يَجْتَازَ بَيْنَ يَدَيْهِ، فَلْيَدْفَعْهُ، فَإِنْ أَبَى فَلْيُقَاتِلْهُ، فَإِنَّمَا هُوَ شَيْطَانٌ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (509)، ومسلم في الصلاة (505) كلاهما من طريق سليمان بن المغيرة، قال: حدثنا حُميد بن هلال العَدَوِي، قال: حدثنا أبو صالح السمَّان فذكره.","grade":"متفق عليه","chapter_ar":"باب منعُ المارِّ بين يدي المصلي","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (509) and Muslim (505)","chapter_en":"Preventing someone from passing in front of the one praying","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":8,"content":{"translation":{"en":["Abu Ṣāliḥ al-Sammān said: “On a Friday, I saw Abu Sa‘īd al-Khudrī praying toward something that he used as a screen from the people. A young man from Banu Abī Mu‘īṭ wanted to pass in front of him, so Abu Sa‘īd pushed him in the chest. The young man looked and found no way through except in front of him, so he came back to pass again, and Abu Sa‘īd pushed him harder than the first time. The young man spoke against Abu Sa‘īd, then went to Marwān and complained about what he faced from Abu Sa‘īd. Abu Sa‘īd entered after him to Marwān. Marwān said: ‘What is between you and your nephew, O Abu Sa‘īd?’ He said: ‘I heard the Prophet ﷺ say: “If one of you prays toward something that screens him from the people, and someone wants to pass in front of him, then let him push him back; if he refuses, then let him fight him, for he is only a devil.”’”"]},"buhuth":{"en":["“مساغاً (masāghan)” means: a path/opening he could pass through.","“فإنما هو شيطان (for he is only a devil)” means: his qareen (devil companion) that commands him toward evil—as will come in the hadith of ‘Abdullah ibn ‘Umar.","“فليقاتله (then let him fight him)” means: push him back/repel him. It is a command of recommendation, not obligation.","Al-Nawawī said: “I do not know anyone among the jurists who said this repelling is obligatory; rather, our scholars explicitly stated that it is recommended, not mandatory.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (509)، ومسلم ( 505)."},{"num":2540,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا كَانَ أَحَدُكُمْ يُصلِّي فَلَا يدعْ أَحَدًا يمرُّ بَيْنَ يَدَيْهِ، فَإِنْ أَبَى فَلْيُقَاتِلْهُ، فإنّ مَعَهُ الْقَرِينَ ."],"takhrij":"صحيح: أخرجه مسلم في الصلاة (506) عن هارون بن عبدالله ومحمد ابن رافع كلاهما عن محمد بن إسماعيل بن أبي فديك.","grade":"صحيح","chapter_ar":"باب منعُ المارِّ بين يدي المصلي","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nMuslim (506)","chapter_en":"Preventing someone from passing in front of the one praying","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":8,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar reported that the Messenger of Allah ﷺ said: “If one of you is praying, then do not let anyone pass in front of him. If he refuses, then fight him, for with him is the qareen (devil companion).”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: أخرجه مسلم (506)."},{"num":2541,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي، فَمَرَّتْ شَاةٌ بَيْنَ يَدَيْهِ، فَسَاعَاهَا إِلَى الْقِبْلَةِ حَتَّى أَلْزَقَ بَطْنُهُ بِالْقِبْلَةِ."],"takhrij":"صحيح: رواه ابن خزيمة (827)، وابن حبان (2371)، والحاكم (934) كلهم من طريق جرير بن حازم، عن يعلى بن حكيم والزبير بن خِرِّيت، عن عكرمة، عن ابن عباس فذكر مثله.","grade":"صحيح","chapter_ar":"باب منعُ المارِّ بين يدي المصلي","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nIbn Khuzaymah (827), Ibn Hibban (2371), al-Hakim (1/254)","chapter_en":"Preventing someone from passing in front of the one praying","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":8,"content":{"translation":{"en":["Ibn ‘Abbas reported that the Prophet ﷺ was praying when a sheep passed in front of him, so he moved along with it toward the qiblah until he pressed his belly against the qiblah (direction/limit)."]},"buhuth":{"en":["“Sā‘āhā (ساعاها)” means: he moved quickly along with it and outpaced it in that movement until he pressed his belly to the qiblah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة (827)، وابن حبان (2371)، والحاكم (934)."},{"num":2542,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ: هَبَطْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ ثَنِيَّةِ أَذَاخِرَ، فَحَضَرَتِ الصَّلاَةُ - يَعْنِي - فَصَلَّى إِلَى جِدَارٍ فَاتَّخَذَهُ قِبْلَةً، وَنَحْنُ خَلْفَهُ، فَجَاءَتْ بَهْمَةٌ تَمُرُّ بَيْنَ يَدَيْهِ. فَمَا زَالَ يُدَارِئُهَا حَتَّى لَصِقَ بَطْنُهُ بِالْجِدَارِ. وَمَرَّتْ مِنْ وَرَائِهِ. أَوْ كَمَا قَالَ مُسَدَّدٌ."],"takhrij":"حسن: رواه أبو داود (708) حدثنا مسدد، حدثنا عيسى بن يونس، حدثنا هشام بن الغاز، عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب منعُ المارِّ بين يدي المصلي","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (708)","chapter_en":"Preventing someone from passing in front of the one praying","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":8,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb, from his father, from his grandfather, said: “We came down with the Messenger of Allah ﷺ from Thaniyyat Adhākhir. The prayer time arrived—meaning he prayed facing a wall and took it as his qiblah—while we were behind him. Then a young lamb (bahmah) came passing in front of him. He kept gently turning it away until he pressed his belly against the wall, and it passed behind him,” or as Musaddad said."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (708)."},{"num":2543,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الله بْنِ زَيْدٍ وَأَبِي بَشِيرٍ الْأَنْصَارِيِّ، أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى بِهِمْ ذَاتَ يَوْمٍ، فَمَرَّتْ امْرَأَةٌ بِالْبَطْحَاءِ، فَأَشَارَ إِلَيْهَا رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تَأَخَّرِي، فَرَجَعَتْ حَتَّى صَلَّى، ثُمَّ مَرَّتْ."],"takhrij":"حسن: رواه الإمام أحمد (21888) عن علي بن إسحاق، حدثنا عبد الله (هو ابن المبارك)، حدثنا ابن لهيعة، حدثني حَبّان بن واسع، عن أبيه، عن عبد الله بن زيد وأبي بشير الأنصاري فذكراه.","grade":"حسن","chapter_ar":"باب منعُ المارِّ بين يدي المصلي","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (21888)","chapter_en":"Preventing someone from passing in front of the one praying","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":8,"content":{"translation":{"en":["From ‘Abdullah ibn Zayd and Abu Bashir al-Ansari: the Messenger of Allah ﷺ prayed with them one day, and a woman passed at al-Bathā’. The Messenger of Allah ﷺ gestured to her: “Move back.” So she went back until he finished praying, then she passed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (21888)."},{"num":2544,"demo":false,"sanad":"","matn":["عَنْ بُسْرِ بْنِ سَعِيدٍ، أَنَّ زَيْدَ بْنَ خَالِدٍ، أَرْسَلَهُ إِلَى أَبِي جُهَيْمٍ يَسْأَلُهُ: مَاذَا سَمِعَ مِنْ، رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمَارِّ بَيْنَ يَدَىِ الْمُصَلِّي؟ فَقَالَ أَبُو جُهَيْمٍ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَوْ يَعْلَمُ الْمَارُّ بَيْنَ يَدَىِ الْمُصَلِّي مَاذَا عَلَيْهِ؟ لَكَانَ أَنْ يَقِفَ أَرْبَعِينَ خَيْرًا لَهُ مِنْ أَنْ يَمُرَّ بَيْنَ يَدَيْهِ.","قال أبو النَّضْر: لا أدري: قال أربعين يوماً، أو شهراً، أو سنةً؟."],"takhrij":"متفق عليه: رواه مالك في قصر الصلاة (34) عن أبي النَّضْرِ مولى عمر ابن عبيدالله، عن بُسْر بن سعيد فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب إثمُ المارِّ بين يدي المصلي","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (34), al-Bukhari (510), Muslim (507)","chapter_en":"The sin of passing in front of the one praying","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":9,"content":{"translation":{"en":["Busr ibn Sa‘id reported that Zayd ibn Khalid al-Juhani sent him to Abu Juhaym to ask: “What did you hear from the Messenger of Allah ﷺ about someone passing in front of a person praying?” Abu Juhaym said: The Messenger of Allah ﷺ said: “If the one who passes in front of a person praying knew what is upon him, then standing (waiting) for forty would be better for him than passing in front of him.” Abu al-Nadr said: “I do not know whether he said forty days, or months, or years.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (34)، والبخاري (510)، ومسلم (507)."},{"num":2545,"demo":false,"sanad":"","matn":["عَنْ سَهْلٍ، قَالَ: كَانَ بَيْنَ مُصَلَّى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَبَيْنَ الْجِدَارِ مَمَرُّ الشَّاةِ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (496)، ومسلم في الصلاة (508) كلاهما من طريق عبد العزيز بن أبي حازم، عن أبيه، عن سهل بن سعد الساعدي فذكره.","grade":"متفق عليه","chapter_ar":"باب قَدْرُ ما ينبغي أن يكون بين المصلي والسترة؟","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (496), Muslim (508).","chapter_en":"How much space there should be between the worshipper and the sutrah","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":10,"content":{"translation":{"en":["Sahl ibn Sa‘d said: “Between the prayer-place of the Messenger of Allah ﷺ and the wall there was the space of a sheep’s passage.”"]},"buhuth":{"en":["And in the wording of Abu Dawud (696): “Between the standing-place of the Prophet ﷺ and the qiblah was the passage-space of a goat.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (496)، ومسلم (508). وفي لفظ أبي داود (696): (( وكان بين مقام النبي ﷺ وبين القبلة ممر عنز ))."},{"num":2546,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ أَبِي حَثْمة قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِذَا صَلَّى أَحَدُكُمْ إِلَى سُتْرَةٍ فليدْنُ مِنْهَا، لاَ يَقْطَعُ الشَّيْطَانُ عَلَيْهِ صَلاَتَهُ ."],"takhrij":"صحيح: رواه أبو داود (695)، والنسائي (748) كلاهما من طريق سفيان، عن صفوان بن سُلَيم، عن نافع بن جبير، عن سهل بن أبي حثْمة فذكر مثله ولفظهما سواء، إلا أن أبا داود قال: يبلغ به النبي صلى الله عليه وسلم .","grade":"صحيح","chapter_ar":"باب قَدْرُ ما ينبغي أن يكون بين المصلي والسترة؟","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nAbu Dawud (695), al-Nasa’i (748), authenticated by Ibn Khuzaymah (803) and Ibn Hibban (2373).","chapter_en":"How much space there should be between the worshipper and the sutrah","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":10,"content":{"translation":{"en":["Sahl ibn Abi Hathmah said: The Messenger of Allah ﷺ said: “If one of you prays toward a sutrah, then let him come close to it, so that Shaytan does not cut off/disturb his prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (695)، والنسائي (748)، وصححه ابن خزيمة (803) وابن حبان (2373)."},{"num":2547,"demo":false,"sanad":"","matn":["عَنْ أَبِي جُحَيْفَةَ، قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْهَاجِرَةِ، فَصَلَّى بِالْبَطْحَاءِ الظُّهْرَ وَالْعَصْرَ رَكْعَتَيْنِ، وَنَصَبَ بَيْنَ يَدَيْهِ عَنَزَةً، وَتَوَضَّأَ، فَجَعَلَ النَّاسُ يَتَمَسَّحُونَ بِوَضُوئِهِ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (501) عن سليمان بن حرب، قال: حدثنا شعبةُ، عن الحكم، عن أبي جحيفة فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب السترة بمكة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (501), Muslim (503).","chapter_en":"The sutrah in Makkah","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب السترة","group_en":"Combined chapters on the sutrah (prayer screen)","part_no":9,"group_no":12,"chapter_no":11,"content":{"translation":{"en":["Abu Juhayfah said: “The Messenger of Allah ﷺ went out at midday, and he prayed at al-Bathā’ the Dhuhr and ‘Asr as two rak‘ahs each, and he set up an ‘anazah (a short spear) in front of him. Then he performed wudu’, and the people began wiping (seeking blessing) with his wudu’.”"]},"buhuth":{"en":["“Al-Bathā’” here means: the Bathā’ of Makkah.","Benefit: We already know there is no difference between Makkah and other places regarding the recommendation of using a sutrah for prayer. But the remaining question is: Does a person who passes in front of a praying person during severe crowding commit sin or not?","Answer: He is not sinful, because Allah the Exalted says: “So fear Allah as much as you are able.” (At-Taghābun 16).","It is extremely difficult to avoid passing in front of someone praying during intense crowding, so major scholars have issued fatwas that during severe crowding there is no problem with passing, whether in al-Masjid al-Harām or al-Masjid an-Nabawi. In that situation, repelling/pushing the passer is dropped,","And repelling is sunnah when there is open space in the mosque for people to pass without hardship.","A person praying nafl (voluntary prayers) should observe their proper etiquette. From the etiquette of the one praying:","To pray voluntary prayers at home.","If he prays in the mosque, then he should pray in a place where passing does not become difficult— and in the two Harams there are many areas and places far from crowding."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (501) ومسلم (503)."},{"num":2548,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ  أَنَّ سَائِلًا سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الصَّلَاةِ فِي الثَّوْبِ الْوَاحِدِ، فَقَالَ: أَوَلِكُلِّكُمْ ثَوْبَانِ."],"takhrij":"متفق عليه: رواه مالك في صلاة الجماعة (30) عن ابن شهاب، عن سعيد بن المسيب، عن أبي هريرة فذكره. ورواه البخاري في الصلاة (358)، ومسلم في الصّلاة (515) كلاهما من طريق مالك.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الصلاة في ثوب واحد وصفة لبسه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (30), al-Bukhari (358), Muslim (515).","chapter_en":"What has been narrated about praying in a single garment and how it is worn","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported that a man asked the Messenger of Allah ﷺ about praying in a single garment. He said: “Do all of you have two garments?”"]},"buhuth":{"en":["The Prophet ﷺ’s words “Do all of you have two garments?” show the hardship/limited means they were living with."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك ( 30)، والبخاري (358)، ومسلم ( 515)."},{"num":2549,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ يُصَلِّي أَحَدُكُمْ فِي الثَّوْبِ الْوَاحِدِ، لَيْسَ عَلَى عَاتِقَيْهِ شَىْءٌ."],"takhrij":"متفق عليه: رواه البخاري في الصّلاة (359)، ومسلم في الصّلاة (516) كلاهما من طريق أبي الزّناد، عن عبدالرحمن الأعرج، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الصلاة في ثوب واحد وصفة لبسه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (359), Muslim (516). Muslim adds: “of it (anything).”","chapter_en":"What has been narrated about praying in a single garment and how it is worn","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Prophet ﷺ said: “None of you should pray in a single garment with nothing of it on his shoulders.”"]},"buhuth":{"en":["“With nothing on his shoulders” means: he does not wear it only around his waist, and he does not fasten its ends at his hips; rather, he should drape/secure it over his shoulders so that part of the upper body is covered— even though that upper part is not ‘awrah— or because that is more effective for covering the ‘awrah. This is mentioned in al-Fath.","The majority of scholars hold that this prohibition is a matter of etiquette (adab), meaning: if he covered what is between his navel and his knees, his prayer is valid. But the Sunnah is that he prays in an izar and rida’ (lower wrap and upper garment) if he finds them. This is mentioned in Sharh as-Sunnah (2/422)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (359)، ومسلم (516). وزاد مسلم: (( منه شيء))."},{"num":2550,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ يَقُولُ: أَشْهَدُ أَنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ صَلَّى فِي ثَوْبٍ وَاحِدٍ، فَلْيُخَالِفْ بَيْنَ طَرَفَيْهِ."],"takhrij":"صحيح: رواه البخاري في الصلاة (360) عن أبي نُعيم، قال: حدثنا شيبان (هو ابن عبدالرحمن) عن يحيى بن أبي كثير، عن عكرمة. قال -أي يحيى ابن أبي كثير- سمعتُه -أو كنتُ سألتُه- قال أي عكرمة- سمعتُ أبا هُريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الصلاة في ثوب واحد وصفة لبسه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nal-Bukhari (360)","chapter_en":"What has been narrated about praying in a single garment and how it is worn","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: “I testify that I heard the Messenger of Allah ﷺ say: ‘Whoever prays in a single garment, let him bring its two ends in opposite directions (i.e., arrange it so it properly covers him and is secured).’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (360)."},{"num":2551,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ الْمُنْكَدِرِ، قَالَ: دَخَلْتُ عَلَى جَابِرِ بْنِ عَبْدِ اللَّهِ وَهُوَ يُصَلِّي فِي ثَوْبٍ مُلْتَحِفًا بِهِ، وَرِدَاؤُهُ مَوْضُوعٌ، فَلَمَّا انْصَرَفَ قُلْنَا: يَا أَبَا عَبْدِ اللَّهِ تُصَلِّي وَرِدَاؤُكَ مَوْضُوعٌ؟ قَالَ: نَعَمْ، أَحْبَبْتُ أَنْ يَرَانِي الْجُهَّالُ مِثْلُكُمْ، رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي هَكَذَا."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (370) عن عبد العزيز بن عبدالله، قال: حدثني ابن أبي الموالي، عن محمد بن المنكدر فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الصلاة في ثوب واحد وصفة لبسه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (370), Muslim (518).","chapter_en":"What has been narrated about praying in a single garment and how it is worn","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Muhammad ibn al-Munkadir said: “I entered upon Jabir while he was praying wrapped in a single garment, and his cloak (rida’) was placed aside. When he finished, we said: ‘O Abu ‘Abdillah, you pray while your rida’ is put down?’ He said: ‘Yes. I wanted the ignorant people like you to see me. I saw the Prophet ﷺ pray like this.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (370)، ومسلم (518)."},{"num":2552,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ الله قَالَ: كُنْتُ مَعَ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ فَانْتَهَيْنَا إِلَى مَشْرَعَةٍ فَقَالَ: أَلاَ تُشْرِعُ يَا جَابِرُ . قُلْتُ بَلَى، قَالَ: فَنَزَلَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وأَشْرَعْتُ، قَالَ: ثُمَّ ذَهَبَ لِحَاجَتِهِ، وَوَضَعْتُ لَهُ وَضُوءًا، قَالَ: فَجَاءَ، فَتَوَضَّأَ، ثُمَّ قَامَ، فَصَلَّى فِى ثَوْبٍ وَاحِدٍ، خَالَفَ بَيْنَ طَرَفَيْهِ، فَقُمْتُ خَلْفَهُ، فَأَخَذَ بِأُذُنِي، فَجَعَلَنِى عَنْ يَمِينِهِ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين وقصرها (766: 196) عن حجاج بن الشاعر، حدثنى محمد بن جعفر المدائنى أبو جعفر، حدثنا ورقاء، عن محمد بن المنكدر، عن جابر بن عبد الله قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الصلاة في ثوب واحد وصفة لبسه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih","chapter_en":"What has been narrated about praying in a single garment and how it is worn","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Jabir ibn ‘Abdillah said: “I was with the Messenger of Allah ﷺ on a journey and we came to a watering place. He said: ‘Won’t you bring the water forth, O Jabir?’ I said: ‘Yes.’ The Messenger of Allah ﷺ got down and I brought the water. Then he went to relieve himself, and I prepared water for his wudu’. He came and performed wudu’, then stood and prayed in a single garment, with its two ends arranged opposite (i.e., wrapped in the proper way). I stood behind him, and he took hold of my ear and placed me on his right side.”"]},"buhuth":{"en":["Muslim (766, hadith no. 196 in that section)."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (766: 196)."},{"num":2553,"demo":false,"sanad":"","matn":["عن أُمِّ هَانِئٍ بنت أَبِي طَالِبٍ قـــــالت: تَقُولُ ذَهَبْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ الْفَتْحِ فَوَجَدْتُهُ يَغْتَسِلُ، وَفَاطِمَةُ ابْنَتُهُ تَسْتُرُهُ بِثَوْبٍ، - قَالَتْ: - فَسَلَّمْتُ عَلَيْهِ، فَقَالَ: مَنْ هَذِهِ. فَقُلْتُ: أُمُّ هَانِئٍ بِنْتُ أَبِي طَالِبٍ. فَقَالَ: مَرْحَبًا بِأُمِّ هَانِئٍ. فَلَمَّا فَرَغَ مِنْ غُسْلِهِ، قَامَ فَصَلَّى ثَمَانِيَ رَكَعَاتٍ مُلْتَحِفًا فِي ثَوْبٍ وَاحِدٍ، ثُمَّ انْصَرَفَ."],"takhrij":"متفق عليه: رواه مالك في كتاب قصر الصلاة (28) عن أبي النضر مولى عمر بن عبيدالله، أن أبا مرة مولى عقيل بن أبي طالب أخبره، أنه سمع أم هانئ بنت أبي طالب تقول فذكرت الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الصلاة في ثوب واحد وصفة لبسه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (28), al-Bukhari (357), Muslim (336).","chapter_en":"What has been narrated about praying in a single garment and how it is worn","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Umm Hani bint Abi Talib said: “I went to the Messenger of Allah ﷺ in the year of the Conquest and found him bathing, and his daughter Fatimah was shielding him with a cloth. I greeted him and he said: ‘Who is this?’ I said: ‘Umm Hani bint Abi Talib.’ He said: ‘Welcome, Umm Hani.’ When he finished his bath, he stood and prayed eight rak‘ahs wrapped in a single garment, then he left.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (28)، والبخاري (357)، ومسلم (336)."},{"num":2554,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ أَبِي سَلَمَةَ، أَنَّهُ رَأَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي ثَوْبٍ وَاحِدٍ، مُشْتَمِلاً بِهِ فِي بَيْتِ أُمِّ سَلَمَةَ، وَاضِعًا طَرَفَيْهِ عَلَى عَاتِقَيْهِ."],"takhrij":"متفق عليه: رواه مالك في صلاة الجماعة (29) عن هشام بن عروة، عن أبيه، عن عمر بن أبي سلمة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الصلاة في ثوب واحد وصفة لبسه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (29), al-Bukhari (354, 355, 356), Muslim (517).","chapter_en":"What has been narrated about praying in a single garment and how it is worn","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["‘Umar ibn Abi Salamah said that he saw the Messenger of Allah ﷺ praying in a single garment, wrapped in it, in the house of Umm Salamah, placing its two ends on his shoulders."]},"buhuth":{"en":["In a wording in Muslim: “wrapped in it (mutawashshiḥan)” and it does not say “mushtamilan.”","And in another wording: “wrapped (multahifan), arranging its two ends oppositely.”","“Multahif” and “mutawashshiḥ” here mean: placing the two ends in opposite directions on the shoulders—this is the same as wrapping it over the shoulders."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (29) والبخاري (354،355،356)، ومسلم (517)."},{"num":2555,"demo":false,"sanad":"","matn":["عَنْ سَهْلٍ، قَالَ: كَانَ رِجَالٌ يُصَلُّونَ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَاقِدِي أُزْرِهِمْ عَلَى أَعْنَاقِهِمْ كَهَيْئَةِ الصِّبْيَانِ، وَقَالَ لِلنِّسَاءِ: لاَ تَرْفَعْنَ رُءُوسَكُنَّ حَتَّى يَسْتَوِيَ الرِّجَالُ جُلُوسًا."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (362) حدثنا مسدد، قال: حدثنا يحيى (هو ابن سعيد القطان)، عن سفيان، قال: حدثني أبو حازم، عن سهل ابن سعد فذكره واللّفظ له، والظاهر أن فاعل قال للنساء هو النبي صلى الله عليه وسلم .","grade":"متفق عليه","chapter_ar":"باب ما جاء في الصلاة في ثوب واحد وصفة لبسه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (362), Muslim (441). And in Muslim: it says that someone said: “O women, do not raise your heads until the men raise theirs.” It was said that the speaker was Bilal, saying it by the instruction/ruling of the Prophet ﷺ. This was so that their eyes would not fall upon the men’s ‘awrah due to the tightness/shortness of their waist-wrappers.","chapter_en":"What has been narrated about praying in a single garment and how it is worn","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Sahl ibn Sa‘d said: “Men used to pray with the Prophet ﷺ with their waist-wrappers tied around their necks like the way boys do.” And he said to the women: “Do not raise your heads until the men are fully seated.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2341],"tks":"متفق عليه: رواه البخاري (362) ومسلم (441) وفيه: فقال قائل: (( يا معشر النساء لا ترفعن رؤوسكن حتى يرفع الرجال )) فقيل: القائل هو بلال قال ذلك بحكم النبي ﷺ. وكان ذلك لئلا تقع أبصارهن على عورات الرجال لضيق أزرهم."},{"num":2556,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيُّ أَنَّهُ دَخَلَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَآهُ يُصلِّي عَلَى حَصِيرٍ يَسْجُدُ عَلَيْهِ قــــــــال: وَرَأَيْتُهُ يصلِّي فِي ثوبٍ وَاحِدٍ متوشِّحاً بِهِ ."],"takhrij":"صحيح: رواه مسلم في الصّلاة (519) من طريق الأعمش، عن أبي سفيان، عن جابر، قال: حدثني أبو سعيد الخدريّ فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الصلاة في ثوب واحد وصفة لبسه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nMuslim (519). And in another wording: “placing its two ends on his shoulders.”","chapter_en":"What has been narrated about praying in a single garment and how it is worn","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said that he entered upon the Prophet ﷺ and saw him praying on a mat, prostrating on it. He said: “And I saw him praying in a single garment, wrapped around himself.”"]},"buhuth":{"en":["“Mushtamil,” “mutawashshiḥ,” and “arranging its two ends oppositely” all carry one meaning here.","Ibn as-Sikkit said: Tawashshuḥ is when a person takes the end of the cloth that he placed on his right shoulder from under his left arm, and takes the end that he placed on his left shoulder from under his right arm, then ties them together on his chest.","And in this is proof of the permissibility of praying in a single garment."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (519). وفي رواية: (( واضعا طرفيه على عاتقيه )."},{"num":2557,"demo":false,"sanad":"","matn":["عَنْ قَيْسِ بْنِ طَلْقٍ، عَنْ أَبِيهِ، قَالَ: قَدِمْنَا عَلَى نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَاءَ رَجُلٌ فَقَالَ: يَا نَبِيَّ اللَّهِ: مَا تَرَى فِي الصَّلاَةِ فِي الثَّوْبِ الْوَاحِدِ؟ قَالَ: فَأَطْلَقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِزَارَهُ، طَارَقَ بِهِ رِدَاءَهُ فَاشْتَمَلَ بِهِمَا، ثُمَّ قَامَ فَصَلَّى بِنَا نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمَّا أَنْ قَضَى الصَّلاَةَ قَالَ: أَوَكُلُّكُمْ يَجِدُ ثَوْبَيْنِ."],"takhrij":"حسن: أخرجه أبو داود (629) عن مسدد، حدثنا ملازم بن عمرو الحنفي، حدثنا عبدالله بن بدر، عن قيس بن طلق، عن أبيه فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في الصلاة في ثوب واحد وصفة لبسه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (629), Ibn Hibban (2297).","chapter_en":"What has been narrated about praying in a single garment and how it is worn","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Qays ibn Talq, from his father, said: “We came to the Prophet ﷺ, and a man came and said: ‘O Prophet of Allah, what do you think about praying in a single garment?’ The Messenger of Allah ﷺ loosened his waist-wrapper, laid it together with his upper garment, and wrapped himself in both of them. Then he stood and led us in prayer. When he finished the prayer he said: ‘Do all of you have two garments?’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: أخرجه أبو داود (629)، وابن حبان (2297)."},{"num":2558,"demo":false,"sanad":"","matn":["عَنْ سَلَمَةَ بْنِ الأَكْوَعِ، قَالَ: قُلْتُ يَا رَسُولَ اللَّهِ، إِنِّي رَجُلٌ أَصِيدُ أَفَأُصَلِّي فِي الْقَمِيصِ الْوَاحِدِ؟ قَالَ: نَعَمْ وَازْرُرْهُ وَلَوْ بِشَوْكَةٍ."],"takhrij":"حسن: رواه أبو داود (632)، والنسائي (766) كلاهما من طريق موسى بن إبراهيم، عن سلمة بن الأكوع فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء في الصلاة في ثوب واحد وصفة لبسه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (632), al-Nasa’i (766), Ibn Khuzaymah (777–778), Ibn Hibban (2294).","chapter_en":"What has been narrated about praying in a single garment and how it is worn","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Salamah ibn al-Akwa‘ said: “I said: ‘O Messenger of Allah ﷺ, I am a hunter—may I pray in a single shirt?’ He said: ‘Yes, and button it up, even if only with a thorn.’”"]},"buhuth":{"en":["His words “and button it up” (and in another wording: “button it”) mean: tie/fasten the opening of the shirt so that your ‘awrah does not become exposed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (632)، والنسائي (766) وابن خزيمة (777،778)، وابن حبان (2294)."},{"num":2559,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: آخِرُ صَلَاةٍ صَلَّاهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَعَ الْقَوْمِ، صَلَّى فِي ثَوْبٍ وَاحِدٍ مُتَوَشِّحًا بِهِ خَلْفَ أَبِي بَكْرٍ."],"takhrij":"صحيح: رواه النسائيّ (786)، وأحمد (12617)، وابن حبان (2125)، والبيهقي في \"الدلائل\" (7/192) كلّهم من حديث حميد الطويل، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الصلاة في ثوب واحد وصفة لبسه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nal-Nasa’i (2/79), Ahmad (12617), Ibn Hibban (2125).","chapter_en":"What has been narrated about praying in a single garment and how it is worn","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Anas said: “The last prayer that the Prophet ﷺ prayed with the people, he prayed in a single garment, wrapped around himself (mutawashshiḥan), behind Abu Bakr.”"]},"buhuth":{"en":["His words “wrapped around himself (mutawashshiḥan)” mean: wrapped in his garment. Tawashshuḥ is when a person takes the end of the cloth that he placed on his right shoulder from under his left arm, and takes the end that he placed on his left shoulder from under his right arm, then ties the two ends together on his chest."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (786)، وأحمد (12617)، وابن حبان ( 2125)."},{"num":2560,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ، عَنْ أَبِيهِ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُصَلَّى فِي لِحَافٍ لاَ يَتَوَشَّحُ بِهِ، وَالآخَرُ أَنْ يُصَلَّى فِي سَرَاوِيلَ وَلَيْسَ عَلَيْكَ رِدَاءٌ."],"takhrij":"حسن: رواه أبو داود (636) قال: حدثنا محمد بن يحيى الذهلي، حدثنا سعيد بن محمد، حدثنا أبو تُميلة، حدثنا أبو المُنيب عبيدالله العتكي، عن عبدالله بن بريدة به فذكره.","grade":"حسن","chapter_ar":"باب من السنة أن يصلي في إزار ورداء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (636).","chapter_en":"From the Sunnah is that a person prays wearing an izar and a rida’.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":2,"content":{"translation":{"en":["‘Abdullah ibn Buraydah, from his father, said: “The Messenger of Allah ﷺ forbade praying in a blanket without wrapping it around oneself properly, and (he forbade) that you pray in trousers while you have no rida’ (upper garment) on you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (636)."},{"num":2561,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ الْحَارِثِ، قَالَ: سَأَلْنَا جَابِرَ بْنَ عَبْدِ اللَّهِ عَنِ الصَّلاَةِ، فِي الثَّوْبِ الْوَاحِدِ. فَقَالَ: خَرَجْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ أَسْفَارِهِ، فَجِئْتُ لَيْلَةً لِبَعْضِ أَمْرِي، فَوَجَدْتُهُ يُصَلِّي، وَعَلَىَّ ثَوْبٌ وَاحِدٌ، فَاشْتَمَلْتُ بِهِ، وَصَلَّيْتُ إِلَى جَانِبِهِ، فَلَمَّا انْصَرَفَ قَالَ: مَا السُّرَى يَا جَابِرُ. فَأَخْبَرْتُهُ بِحَاجَتِي، فَلَمَّا فَرَغْتُ قَالَ: مَا هَذَا الاِشْتِمَالُ الَّذِي رَأَيْتُ. قُلْتُ: كَانَ ثَوْبٌ. يَعْنِي ضَاقَ. قَالَ: فَإِنْ كَانَ وَاسِعًا فَالْتَحِفْ بِهِ، وَإِنْ كَانَ ضَيِّقًا فَاتَّزِرْ بِهِ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (361) عن يحيى بن صالح، حدثنا فُلَيح بن سليمان، عن سعيد بن الحارث، قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب إذا كان الثوب ضيقا يتزربه، ولا يشتمل اشتمال اليهود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (361), and Muslim (3008). And in Muslim’s wording:","chapter_en":"If the garment is tight, he should wear it as an izar, and he should not wrap himself in the manner of the Jews.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":3,"content":{"translation":{"en":["Sa‘id ibn al-Harith said: “We asked Jabir ibn ‘Abdillah about praying in a single garment.” He said: “I went out with the Prophet ﷺ on one of his journeys. One night I came for some need and found him praying. I had only one garment, so I wrapped myself in it and prayed beside him. When he finished he said: ‘What is this night-walking, O Jabir?’ So I told him my need. When I finished, he said: ‘What is this wrapping (ishtimal) that I saw?’ I said: ‘It was a garment’—meaning it was tight. He said: ‘If it is wide, then wrap yourself in it; and if it is tight, then wear it as an izar.’”"]},"buhuth":{"en":["“Then we traveled on until we came to Jabir ibn ‘Abdillah in his mosque while he was praying in a single garment wrapped in it. I stepped past the people until I sat between him and the qiblah. I said: ‘May Allah have mercy on you—are you praying in one garment while your rida’ is beside you?’ He gestured with his hand into my chest like this, spreading his fingers and curving them, and said: ‘I wanted an ignorant person like you to come in on me and see how I do it, so he would do the same.’”","Then Jabir said: “We traveled with the Messenger of Allah ﷺ in the expedition of Batn Buwaṭ…” and he mentioned his prayer with the Messenger of Allah ﷺ and said:","“I had a cloak and I wanted to place its two ends opposite, but it did not reach for me; it had fringes, so I lowered it, then arranged its two ends opposite, then bent over it to keep it in place. Then I came and stood on the left of the Messenger of Allah ﷺ. He took my hand and turned me until he placed me on his right… The Messenger of Allah ﷺ kept glancing at me while I did not realize, then I noticed. He said—gesturing with his hand—meaning: ‘Tighten/secure your waist.’ When the Messenger of Allah ﷺ finished, he said: ‘O Jabir.’ I said: ‘At your service, O Messenger of Allah.’ He said: ‘If it is wide, then place its two ends opposite; and if it is tight, then tighten it on your waist (ḥiqw).’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (361)، ورواه مسلم (3008) وفيه:."},{"num":2562,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْ قَالَ: قَالَ عُمَرُ: رَضِيَ اللَّهُ عَنْهُ إِذَا كَانَ لأَحَدِكُمْ ثَوْبَانِ فَلْيُصَلِّ فِيهِمَا، فَإِنْ لَمْ يَكُنْ إِلاَّ ثَوْبٌ وَاحِدٌ فَلْيَتَّزِرْ بِهِ، وَلاَ يَشْتَمِلِ اشْتِمَالَ الْيَهُودِ."],"takhrij":"صحيح: رواه أبو داود (635) عن سليمان بن حرب، حدثنا حمّاد بن زيد، عن أيوب، عن نافع، عن ابن عمر به فذكر مثله.","grade":"صحيح","chapter_ar":"باب إذا كان الثوب ضيقا يتزربه، ولا يشتمل اشتمال اليهود","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih","chapter_en":"If the garment is tight, he should wear it as an izar, and he should not wrap himself in the manner of the Jews.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":3,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ said—or ‘Umar said: “If one of you has two garments, then let him pray in them. If he has only one garment, then let him wear it as an izar, and do not wrap yourselves in the wrapping of the Jews.”"]},"buhuth":{"en":["Abu Dawud (635). Ibn Khuzaymah also graded it authentic (769), with the wording: “If one of you prays in one garment, let him tighten it on his waist (ḥiqw), and do not wrap yourselves like the wrapping of the Jews.”","“The wrapping of the Jews” means: that a person covers his body with the cloth and lets it hang down without lifting/adjusting its end. (As stated by al-khattabi.)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (635). وقد صححه ابن خزيمة (769) ولفظه: (( إذا صلى أحدكم في ثوب واحد فليشده على حقوه، ولا يشتمل اشتمال اليهود ))."},{"num":2563,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ لِبْسَتَيْنِ..... اشْتِمَالُ الصَّمَّاءِ، ، وَالصَّمَّاءُ: : أَنْ يَجْعَلَ ثَوْبَهُ عَلَى أَحَدِ عَاتِقَيْهِ، فَيَبْدُو أَحَدُ شِقَّيْهِ لَيْسَ عَلَيْهِ ثَوْبٌ. وَاللِّبْسَةُ الْأُخْرَى: احْتِبَاؤُهُ بِثَوْبِهِ وَهُوَ جَالِسٌ، لَيْسَ عَلَى فَرْجِهِ مِنْهُ شَيْءٌ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5820) واللفظ له، ومسلم في البيوع (1512) غير أنه لم يذكر تفسير اللبستين، كلاهما من طريق يونس، عن ابن شهاب، قال: أخبرني عامر بن سعد، أن أبا سعيد الخدري أخبره فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب النهي عن اشتمال الصمّاء في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (5820) (wording his), and Muslim (1512).","chapter_en":"Prohibition of ishtimāl al-ṣammā’ (wrapping in the “ṣammā’” manner) in prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":4,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: The Messenger of Allah ﷺ forbade two kinds of dress. The two are: ishtimāl al-ṣammā’—and ṣammā’ is that a person places his garment over one of his shoulders so that one side of his body is exposed with no garment covering it—and the other dress is: iḥtibā’ in one’s garment while sitting, with nothing of it covering the private part."]},"buhuth":{"en":["His phrase “so one of his sides becomes visible” means: his private parts may become visible. It is also said: ṣammā’ is the same as the “wrapping of the Jews,” which was forbidden in the hadith of Ibn ‘Umar—so ṣammā’ and the “wrapping of the Jews” would then carry the same meaning.","Ṣammā’ (with ṣād and a long vowel) — linguists said: it is that a person covers his body completely with the garment, not lifting any side of it, and not leaving an opening for his hand to come out. Ibn Qutaybah said: it was called “ṣammā’” because it blocks all openings, becoming like a solid rock with no crack. Jurists said: it is that a person wraps himself in the garment, then lifts one side and places it on his shoulders, so that his private parts become exposed.","Al-Nawawi said: according to the linguists’ interpretation it is disliked, because if a need arises it becomes difficult to bring one’s hand out, causing harm; and according to the jurists’ interpretation it is forbidden, due to exposure of the ‘awrah. See: Fath al-Bari (1/477)."]}},"tuhfa":{},"full":1,"dr":1,"rep":[15361],"tks":"متفق عليه: رواه البخاري (5820) واللفظ له، ومسلم (1512)."},{"num":2564,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ بَيْعَتَيْنِ، وَعَنْ لِبْسَتَيْنِ، وَعَنْ صَلَاتَيْنِ...","وَعَنِ اشْتِمَالِ الصَّمَّاءِ ، وَعَنِ الِاحْتِبَاءِ فِي ثَوْبٍ وَاحِدٍ يُفْضِي بِفَرْجِهِ إِلَى السَّمَاءِ."],"takhrij":"متفق عليه: رواه البخاري في مواقيت الصلاة (584) عن عبيد بن إسماعيل، عن أبي أسامة، عن عبيدالله، عن خُبيب بن عبدالرحمن، عن حفص بن عاصم، عن أبي هريرة قال: فذكره. ورواه في كتاب اللباس (5819) عن محمد بن بشار، حدثنا عبدالوهاب، حدثنا عبيدالله، عن خُبيب بن عبدالرحمن به نحوه.","grade":"متفق عليه","chapter_ar":"باب النهي عن اشتمال الصمّاء في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (584) and Muslim (1511).","chapter_en":"Prohibition of ishtimāl al-ṣammā’ (wrapping in the “ṣammā’” manner) in prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ forbade two types of sales, two types of dress, and two prayers:“He forbade prayer after Fajr until the sun rises, and after ʿAṣr until the sun sets; he forbade wrapping oneself in the garment in the manner of al-ṣammāʾ, and sitting with the knees drawn up while wearing only one garment in such a way that one’s private parts are exposed toward the sky; and he forbade the sales of munābadhah and mulāmasah.”"]}},"tuhfa":{},"voc":["bukhari",584],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (584)، ومسلم (1511)."},{"num":2565,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ أَسْبَلَ إِزَارَهُ فِي صَلاَتِهِ خُيَلاَءَ فَلَيْسَ مِنَ اللَّهِ فِي حِلٍّ وَلاَ حَرَامٍ."],"takhrij":"صحيح: رواه أبو داود (637) عن زيد بن أخزم، حدثنا أبو داود، عن أبي عوانة، عن عاصم، عن أبي عثمان، عن ابن مسعود فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الإسبال في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (637).","chapter_en":"Prohibition of letting the garment hang below (isbal) in prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Ibn Masʿūd reported:I heard the Messenger of Allah ﷺ say:“Whoever lets his lower garment hang down in his prayer out of pride, Allah will neither grant him His favor nor protect him from punishment.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (637)."},{"num":2566,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ السَّدْلِ فِي الصَّلاَةِ، وَأَنْ يُغَطِّيَ الرَّجُلُ فَاهُ."],"takhrij":"حسن: رواه أبو داود (643) عن محمد بن العلاء وإبراهيم بن موسى، عن عبدالله بن المبارك، عن الحسن بن ذكوان، عن سليمان الأحول، عن عطاء. قال إبراهيم: عن أبي هريرةَ فذكر الحديث.","grade":"حسن","chapter_ar":"باب النهي عن السدل في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (643), Ibn Khuzaymah (772).","chapter_en":"Prohibition of sadl in prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ forbade sadl in prayer, and that a man cover his mouth."]},"buhuth":{"en":["Sadl is letting the garment hang down until it reaches the ground; it carries the meaning of isbal (letting the garment trail), as al-Khattabi explained it.","In al-Nihayah fi Gharib al-Hadith: sadl is that a person wraps himself in his garment and keeps his hands inside it, then bows and prostrates like that; the Jews used to do this.","As for the phrase “that a man cover his mouth,” al-Khattabi said: it was a practice among the Arabs to veil the mouth with turbans, so they were forbidden from that—except if a worshipper yawns, in which case he covers his mouth then, due to the hadith that mentions it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (643)، وابن خزيمة (772)."},{"num":2567,"demo":false,"sanad":"","matn":["عَنْ أَبِي جُحَيْفَةَ قَالَ: خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حُلَّةٍ حَمْرَاءَ مشمِّراً صَلَّى بِالنَّاسِ رَكْعَتَيْنِ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (376)، ومسلم في الصلاة (503) كلاهما من طريق عمر بن أبي زائدة، عن عون بن أبي جحيفة، عن أبيه فذكره في حديث طويل.","grade":"متفق عليه","chapter_ar":"باب الصلاة في الثوب الأحمر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (376), Muslim (503).","chapter_en":"Praying in a red garment.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":7,"content":{"translation":{"en":["Abu Juhayfah said: The Prophet ﷺ came out wearing a red suit/garment, with his garment tucked up, and he led the people in two rak‘ahs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (376)، ومسلم (503)."},{"num":2568,"demo":false,"sanad":"","matn":["عَنْ رَاشِدٍ الْحِمَّانِيِّ قَالَ: رَأَيْتُ أَنَسَ بْنَ مَالِكٍ عَلَيْهِ فَرْوٌ أَحْمَرُ، فَقَالَ: كَانَتْ لُحُفَنَا عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَلْبَسُهَا، وَنُصَلِّي فِيهَا."],"takhrij":"حسن: رواه الطبراني في الأوسط –مجمع البحرين (4223) عن أحمد بن القاسم (هو ابن مساور الجوهري - ثقة)، ثنا عبيد الله بن عمر القواريري، ثنا الحسن بن حبيب بن ندبة، ثنا راشد أبو محمد الحمّاني قال: فذكره.","grade":"حسن","chapter_ar":"باب الصلاة في اللحاف","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan","chapter_en":"Praying in a blanket/cloak.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":8,"content":{"translation":{"en":["Rashid ibn Najih al-Hammānī said: I saw Anas ibn Malik wearing a red fur garment, and he said: “In the time of the Messenger of Allah ﷺ, our blankets/cloaks were such that we used to wear them and pray in them.”"]},"buhuth":{"en":["al-Tabarani in al-Awsat (as cited in Majma‘ al-Bahrayn, no. 4223)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط في مجمع البحرين (4223)."},{"num":2569,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ، قَالَ: أُهْدِيَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرُّوجُ حَرِيرٍ، فَلَبِسَهُ، فَصَلَّى فِيهِ، ثُمَّ انْصَرَفَ فَنَزَعَهُ نَزْعًا شَدِيدًا كَالْكَارِهِ لَهُ وَقَالَ: لاَ يَنْبَغِي هَذَا لِلْمُتَّقِينَ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (375)، ومسلم في اللباس (2075) كلاهما من طريق الليث، عن يزيد بن أبي حبيب، عن أبي الخير، عن عقبة بن عامر فذكره.","grade":"متفق عليه","chapter_ar":"باب من صلى في حرير ثم نزعه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (375), Muslim (2075).","chapter_en":"One who prayed wearing silk, then removed it.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":9,"content":{"translation":{"en":["‘Uqbah ibn ‘Amir said: A silk garment was gifted to the Prophet ﷺ, so he wore it and prayed in it. Then he turned away and removed it forcefully, as if disliking it, and said: “This is not befitting for the God-fearing.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (375)، ومسلم (2075)."},{"num":2570,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى فِي خَمِيصَةٍ لَهَا أَعْلاَمٌ، فَنَظَرَ إِلَى أَعْلاَمِهَا نَظْرَةً، فَلَمَّا انْصَرَفَ قَالَ: اذْهَبُوا بِخَمِيصَتِي هَذِهِ إِلَى أَبِي جَهْمٍ، وَائْتُونِي بِأَنْبِجَانِيَّةِ أَبِي جَهْمٍ، فَإِنَّهَا أَلْهَتْنِي آنِفًا عَنْ صَلاَتِي. وَقَالَ هِشَامُ بْنُ عُرْوَةَ عَنْ أَبِيهِ عَنْ عَائِشَةَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُنْتُ أَنْظُرُ إِلَى عَلَمِهَا وَأَنَا فِي الصَّلاَةِ فَأَخَافُ أَنْ تَفْتِنَنِي."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (373)، ومسلم في المساجد (556) كلاهما من حديث ابن شهاب، عن عروة، عن عائشة واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب كراهية الصلاة في ثوب له أعلام","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (373) and Muslim (556), wording in al-Bukhari.","chapter_en":"Dislike of praying in a garment that has aʿlām (patterns/markings).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":10,"content":{"translation":{"en":["‘A’ishah reported that the Prophet ﷺ prayed in a khamīṣah (a cloak) that had markings, and he glanced at its markings. When he finished, he said: “Take this khamīṣah of mine to Abu Jahm, and bring me an anbijāniyyah of Abu Jahm, for it distracted me just now from my prayer.” Hisham ibn ‘Urwah narrated from his father, from ‘A’ishah, that the Prophet ﷺ said: “I kept looking at its markings during the prayer, and I feared that it might distract/tempt me.”"]},"buhuth":{"en":["His phrase khamīṣah: it is a square cloak made of wool.","His phrase anbijāniyyah: Ibn al-Athir said in al-Nihāyah: it is a cloak attributed to Manbij, the well-known city; its bā’ is originally kasrah but is opened in the adjectival form, and the mīm is replaced with a hamzah. It is also said that it is attributed to a place called Anbijān, and that is more likely."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (373)، ومسلم (556) واللفظ للبخاري."},{"num":2571,"demo":false,"sanad":"","matn":["عن سَعِيدِ بْنِ يَزِيدَ الأزدي قَالَ: سَأَلْتُ أَنَسَ بْنَ مَالِكٍ: أَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي نَعْلَيْهِ؟ قَالَ: نَعَمْ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (386) وفي اللباس bukhari(5850)، ومسلم في المساجد (555) كلاهما من طريق أبي مَسْلَمة سعيد بن يزيد الأزدي به مثله.","grade":"متفق عليه","chapter_ar":"باب الصّلاة في النِّعال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (5850, 386) and Muslim (555).","chapter_en":"Praying in sandals.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Sa‘id ibn Yazid al-Azdi said: I asked Anas ibn Malik: “Did the Prophet ﷺ pray in his sandals?” He said: “Yes.”"]},"buhuth":{"en":["Ibn Daqiq al-‘Id considered praying in sandals to be among the rukhaṣ (concessions), not among the recommended practices.","(Author’s note:) Therefore, I did not find any scholar explicitly stating that praying in them is part of the adornment Allah commanded."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5850 ،386)، ومسلم (555)."},{"num":2572,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: لَمْ يَخْلَعِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَعْلَيْهِ فِي الصَّلَاةِ إِلَّا مَرَّةً، فَخَلَعَ الْقَوْمُ نِعَالَهُمْ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لِمَ خَلَعْتُمْ نِعَالَكُمْ؟ قَالُوا: رَأَيْنَاكَ خَلَعْتَ، فَخَلَعْنَا. فَقَالَ: إِنَّ جِبْرِيلَ عَلَيْهِ السلام أَخْبَرَنِي أَنَّ بِهِمَا قَذَرًا."],"takhrij":"حسن: رواه الطبراني في الأوسط (4305) عن عبدالله بن أحمد بن حنبل، قال: حدثني إبراهيم بن الحجاج السامي، قال: حدثنا عبدالله بن المثنى، قال: حدثنا ثمامة، عن أنس قال: فذكره.","grade":"حسن","chapter_ar":"باب الصّلاة في النِّعال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tabarani in al-Awsat (4305) and al-Bazzar in Kashf al-Astar (605).","chapter_en":"Praying in sandals.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ did not remove his sandals during prayer except once. The people then removed their sandals, so the Prophet ﷺ said: “Why did you remove your sandals?” They said: “We saw you remove yours, so we removed ours.” He said: “Jibril (Gabriel), peace be upon him, informed me that there was filth on them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (4305)، والبزار في كشف الأستار (605)."},{"num":2573,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: بَيْنَمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِأَصْحَابِهِ إِذْ خَلَعَ نَعْلَيْهِ، فَوَضَعَهُمَا عَنْ يَسَارِهِ، فَلَمَّا رَأَى ذَلِكَ الْقَوْمُ أَلْقَوْا نِعَالَهُمْ، فَلَمَّا قَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلاَتَهُ قَالَ: مَا حَمَلَكُمْ عَلَى إِلْقَائِكُمْ نِعَالَكُمْ. قَالُوا: رَأَيْنَاكَ أَلْقَيْتَ نَعْلَيْكَ فَأَلْقَيْنَا نِعَالَنَا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنَّ جِبْرِيلَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَتَانِي، فَأَخْبَرَنِي أَنَّ فِيهِمَا قَذَرًا. وَقَالَ: إِذَا جَاءَ أَحَدُكُمْ إِلَى الْمَسْجِدِ فَلْيَنْظُرْ، فَإِنْ رَأَى فِي نَعْلَيْهِ قَذَرًا، أَوْ أَذًى فَلْيَمْسَحْهُ وَلْيُصَلِّ فِيهِمَا."],"takhrij":"صحيح: رواه أبو داود (650) عن موسى بن إسماعيل، ثنا حماد، عن أبي نُعامة السعدي، عن أبي نضرة، عن أبي سعيد الخدري فذكر مثله.","grade":"صحيح","chapter_ar":"باب الصّلاة في النِّعال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nAbu Dawud (650) and Ahmad (11153). It was also authenticated by Ibn Khuzaymah (1017) and al-Hakim (1/260).","chapter_en":"Praying in sandals.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: While the Messenger of Allah ﷺ was praying with his companions, he removed his sandals and placed them to his left. When the people saw that, they threw off their sandals. When the Messenger of Allah ﷺ finished his prayer, he said: “What made you throw off your sandals?” They said: “We saw you throw off your sandals, so we threw off ours.” He said: “Jibril (Gabriel), peace be upon him, came to me and informed me that there was filth on them”—or he said: “harm.” And he said: “When one of you comes to the mosque, let him look; if he sees on his sandals filth or harm, let him wipe it off and pray in them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (650) والإمام أحمد (11153) وصححه ابن خزيمة (1017)، والحاكم."},{"num":2574,"demo":false,"sanad":"","matn":["عن شدَّاد بن أَوْسٍ عَنْ أَبِيهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَالِفُوا الْيَهُودَ، فَإِنَّهُمْ لاَ يُصَلُّونَ فِي نِعَالِهِمْ، وَلاَ خِفَافِهِمْ."],"takhrij":"حسن: رواه أبو داود (652) عن قتيبة بن سعيد، ثنا مروان بن معاوية الفزاري، عن هلال بن ميمون الرملي، عن يعلى بن شداد بن أوس، عن أبيه فذكر الحديث.","grade":"حسن","chapter_ar":"باب الصّلاة في النِّعال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (652). Ibn Hibban authenticated it (2186) and added: “the Christians.”","chapter_en":"Praying in sandals.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Shaddad ibn Aws said: The Messenger of Allah ﷺ said: “Be different from the Jews, for they do not pray in their sandals or their leather socks (khuff).”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (652)، وصححه ابن حبان (2186)، وزاد ابن حبان: (( النصارى))."},{"num":2575,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي حَافِيًا وَمُنْتَعِلاً."],"takhrij":"حسن: رواه أبو داود (653)، وابن ماجة (1038) كلاهما من طريق حسين المعلم، عن عمرو بن شعيب، عن أبيه، عن جدِّه فذكره.","grade":"حسن","chapter_ar":"باب الصّلاة في النِّعال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (653) and Ibn Majah (1038).","chapter_en":"Praying in sandals.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["‘Amr ibn Shu‘ayb, from his father, from his grandfather, said: I saw the Messenger of Allah ﷺ pray barefoot and (also) wearing sandals."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (653)، وابن ماجه (1038)."},{"num":2576,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا صَلَّى أَحَدُكُمْ فَلْيَلْبَسْ نَعْلَيْهِ، أَوْ لِيَخْلَعْهُمَا بَيْنَ رِجْلَيْهِ، وَلَا يُؤْذِ بِهِمَا غَيْرَهُ."],"takhrij":"صحيح: رواه ابن خزيمة (1009) عن يونس بن عبد الأعلى، نا ابن وهب، نا عياض بن عبدالله القرشي، وغيره، عن سعيد بن أبي سعيد المقبري، عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الصّلاة في النِّعال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nIbn Khuzaymah (1009); also narrated by Ibn Hibban (2183) and al-Hakim (1/259).","chapter_en":"Praying in sandals.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “When one of you prays, let him wear his sandals, or let him take them off and place them between his feet, and do not harm anyone with them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة (1009) وعنه رواه ابن حبان في صحيحه (2183)، والحاكم (952)."},{"num":2577,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي قَائِمًا وَقَاعِدًا، وَحَافِيًا وَمُنْتَعِلًا."],"takhrij":"حسن: رواه الإمام أحمد (7384) حدثنا سفيان، عن عبد الملك بن عُمَير، عن أبي الأوبر، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب الصّلاة في النِّعال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAhmad (7384) and al-Bazzar in Kashf al-Astar (601).","chapter_en":"Praying in sandals.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ used to pray standing and sitting, barefoot and wearing sandals."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد ( 7384) والبزار في كشف الأستار ( 601)."},{"num":2578,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْعَلَاءِ بْنِ الشِّخِّيرِ، عَنْ أَبِيهِ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي نَعْلَيْهِ."],"takhrij":"صحيح: رواه الإمام أحمد (16309) عن عبد الرزاق، حدثنا معمر، عن سعيد الجُريري، عن أبي العلاء به مثله.","grade":"صحيح","chapter_ar":"باب الصّلاة في النِّعال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nAhmad (16309) (wording his). It was authenticated by Ibn Hibban (2184).","chapter_en":"Praying in sandals.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["Abu al-‘Ala’ Yazid ibn ‘Abdullah ibn al-Shikhkhir, from his father, said: “I saw the Messenger of Allah ﷺ praying in his sandals.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (16309) واللفظ له، وصححه ابن حبان (2184)."},{"num":2579,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَشْرَبُ قَائِمًا وَقَاعِدًا، وَيُصَلِّي مُنْتَعِلًا وَحَافِيًا، وَيَنْصَرِفُ مِنَ الصَّلَاةِ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ."],"takhrij":"حسن: رواه الطبراني في الأوسط (1235) عن أحمد، قال: حدثنا يحيى بن حكيم المقدِّمُ، قال: حدثنا مُخلد بن يزيد الحراني، عن يحيى بن سعيد الأنصاري، عن عطاء، عن عائشة. فذكرت الحديث.","grade":"حسن","chapter_ar":"باب الصّلاة في النِّعال","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tabarani in al-Awsat (1235).","chapter_en":"Praying in sandals.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":11,"content":{"translation":{"en":["‘A’ishah said: I saw the Messenger of Allah ﷺ drink while standing and while sitting; and he would pray wearing sandals and barefoot; and he would turn away (after finishing the prayer) sometimes to his right and sometimes to his left."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2211,9563,14390],"tks":"حسن: رواه الطبراني في الأوسط (1235)."},{"num":2580,"demo":false,"sanad":"","matn":["عَبْدِ اللَّهِ بْنِ السَّائِبِ، قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي يَوْمَ الْفَتْحِ، وَوَضَعَ نَعْلَيْهِ عَنْ يَسَارِهِ."],"takhrij":"صحيح: رواه أبو داود (648)، والنسائي (777)، وابن ماجة (1431) كلّهم من طريق يحيى بن سعيد، عن ابن جريج قال: حدثني محمد بن عباد بن جعفر، عن عبدالله بن سفيان، عن عبدالله بن السائب فذكره.","grade":"صحيح","chapter_ar":"باب أين يضع نعليه إذا صَلّى","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nAbu Dawud (648), al-Nasa’i (778), and Ibn Majah (1431).","chapter_en":"Where to place one’s sandals when praying.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":12,"content":{"translation":{"en":["‘Abdullah ibn al-Sa’ib said: I saw the Prophet ﷺ praying on the Day of the Conquest, and he placed his sandals to his left."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (648)، والنسائي (777)، وابن ماجه ( 1431)."},{"num":2581,"demo":false,"sanad":"","matn":["عَنْ مَيْمُونَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهَا كَانَتْ تَكُونُ حَائِضًا لاَ تُصَلِّي، وهي مُفْتَرِشَةٌ بِحِذَاءِ مَسْجِدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهْوَ يُصَلِّي عَلَى خُمْرَتِهِ، إِذَا سَجَدَ أَصَابَنِي بَعْضُ ثَوْبِهِ."],"takhrij":"متفق عليه: رواه البخاري في الحيض (333) والصلاة (381)، ومسلم في الصلاة (513) كلاهما من طريق سليمان الشيباني، عن عبدالله بن شداد، قال: سمعتُ خالتي ميمونة فذكرتِ الحديث.","grade":"متفق عليه","chapter_ar":"باب الصلاة على الخُمْرة والحصير","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari in Menstruation (333) and Prayer (381), and Muslim (513).","chapter_en":"Praying on a khumrah and a mat (hasir).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":13,"content":{"translation":{"en":["Maymunah, the wife of the Prophet ﷺ, said that she would be menstruating and not praying, while lying beside the mosque of the Messenger of Allah ﷺ. He would pray on his khumrah, and when he prostrated, part of his garment would touch her."]},"buhuth":{"en":["Khumrah (with khā’ ḍammah and mīm sukun): al-Tabari said it is a small prayer mat made from palm fronds. It was called that because it covers (protects) the face and the hands from the heat and cold of the ground. If it is large, it is called a hasir (a larger woven mat)."]}},"tuhfa":{},"full":1,"dr":1,"rep":[1511],"tks":"متفق عليه: رواه البخاري (333) والصلاة (381)، ومسلم (513)."},{"num":2582,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: دعتْ جدتي مُلَيْكَةَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِطَعَامٍ فَأَكَلَ مِنْهُ، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : قُومُوا فلأُصلِّي لَكُمْ قَالَ: أَنَسٌ: فَقُمْتُ إِلَى حَصِيرٍ لَنَا قَدِ اسْوَدَّ مِنْ طُولِ مَا لُبِس فَنَضَحْتُهُ بِمَاءٍ. فَقَامَ عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وصفَفتُ أنا وَالْيَتِيمَ وَرَاءَهُ، وَالْعَجُوزُ مِنْ وَرَائِنَا فَصَلَّى رَكْعَتَيْنِ ثُمَّ انْصَرَفَ."],"takhrij":"متفق عليه: رواه مالك في قصر الصلاة في السفر (31) عن إسحاق بن عبدالله بن أبي طلحة، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب الصلاة على الخُمْرة والحصير","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (31), al-Bukhari (380), and Muslim (658).","chapter_en":"Praying on a khumrah and a mat (hasir).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":13,"content":{"translation":{"en":["Anas ibn Malik said: My grandmother Mulaykah invited the Messenger of Allah ﷺ for food and he ate. Then the Messenger of Allah ﷺ said: “Stand up, so that I may lead you in prayer.” Anas said: I went to a mat we had that had become dark from long use, and I sprinkled it with water. The Messenger of Allah ﷺ stood on it, and I and an orphan lined up behind him, and an elderly woman stood behind us. He prayed two rak‘ahs and then left."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (31) والبخاري (380)، ومسلم (658)."},{"num":2583,"demo":false,"sanad":"","matn":["عن أنس بْنِ سِيرِينَ قَالَ: سَمِعْتُ أَنَسًا، يَقُولُ: قَالَ رَجُلٌ مِنَ الأَنْصَارِ: إِنِّي لاَ أَسْتَطِيعُ الصَّلاَةَ مَعَكَ. وَكَانَ رَجُلاً ضَخْمًا، فَصَنَعَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَعَامًا، فَدَعَاهُ إِلَى مَنْزِلِهِ، فَبَسَطَ لَهُ حَصِيرًا، وَنَضَحَ طَرَفَ الْحَصِيرِ، صَلَّى عَلَيْهِ رَكْعَتَيْنِ. فَقَالَ رَجُلٌ مِنْ آلِ الْجَارُودِ لأَنَسٍ: أَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي الضُّحَى؟ قَالَ: مَا رَأَيْتُهُ صَلاَّهَا إِلاَّ يَوْمَئِذٍ."],"takhrij":"صحيح: رواه البخاري في الأذان (670) عن آدم، قال: حدثنا شعبةُ، قال: حدثنا أنس بن سيرين فذكر مثله.","grade":"صحيح","chapter_ar":"باب الصلاة على الخُمْرة والحصير","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nal-Bukhari (670).","chapter_en":"Praying on a khumrah and a mat (hasir).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":13,"content":{"translation":{"en":["Anas ibn Sirin said: I heard Anas say: A man from the Ansar said: “I cannot pray with you”—and he was a large man—so he prepared food for the Prophet ﷺ and invited him to his home. He spread out a mat for him and sprinkled water on one end of the mat, and the Prophet ﷺ prayed two rak‘ahs on it. A man from the family of al-Jarud said to Anas: “Did the Prophet ﷺ pray the Duha prayer?” He said: “I did not see him pray it except on that day.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2921],"tks":"صحيح: رواه البخاري (670)."},{"num":2584,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: حَدَّثَنَا أَبُو سَعِيدٍ الْخُدْرِيُّ  أَنَّهُ دَخَلَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوَجَدَهُ يُصَلِّي عَلَى حَصِيرٍ يَسْجُدُ عَلَيْهِ."],"takhrij":"صحيح: رواه مسلم في المساجد (661/271) من طريق الأعمش، عن أبي سفيان، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب الصلاة على الخُمْرة والحصير","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nMuslim (271/661).","chapter_en":"Praying on a khumrah and a mat (hasir).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":13,"content":{"translation":{"en":["Jabir ibn ‘Abdullah said: Abu Sa‘id al-Khudri narrated to us that he entered upon the Messenger of Allah ﷺ and found him praying on a mat on which he prostrated."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (661/271)."},{"num":2585,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي عَلَى الْخُمْرَةِ."],"takhrij":"حسن: رواه الترمذي (331) عن قتيبة، حدثنا أبو الأحوص، عن سماك بن حرْب، عن عكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب الصلاة على الخُمْرة والحصير","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan (and al-Tirmidhi said: “Hasan Sahih”)\nal-Tirmidhi (331) and Ibn Hibban (2310, 2311).","chapter_en":"Praying on a khumrah and a mat (hasir).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":13,"content":{"translation":{"en":["Ibn ‘Abbas said: The Messenger of Allah ﷺ used to pray on a khumrah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (331)، وقال الترمذي: (( حسن صحيح )). وابن حبان في صحيحه (2310 و 2311)."},{"num":2586,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سُلَيْمٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَانَ يَأْتِيهَا فَيَقِيلُ عِنْدَهَا، فَتَبْسُطُ لَهُ نِطَعًا، فَيَقِيلُ عِنْدَهَا، وَكَانَ كَثِيرَ الْعَرَقِ، فَتَجْمَعُ عَرَقَهُ، فَتَجْعَلُهُ فِي الطِّيبِ وَالْقَوَارِيرِ، قَالَتْ: وَكَانَ يُصَلِّي عَلَى الْخُمْرَةِ."],"takhrij":"صحيح: رواه أحمد (27117)، والطبراني في الكبير (25/ح 297) كلاهما من طريق وُهيب، عن أيوب، عن أبي قلابة، عن أنس، عن أم سُليم وهي والدته واللفظ لأحمد، وأما الطبراني فاقتصر على قولها: كان يصلي على الخمرة.","grade":"صحيح","chapter_ar":"باب الصلاة على الخُمْرة والحصير","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nAhmad (27117) and al-Tabarani in al-Kabir (25/122).","chapter_en":"Praying on a khumrah and a mat (hasir).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":13,"content":{"translation":{"en":["Umm Sulaym said that the Prophet ﷺ would come to her and take a midday rest at her home. She would spread a leather mat for him, and he would rest there. He used to perspire a lot, so she would collect his sweat and put it into perfume and small bottles. She said: And he used to pray on the khumrah."]},"buhuth":{"en":["The core of this hadith is in Sahih Muslim (2332), except that it does not mention praying on the mat."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (27117)، والطبراني في الكبير (25/ح 297)."},{"num":2587,"demo":false,"sanad":"","matn":["عَنْ أُمِّ حَبِيبَةَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي عَلَى الْخُمْرَةِ."],"takhrij":"صحيح: رواه أبو يعلى (7095 تحقيق الأثري) عن أبي خيثمة، حدثنا وهب بن جرير، حدثنا شعبة، عن أبي حصين، عن يحيى بن وثَّاب، عن أبي عبدالرحمن، عن أم حبيبة فذكرت مثله.","grade":"صحيح","chapter_ar":"باب الصلاة على الخُمْرة والحصير","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nAbu Ya‘la (7095) and al-Tabarani in al-Kabir (23/242).","chapter_en":"Praying on a khumrah and a mat (hasir).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":13,"content":{"translation":{"en":["Umm Habibah reported that the Prophet ﷺ used to pray on a khumrah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو يعلى (7095 تحقيق الأثري)، والطبراني في الكبير (23/242)."},{"num":2588,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي عَلَى خُمْرَةٍ، فَقَالَ: يَا عَائِشَةُ ارْفَعِي عَنَّا حَصِيرَكِ هَذَا، فَقَدْ خَشِيتُ أَنْ يَكُونَ يَفْتِنَ النَّاسَ."],"takhrij":"صحيح: رواه الإمام أحمد (26111) عن عثمان بن عمر، حدثنا يونس، عن الزهري، عن عروة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب الصلاة على الخُمْرة والحصير","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nAhmad (26111) and Ibn Khuzaymah (1011).","chapter_en":"Praying on a khumrah and a mat (hasir).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":13,"content":{"translation":{"en":["‘A’ishah reported that the Prophet ﷺ used to pray on a khumrah, and he said: “O ‘A’ishah, remove this mat of yours from us, for I fear it may tempt (mislead) the people.”"]},"buhuth":{"en":["His phrase “Remove this mat of yours from me”: al-Sindi said he means the khumrah.","And the meaning of “it may tempt the people” is that people might believe that praying on the khumrah is an established Sunnah if he were to keep doing it continuously, so he avoided persisting in it out of fear of that. And Allah knows best."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (26111) وابن خزيمة في صحيحه ( 1011)."},{"num":2589,"demo":false,"sanad":"","matn":["عن أمِّ سَلَمَةَأَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي عَلَى الْخُمْرَةِ."],"takhrij":"صحيح: رواه أبو يعلى (6848 تحقيق الأثري) عن العباس بن الوليد، حدثنا وُهيب، عن خالد، عن أبي قِلابة، عن زينب بنت أم سلمة، عن أمها أم سلمة فذكرت الحديث.","grade":"صحيح","chapter_ar":"باب الصلاة على الخُمْرة والحصير","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nAbu Ya‘la (6848).","chapter_en":"Praying on a khumrah and a mat (hasir).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":13,"content":{"translation":{"en":["Umm Salamah said: The Prophet ﷺ used to pray on a khumrah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو يعلى (6848 تحقيق الأثري)."},{"num":2590,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي عَلَى الْخُمْرَةِ، وَيَسْجُدُ عَلَيْهَا."],"takhrij":"حسن: رواه الطبراني في المعجم الكبير (13415) وفي المعجم الأوسط مجمع البحرين (705) عن أحمد بن شعيب النسائي، أنا قتيبة بن سعيد، ثنا العطاف بن خالد، عن نافع، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب الصلاة على الخُمْرة والحصير","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tabarani in al-Kabir (13415), Ibn Khuzaymah (1013), and al-Bazzar in Kashf al-Astar (608).","chapter_en":"Praying on a khumrah and a mat (hasir).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":13,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ used to pray on the khumrah and prostrate on it."]},"buhuth":{"en":["Note (wording of al-Bazzar): “He used to pray on the khumrah”—and I think he said: “and prostrate on it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (13415) وابن خزيمة (1013) والبزار في كشف الأستار (608)."},{"num":2591,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: لاَ يَقْبَلُ اللَّهُ صَلاَةَ حَائِضٍ إِلاَّ بِخِمَارٍ."],"takhrij":"صحيح: رواه أبو داود (641)، والترمذي (377)، وابن ماجة (655) كلهم من طرق عن حماد بن سلمة، عن قتادة، عن محمد بن سيرين، عن صفية بنت الحارث، عن عائشة فذكرتِ الحديث. قال الترمذي: \"هذا حديث حسن\".","grade":"صحيح","chapter_ar":"باب ما جاء في لباس المرأة في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nAbu Dawud (641), al-Tirmidhi (377) (he graded it hasan), and Ibn Majah (655).","chapter_en":"What has been reported regarding a woman’s clothing in prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يُصَلَّى فيه","group_en":"Combined chapters on what one may pray in (clothing/conditions)","part_no":9,"group_no":13,"chapter_no":14,"content":{"translation":{"en":["‘A’ishah reported that the Prophet ﷺ said: “Allah does not accept the prayer of a woman who has reached menstruating age unless she wears a head-covering (khimar).”"]},"buhuth":{"en":["The word “ha’id (حائض)” here means a woman who has reached the age of menstruation (i.e., puberty). It does not mean a woman who is currently menstruating, because a menstruating woman does not pray at all."]}},"tuhfa":{},"full":1,"dr":1,"rep":[5643],"tks":"صحيح: رواه أبو داود ( 641)، والترمذي (377) وحسنه، وابن ماجه ( 655)."},{"num":2592,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بن أَرْقَمَ قَالَ: كُنَّا لَنَتَكَلَّمُ فِي الصَّلاَةِ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، يُكَلِّمُ أَحَدُنَا صَاحِبَهُ بِحَاجَتِهِ حَتَّى نَزَلَتْ: حَافِظُوا عَلَى الصَّلَوَاتِ [ سورة الْبَقَرَةِ: 238] فَأُمِرْنَا بِالسُّكُوتِ."],"takhrij":"متفق عليه: رواه البخاري في العمل في الصلاة (1200) وفي التفسير bukhari(4534)، ومسلم في المساجد (539) كلاهما من طريق إسماعيل بن أبي خالد، عن الحارث بن شُبَيل، عن أبي عمرو الشيباني، عن زيد بن أرقم فذكره.","grade":"متفق عليه","chapter_ar":"باب نسخ الكلام في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (4534, 1200) and Muslim (539).","chapter_en":"The abrogation of speaking during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":1,"content":{"translation":{"en":["Zayd ibn Arqam said: We used to speak during the prayer in the time of the Messenger of Allah ﷺ—one of us would speak to his companion about his need—until this was revealed: “Guard strictly the prayers…” (al-Baqarah 2:238). Then we were commanded to remain silent."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4534 ،1200)، ومسلم (539)."},{"num":2593,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي صَلاَةٍ وَقُمْنَا مَعَهُ، فَقَالَ أَعْرَابِيٌّ وَهْوَ فِي الصَّلاَةِ: اللَّهُمَّ ارْحَمْنِي وَمُحَمَّدًا وَلاَ تَرْحَمْ مَعَنَا أَحَدًا. فَلَمَّا سلَّم النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِلأَعْرَابِيِّ: لَقَدْ حجَّرت وَاسِعًا يُرِيدُ رَحْمَةَ اللَّهِ."],"takhrij":"صحيح: رواه البخاري في الآداب (6010) عن أبي اليمان، أخبرنا شُعيب، عن الزهري، قال: أخبرني أبو سلمة بن عبدالرحمن، أن أبا هريرة قال فذكره.","grade":"صحيح","chapter_ar":"باب نسخ الكلام في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nal-Bukhari (6010).","chapter_en":"The abrogation of speaking during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ stood to pray and we stood with him. A Bedouin said while in prayer: “O Allah, have mercy on me and Muhammad, and do not have mercy on anyone with us.” When the Prophet ﷺ said the taslim, he said to the Bedouin: “You have restricted something vast,” meaning the mercy of Allah."]}},"tuhfa":{},"full":1,"dr":1,"rep":[10916,13913],"tks":"صحيح: رواه البخاري ( 6010)."},{"num":2594,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ قَالَ: كُنَّا نسَلِّم عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي الصَّلاَةِ فيردُّ عَلَيْنَا. فَلَمَّا رَجَعْنَا مِنْ عِنْدِ النَّجَاشِيِّ سلَّمنا عَلَيْهِ فَلَمْ يَرُدَّ عَلَيْنَا وَقَالَ: إِنَّ فِي الصَّلاَةِ شُغْلاً ."],"takhrij":"متفق عليه: رواه البخاري في العمل في الصّلاة (1199)، ومسلم في المساجد (538) كلاهما عن ابن نُمَيرٍ، حدثنا ابن فُضَيْل، حدثنا الأعمش، عن إبراهيم، عن علقمة، عن عبدالله فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب تحريم رد السلام في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1199) and Muslim (538).","chapter_en":"The prohibition of returning greetings (salam) during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":2,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud said: We used to greet the Messenger of Allah ﷺ while he was praying and he would return the greeting to us. But when we returned from (the land of) al-Najashi, we greeted him and he did not return the greeting, and he said: “Indeed, in prayer there is preoccupation.”"]},"buhuth":{"en":["Abu Dawud (924), al-Nasa’i (1221), and Ibn Hibban (2243) (who authenticated it) narrate from ‘Abdullah ibn Mas‘ud: We used to give salam during prayer and speak about our needs. Then I came to the Messenger of Allah ﷺ and greeted him, but he did not return the salam. I felt what I felt (of worry and concern). When the Messenger of Allah ﷺ finished the prayer, he said: “Allah brings about in His command whatever He wills, and Allah—Glorified and Exalted—has brought about in His command that you do not speak during the prayer.” Then he returned the salam to me.","Al-Nasa’i (1220) adds: “Do not speak except with the remembrance of Allah; and what is fitting for you is that you stand before Allah in devotion (qunut).”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1199)، ومسلم (538)."},{"num":2595,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَاجَةٍ لَهُ، فَانْطَلَقْتُ، ثُمَّ رَجَعْتُ وَقَدْ قَضَيْتُهَا، فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَلَّمْتُ عَلَيْهِ، فَلَمْ يَرُدَّ عَلَىَّ، فَوَقَعَ فِي قَلْبِي مَا اللَّهُ أَعْلَمُ بِهِ، فَقُلْتُ فِي نَفْسِي: لَعَلَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَجَدَ عَلَىَّ أَنِّي أَبْطَأْتُ عَلَيْهِ، ثُمَّ سَلَّمْتُ عَلَيْهِ فَلَمْ يَرُدَّ عَلَىَّ، فَوَقَعَ فِي قَلْبِي أَشَدُّ مِنَ الْمَرَّةِ الْأُولَى، ثُمَّ سَلَّمْتُ عَلَيْهِ فَرَدَّ عَلَىَّ فَقَالَ: إِنَّمَا مَنَعَنِي أَنْ أَرُدَّ عَلَيْكَ أَنِّي كُنْتُ أُصَلِّي. وَكَانَ عَلَى رَاحِلَتِهِ مُتَوَجِّهًا إِلَى غَيْرِ الْقِبْلَةِ."],"takhrij":"متفق عليه: رواه البخاريّ في العمل في الصّلاة (1217)، ومسلم في المساجد (540/38) كلاهما من طريق عبد الوارث بن سعيد، حدثنا كثير بن شِنْظِير، عن عطاء بن أبي رباح، عن جابر بن عبدالله فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم رد السلام في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1217) and Muslim (38/540) — wording here is that of al-Bukhari.","chapter_en":"The prohibition of returning greetings (salam) during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":2,"content":{"translation":{"en":["Jabir ibn ‘Abdullah said: The Messenger of Allah ﷺ sent me on an errand. I went and then returned after completing it. I came to the Prophet ﷺ and greeted him, but he did not return my greeting. What Allah knows best fell into my heart, and I said to myself: Perhaps the Messenger of Allah ﷺ is upset with me for being late. Then I greeted him again and he did not respond, and what fell into my heart was even stronger than the first time. Then I greeted him and he returned my greeting and said: “What prevented me from returning your greeting was that I was praying.” And he was on his riding animal, facing other than the qiblah."]},"buhuth":{"en":["Muslim’s narration (additional detail):","Jabir said: The Messenger of Allah ﷺ sent me while he was heading to Banu al-Mustaliq. I came to him while he was praying on his camel. I spoke to him, and he signaled to me with his hand like this (Zuhayr gestured with his hand). Then I spoke again, and he signaled to me like this (Zuhayr gestured with his hand toward the ground). And I could hear him reciting, nodding his head. When he finished, he said: “What did you do regarding what I sent you for? Nothing prevented me from speaking to you except that I was praying.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1217)، ومسلم (540/38). واللفظ للبخاري."},{"num":2596,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ غِرَارَ فِي صَلاَةٍ وَلاَ تَسْلِيمٍ.","قَالَ أَحْمَدُ: يَعْنِي فِيمَا أُرَى -أَنْ لاَ تُسَلِّمَ وَلاَ يُسَلَّمَ عَلَيْكَ. وَيُغَرِّرُ الرَّجُلُ بِصَلاَتِهِ فَيَنْصَرِفُ وَهُوَ فِيهَا شَاكٌّ."],"takhrij":"صحيح: رواه أبو داود (928) عن أحمد بن حنبل، حدثنا عبدالرحمن بن مهدي، عن سفيان، عن أبي مالك الأشجعي، عن أبي حازم، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب تحريم رد السلام في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nAbu Dawud (928), Ahmad (9936), and al-Hakim (1/264).","chapter_en":"The prohibition of returning greetings (salam) during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “There is no ghirār in prayer, and no (such) salām.”"]},"buhuth":{"en":["Ahmad said: As I understand it, it means: do not say salām (to others) and do not have salām said to you (while you are praying). And a person commits ghirār in his prayer when he ends it and leaves while still in doubt about it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (928)، وأحمد (9936) والحاكم (972)."},{"num":2597,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ أَنَّ رَجُلًا سَلَّمَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي الصَّلَاةِ، فَرَدَّ النَّبِيُّ إِشَارَةً، فَلَمَّا سَلَّمَ قَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّا كُنَّا نَرُدُّ السَّلَامَ فِي صَلَاتِنَا فَنُهِينَا عَنْ ذَلِكَ."],"takhrij":"حسن: رواه البزار كشف الأستار (554) عن عمر بن الخطاب السجستاني، ثنا عبدالله بن صالح، حدثني الليث، حدثني محمد بن عجلان، عن زيد بن أسلم، عن عطاء بن يسار، عن أبي سعيد الخدري فذكر مثله.","grade":"حسن","chapter_ar":"باب تحريم رد السلام في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Bazzar, Kashf al-Astar (554).","chapter_en":"The prohibition of returning greetings (salam) during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":2,"content":{"translation":{"en":["Abu Sa‘id reported that a man greeted the Messenger of Allah ﷺ while he was praying, so the Prophet ﷺ responded with a gesture. When he finished (the prayer) and gave the taslim, the Prophet ﷺ said to him: “We used to return salām during our prayer, then we were forbidden from that.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (554)."},{"num":2598,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ بْنِ الْحَكَمِ السُّلَمِيِّ، قَالَ:  بَيْنَا أَنَا أُصَلِّي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ عَطَسَ رَجُلٌ مِنَ الْقَوْمِ، فَقُلْتُ: يَرْحَمُكَ اللَّهُ، فَرَمَانِي الْقَوْمُ بِأَبْصَارِهِمْ. فَقُلْتُ: وَاثُكْلَ أُمِّيَاهْ! مَا شَأْنُكُمْ؟ تَنْظُرُونَ إِلَيَّ! فَجَعَلُوا يَضْرِبُونَ بِأَيْدِيهِمْ عَلَى أَفْخَاذِهِمْ. فَلَمَّا رَأَيْتُهُمْ يُصَمِّتُونَنِي، لَكِنِّي سَكَتُّ. فَلَمَّا صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبِأَبِي هُوَ وَأُمِّي، مَا رَأَيْتُ مُعَلِّمًا قَبْلَهُ وَلَا بَعْدَهُ أَحْسَنَ تَعْلِيمًا مِنْهُ، فَوَاللهِ! مَا كَهَرَنِي وَلَا ضَرَبَنِي وَلَا شَتَمَنِي. قَالَ: إِنَّ هَذِهِ الصَّلَاةَ لَا يَصْلُحُ فِيهَا شَيْءٌ مِنْ كَلَامِ النَّاسِ، إِنَّمَا هُوَ التَّسْبِيحُ وَالتَّكْبِيرُ وَقِرَاءَةُ الْقُرْآنِ. أَوْ كَمَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي حَدِيثُ عَهْدٍ بِجَاهِلِيَّةٍ، وَقَدْ جَاءَ اللَّهُ بِالْإِسْلَامِ وَإِنَّ مِنَّا رِجَالًا يَأْتُونَ الْكُهَّانَ! قَالَ: فَلَا تَأْتِهِمْ. قَالَ: وَمِنَّا رِجَالٌ يَتَطَيَّرُونَ! قَالَ: ذَاكَ شَيْءٌ يَجِدُونَهُ فِي صُدُورِهِمْ فَلَا يَصُدَّنَّهُمْ. - قَالَ ابْنُ الصَّبَّاحِ: فَلَا يَصُدَّنَّكُمْ -. قَالَ: قُلْتُ: وَمِنَّا رِجَالٌ يَخُطُّونَ! قَالَ: كَانَ نَبِيٌّ مِنَ الْأَنْبِيَاءِ يَخُطُّ فَمَنْ وَافَقَ خَطَّهُ فَذَاكَ. قَالَ: وَكَانَتْ لِي جَارِيَةٌ تَرْعَى غَنَمًا لِي قِبَلَ أُحُدٍ وَالْجَوَّانِيَّةِ، فَاطَّلَعْتُ ذَاتَ يَوْمٍ فَإِذَا الذِّيبُ قَدْ ذَهَبَ بِشَاةٍ مِنْ غَنَمِهَا، وَأَنَا رَجُلٌ مِنْ بَنِي آدَمَ آسَفُ كَمَا يَأْسَفُونَ لَكِنِّي صَكَكْتُهَا صَكَّةً، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَظَّمَ ذَلِكَ عَلَيَّ. قُلْتُ: يَا رَسُولَ اللَّهِ، أَفَلَا أُعْتِقُهَا؟ قَالَ: ائْتِنِي بِهَا. فَأَتَيْتُهُ بِهَا فَقَالَ لَهَا: أَيْنَ اللهُ؟. قَالَتْ: فِي السَّمَاءِ. قَالَ: مَنْ أَنَا؟ قَالَتْ: أَنْتَ رَسُولُ اللَّهِ. قَالَ: أَعْتِقْهَا فَإِنَّهَا مُؤْمِنَةٌ."],"takhrij":"صحيح: رواه مسلم في المساجد (537) عن أبي جعفر محمد الصباح وأبي بكر بن أبي شيبة، قالا: حدثنا إسماعيل بن إبراهيم، عن حجاج الصوَّاف، عن يحيى بن أبي كثير، عن هلال بن أبي ميمونة، عن عطاء بن يسار، عن معاوية بن الحكم السلمي فذكر مثله.","grade":"صحيح","chapter_ar":"باب كراهية تشميت العاطس في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"","chapter_en":"The dislikedness of saying “yarhamuk Allah” (tashmīt) to someone who sneezes during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":3,"content":{"translation":{"en":["Mu‘awiyah ibn al-Hakam al-Sulami said: While I was praying with the Messenger of Allah ﷺ, a man among the people sneezed, so I said: “May Allah have mercy on you.” The people stared at me. I said: “Woe to my mother! What is wrong with you—why are you looking at me?” Then they began striking their hands on their thighs. When I saw them trying to silence me, I kept quiet. When the Messenger of Allah ﷺ finished the prayer—may my father and mother be ransomed for him—I never saw a teacher before him or after him better in teaching than him. By Allah, he did not scold me, nor hit me, nor insult me. He said: “This prayer is not appropriate for anything from people’s speech. It is only glorification (tasbih), saying ‘Allāhu akbar’, and recitation of the Qur’an.” Or as the Messenger of Allah ﷺ said. I said: “O Messenger of Allah, I have only recently left the time of ignorance, and Allah has brought Islam.” “And among us are men who go to soothsayers.” He said: “Do not go to them.” “And among us are men who take omens (tatayyur).” He said: “That is something they find within their chests—so let it not stop them.” (Ibn al-Sabbah said: “So let it not stop you.”) I said: “And among us are men who draw lines (as a form of divination).” He said: “There was a prophet among the prophets who would draw lines; whoever’s drawing matches his, then that is it.” He said: I had a slave-girl who used to tend sheep for me near Uhud and al-Jawwaniyyah. One day I looked and a wolf had taken one sheep from her flock. I am a human being—I get upset as people get upset—but I struck her once. I came to the Messenger of Allah ﷺ and that felt very serious to me. I said: “O Messenger of Allah, should I not free her?” He said: “Bring her to me.” So I brought her to him. He asked her: “Where is Allah?” She said: “In the sky.” He asked: “Who am I?” She said: “You are the Messenger of Allah ﷺ.” He said: “Free her, for she is a believer.” Muslim (537). From this hadith: the speech of someone who forgets or is ignorant does not invalidate the prayer. This was the view of ‘Abdullah ibn ‘Abbas, ‘Abdullah ibn al-Zubayr, ‘Ata’, al-Sha‘bi, Malik, al-Shafi‘i, and others. Al-Awza‘i added: If someone speaks intentionally in the prayer with something that serves the interest of the prayer—such as telling the imam to sit when he stands where sitting is required, or informing him he recited aloud where it should be silent—then his prayer is not invalidated. See: Sharh al-Sunnah (3/239–240)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (537)."},{"num":2599,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: التَّثَاؤُبُ مِنَ الشَّيْطَانِ، فَإِذَا تَثَاءَبَ أَحَدُكُمْ فَلْيَرُدَّهُ مَا اسْتَطَاعَ، فَإِنَّ أَحَدَكُمْ إِذَا قَالَ: هَا. ضَحِكَ الشَّيْطَانُ.","وفي رواية: إن الله يحب العُطاس، ويكره التثاؤُبَ. فإذا عَطَسَ فَحمِد الله فحق على كل مسلم سَمِعه أن يُشَمِّتَه ثم ذكره."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3289) عن عاصم بن علي، حدثنا ابن أبي ذئب، عن سعيد المقبري، عن أبيه، عن أبي هريرة فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب كراهية التثاؤب في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (3289); the second narration is also in al-Bukhari (6223).","chapter_en":"The dislikedness of yawning during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":4,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “Yawning is from Shaytan. If one of you yawns, let him repel it as much as he can, for if one of you says ‘ha’ (while yawning), Shaytan laughs.” And in another narration: “Allah loves sneezing and dislikes yawning. If someone sneezes and praises Allah, then it is a duty upon every Muslim who hears him to respond with tashmīt.” Then he mentioned the rest."]},"buhuth":{"en":["Also in Muslim (2994) with the wording: “Yawning is from Shaytan, so if one of you yawns, let him restrain it as much as he can.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3289)، والرواية الثانية رواه أيضا البخاري (6223)."}]);